  mansa_musa: { n: 'Mansa Musas pilegrimsreise', p: 'Timbuktu → Mekka', d: 'Malikeiserens karavane til Mekka deler ut så mye gull at prisene i Kairo synker i årevis — sannsynligvis historiens rikeste mann.' },
  magna_carta: { n: 'Magna Carta', p: 'Runnymede, England', d: 'Opprørske baroner tvinger kong Johan til å underskrive: kongen står under loven — konstitusjonelt styres stamfar.' },
