  ibn_battuta: { n: 'Ibn Battutas reiser', p: 'Tanger → hele verden', d: 'Den marokkanske juristen legger bak seg om lag 120 000 kilometer — tre ganger lenger enn Marco Polo — fra Timbuktu til Kina.' },
