  kalmar: { n: 'Kalmarunionen', p: 'Kalmar, Sverige', d: 'Dronning Margaretes diplomati kroner én konge over Danmark, Norge og Sverige (med Island og Finland i toget) — én nordisk krone i 126 år.' },
  margaret: { n: 'Margrete I', p: 'Danmark/Norge/Sverige', d: 'Kvinnen som utmanøvrerte hver eneste fyrste i Norden, samlet tre kongedømmer under én krone — og styrte dem gjennom en adoptert nevø mens hun selv beholdt den reelle makten.' },
  grunwald: { n: 'Slaget ved Grunwald (Žalgiris)', p: 'Grunwald, Polen', d: 'Jagiełło av Polen og Vytautas av Litauen utsletter Den tyske ordenen — middelalderens største slag gjør slutt på ridderordens monopol på Gud og handel i Baltikum.' },
  vytautas: { n: 'Vytautas den store', p: 'Trakai/Vilnius, Litauen', d: 'Under ham strekker storfyrstedømmet seg fra Østersjøen til Svartehavet; han dør noen dager før kroningen som konge — kronen kom for sent.' },
  black_death: { n: 'Svartedauden', p: 'Kaffa → Europa', d: 'Mongolenes beleiringskatapulter (sier folk) kaster pest inn i Kaffa; den rottebårne Yersinia pestis dreper så mellom en tredjedel og halvparten av Europas befolkning.' },
  ming: { n: 'Ming-dynastiet grunnlegges', p: 'Nanjing, Kina', d: 'Zhu Yuanzhang — tigger, munk, opprører — kaster mongolene ut og bygger Den forbudte by; Kina snur seg innover og blir storslått.' },
  zheng_he: { n: 'Zheng Hes skatteferder', p: 'Nanjing', d: 'Mingflåter på 300 skip og 27 000 mann seiler til India, Arabia og Øst-Afrika — tiår før Portugal runder Afrika.' },
  dante: { n: 'Den guddommelige komedie', p: 'Firenze', d: 'Landflyktig fra Firenze vandrer Dante gjennom helvete, skjærsilden og himmelen i diktet som gjorde italiensk til et litterært språk.' },
  joan: { n: 'Jeanne d’Arc', p: 'Orléans, Frankrike', d: 'En 17 år gammel bondejente bryter beleiringen av Orléans og kroner en konge — og brennes av engelskmennene som 19-åring.' },
