  kyiv_mohyla: { n: 'Kyiv-Mohyla-akademiet grunnlegges', p: 'Kyiv', d: 'Metropolitt Petro Mohyla slår sammen Kyivs brorskapsskole med Lavra-skolen til Kollegiet — Øst-Europas intellektuelle kraftsenter i de neste 150 årene.' },
  sahaidachny: { n: 'Petro Konasjevytsj-Sahajdatsjnyj', p: 'Kyiv', d: 'Hetmanen som gjorde kosakkene til en sjømakt — hans tsjajkaer brente Varna, Sinop og forstedene til selve Istanbul — og som ga Kyivs brorskapsskole sitt tilhold; dødelig såret ved Khotyn.' },
  khotyn_1621: { n: 'Slaget ved Khotyn', p: 'Khotyn, Ukraina', d: 'Polsk-litauiske og zaporizjzjiske styrker, under den dødssyke storhetman Chodkiewicz og Sahajdatsjnyjs kosakker, holder sultan Osman IIs langt større hær på avstand i en hel måned; til slutt underskriver begge imperier, utmattet.' },
