  pereiaslav: { n: 'Pereiaslav-avtalen', p: 'Pereiaslav, Ukraina', d: 'Khmelnytskyjs forsamling aksepterer den moskovittiske tsarens militære beskyttelse mot Polen — en pakt Moskva straks skriver om til egen fordel, og som russisk historieskrivning senere blåser opp til en mytisk «gjenforening».' },
  hetmanate: { n: 'Hetmanatet — kosakkstaten', p: 'Baturyn, Ukraina', d: 'Det selvstyrende kosakkstyret ved Dnipro: valgte hetmaner, allmenne råd, egen hær, domstoler og diplomati — navigert mellom Warszawa, Moskva og Istanbul til Katarina II avskaffer hetmanembetet.' },
