  mazepa: { n: 'Hetman Ivan Mazepa', p: 'Baturyn, Ukraina', d: 'Mecenat for kirker og for Kyiv-Mohyla-akademiet, som styrte Hetmanatet i to tiår; som 69-åring satte han alt på ett kort hos Sveriges Karl XII — og betalte med hovedstaden sin, omdømmet i Moskva og plassen sin i russisk demonologi.' },
  baturyn_sack: { n: 'Baturyns ødeleggelse', p: 'Baturyn, Ukraina', d: 'Dager etter Mazepas trekk stormer Mensjikovs moskovittiske korps kosakkhovedstaden og massakrerer garnisonen og bybefolkningen — krigens første grusomhet, og et minne Ukraina bærer helt på egen hånd.' },
  poltava: { n: 'Slaget ved Poltava', p: 'Poltava, Ukraina', d: 'Peter I knuser Karl XIIs svensker og Mazepas kosakker; Sverige trer ut av stormaktsrekken, og Hetmanatet mister friheten i utenrikspolitikken — og med den sin statsdannelse.' },
