  fr_philip_v: { n: 'Filip den lange', p: 'Paris', d: 'Overvant niesen krav med prinsippet om at kvinner ikke arver kronen — reformerte mynten, døde ved tretti.' },
  fr_charles_iv_fr: { n: 'Karl den skjønne', p: 'Paris', d: 'Den siste direkte kapetingeren: døde uten sønn og med dronningen gravid — tronfølgekrisen som åpnet hundreårskrigen.' },
  fr_philip_vi: { n: 'Filip VI av Valois', p: 'Paris', d: 'Fetteren valgt fremfor Edvard III — hvis motkrav tente hundreårskrigen; slått ved Crécy og mistet Calais (1347).' },
  fr_john_ii: { n: 'Johan den gode', p: 'Paris', d: 'Tatt til fange ved Poitiers (1356) — vendte hjem fra sitt ærerike engelske fangenskap for å dø, for en fyrste som brøt sitt ord var ingen fyrste.' },
  fr_charles_v: { n: 'Karl den vise', p: 'Paris', d: 'Gjenerobret alt med bakholdskrig og Bertrand du Guesclin — bygget Bastiljen og det kongelige biblioteket, døde mistenksom mot alle.' },
  fr_charles_vi: { n: 'Karl den gale', p: 'Paris', d: 'Den gale kongen som myrdet egne riddere i skoghallusinasjonen (1392): Frankrike splittet seg i armagnaker og burgundere — og engelskmennene kom inn.' },
  fr_henry_vi_fr: { n: 'Henrik VI av England — Frankrikes konge', p: 'Paris', d: 'Troyes-traktaten gjorde den engelske spedbarnet til Frankrikes konge (1422): ti år av dobbeltmonarki — til en bondejente fra Domrémy brøt det.' },
  fr_charles_vii: { n: 'Karl VII — vel betjent', p: 'Paris', d: 'Kronet i Reims takket være Jeanne d’Arc: avsluttet hundreårskrigen ved Castillon (1453) — utleverte Jeanne til ilden og rehabiliterte henne senere.' },
  fr_louis_xi: { n: 'Ludvig XI — den universelle edderkoppen', p: 'Paris', d: 'Lur under en slapp hatt: brøt Karl den djerve ved Nancy (1477), spant postvesenet, trykkeriet — og et nett av frykt.' },
  fr_charles_viii: { n: 'Karl VIII', p: 'Paris', d: 'Den vennlige unge kongen som invaderte Italia (1494) — døde ved tjue-åtte, slått hodet mot en dørterskel, barnløs.' },
  fr_louis_xii: { n: 'Ludvig XII — Folkets far', p: 'Paris', d: '«Sitt folks far»: giftet seg med Johan den halte og så med enken Anna av Bretagne — holdt hertugdømmet hennes, freden og skattene lave.' },
