  fr_henry_ii_fr: { n: 'Henrik II', p: 'Paris', d: 'Diane de Poitiers konge: forfulgte kjettere med den Brennende kammer — døde av en splintret lanser i øyet på datterens bryllupsturnering (1559).' },
  fr_francis_ii: { n: 'Frans II', p: 'Paris', d: 'Den skrøpelige guttekongen gift med Maria Stuart — Guise-brødrene regjerte i hans navn; døde ved seksten, en øvrebet abscess.' },
  fr_charles_ix: { n: 'Karl IX', p: 'Paris', d: 'Religionskrigenes konge — og Bartolomeusnatten (1572), som gnagde ham til dødssengen.' },
