  fr_henry_iv: { n: 'Henrik IV av Bourbon', p: 'Paris', d: '«Paris er verdt en messe»: béarnieren som konverterte for å avslutte krigen — Nantes-ediktet, høne i hver gryte, dolket av Ravaillac (1610).' },
  fr_louis_xiii: { n: 'Ludvig XIII den rettferdige', p: 'Paris', d: 'Den innelukkede kongen og kardinal Richelieu: rev ned adelens borgan og gikk inn i tredveårskrigen — døde lyttende til messe, på Kristi himmelfartsdag.' },
  fr_louis_xiv: { n: 'Ludvig XIV — solkongen', p: 'Versailles, Frankrike', d: 'Sjuetti to år på tronen: «Staten, det er meg» — Versailles bygget, dragonadenes mot hugenottene, og Europa alliert mot ham fire kriger langt.' },
