  fr_louis_xvi: { n: 'Ludvig XVI', p: 'Versailles, Frankrike', d: 'Låssmedkongen som ville være god: innkalte stenderforsamlingen og tapte kontrollen over revolusjonen — giljotinert 21. januar 1793.' },
  fr_louis_xviii: { n: 'Ludvig XVIII', p: 'Paris', d: 'Den giktkuede greven av Provence, vendt tilbake etter Napoleon: ga den konstitusjonelle charteret — regjerte gjennom de hundre dagenes avbrudd.' },
  fr_charles_x: { n: 'Karl X', p: 'Paris', d: 'Den ultra-royalistiske broren: kroning med middelalderriter, sensur og erstatninger — julirevolusjonen 1830 sendte ham i eksil.' },
  fr_louis_philippe: { n: 'Ludvig Filip I — borgerkongen', p: 'Paris', d: 'Orléans bankirkongen med paraplyen: regjerte for den borgerlige julimonarkiet — flyktet utkledd som «Mr Smith» i 1848-revolusjonen.' },
  fr_napoleon_iii: { n: 'Napoleon III', p: 'Paris', d: 'Nevøen som ble president ved valg og keiser ved folkeavstemning (1852): Haussmanns Paris, Suez-konsesjonen — og Sedan (1870).' }
