/* ── 52 tyske monarker + 39 herskere i Østerrike (2026-10-28) ── */
Object.assign(window.DATA_NO, {
  de_louis_ii_german: { n: 'Ludvig den tyske', p: 'Regensburg, Tyskland', d: 'Sønnesønn av Karl den store: traktaten i Verdun (843) gir ham Østfranken, den tyskspråklige østlige tredjedelen — det første «Kongeriket Tyskland» som eget rike.' },
  de_carloman_bavaria: { n: 'Karloman av Bayern', p: 'Regensburg, Tyskland', d: 'Eldste sønn av Ludvig den tyske: Bayern som arv, Italia og keiserkronen som erobring — et slag tar alt på fire år.' },
  de_louis_iii_younger: { n: 'Ludvig den yngre', p: 'Regensburg, Tyskland', d: 'Knuste den vestfrankiske invasjonen ved Andernach (876) — øyeblikket da Østfranken står på egne bein — og legger til vestre Lothringen; død trettitre år gammel.' },
  de_arnulf: { n: 'Arnulf av Kärnten', p: 'Regensburg, Tyskland', d: 'Den uektefødte nevøen som avsatte onkelen Karl den tykke, samlet øst mot vikinger og magyarer — og ble kronet til keiser etter å ha brutt normannenes beleiring av Leuven (891).' },
  de_louis_iv_child: { n: 'Ludvig barnet', p: 'Forchheim, Tyskland', d: 'Kronet som seksåring, den siste karolingeren i øst: magyarraidene begynner, hertugene tar makten i stillhet — dynastiet dør med ham som syttenåring.' },
  de_conrad_i: { n: 'Konrad I', p: 'Forchheim, Tyskland', d: 'Den første kongen uten karolingisk blod, valgt av hertugene — ni år med kamp mot dem, og på dødsleiet rådet han dem å velge sin sterkeste rival i stedet: Henrik av Sachsen.' },
  de_henry_i_fowler: { n: 'Henrik Fuglefangeren', p: 'Quedlinburg, Tyskland', d: 'Valgt uten kirkelig salving for å beholde hertugenes velvilje: bygget befestede byer mot magyarernes ryttere og knuste dem ved Riade (933) — grunnleggeren av ottodynastiet.' },
  de_otto_i: { n: 'Otto den store', p: 'Magdeburg, Tyskland', d: 'Temmet hertugene, knuste magyarerne ved Lechfeld (955) og ble kronet til keiser i Roma (962): Det hellige romerske rike tar til — med Magdeburg som hans elskede by.' },
  de_otto_ii: { n: 'Otto den røde', p: 'Aachen, Tyskland', d: 'Giftet seg med en bysantinsk prinsesse og drømte om et romersk-middelhavsrike — til sarasenerne tilintetgjorde hæren hans i Calabria (982); død tjueåtte år gammel.' },
  de_otto_iii: { n: 'Otto III — «verdens under»', p: 'Aachen, Tyskland', d: 'Keisergutten med bysantinske drømmer: åpnet Karl den stores grav i Aachen, holdt et temmet løve, regjerte fra Roma — død tjueen år gammel, og med ham drømmeriket.' },
  de_henry_ii: { n: 'Henrik den hellige', p: 'Bamberg, Tyskland', d: 'Den siste ottokongen: grunnla Bambergs bispedømme, drog i strid med et hellig spyd i hånden — kanonisert i 1146, den eneste tyske kongen som er blitt helgen.' },
  de_conrad_ii: { n: 'Konrad II', p: 'Speyer, Tyskland', d: 'En «liten greve» valgt for sin ventede middelmåtdighet: fornyet i stedet riket, tok Burgund og begynte Speyerdomen som keiserlig gravkirke.' },
  de_henry_iii: { n: 'Henrik III den svarte', p: 'Speyer, Tyskland', d: 'Keisermakten på sitt høydepunkt: tre rivaliserende paver avsatt i Sutri (1046), en reformert pavedom under tysk oppsyn — et autokrati som sønnen ikke skal klare å holde.' },
  de_henry_iv: { n: 'Henrik IV', p: 'Goslar, Tyskland', d: 'Gikk til Canossa (1077) — barbeint i snøen for pave Gregor VII — og kjempet tretti år til med bannlysninger, motkonger og borgerkrig; til slutt avsatt av sin egen sønn.' },
  de_henry_v: { n: 'Henrik V', p: 'Speyer, Tyskland', d: 'Tok tronen over farens brukne kropp, kjempet deretter samme investiturkrigen — og avsluttet den med Wormskonkordatet (1122): kirke og rike, skilt.' },
  de_lothar_ii: { n: 'Lothar av Supplinburg', p: 'Goslar, Tyskland', d: 'Valgt mot stauferne, ledet en pavelig hær til Roma og døde på veien hjem fra Italia — og lot welferne og stauferne slakte arvefølgen i en generasjon.' },
  de_conrad_iii: { n: 'Konrad III', p: 'Nürnberg, Tyskland', d: 'Den første stauferkongen: dro på det annet korstoget som brøt sammen ved Dorylaion, beleiret hjemme sine welfiske rivaler — den eneste kongen i sin tid som aldri nådde noen keiserkroning i Roma.' },
  de_frederick_barbarossa: { n: 'Fredrik Barbarossa', p: 'Nürnberg, Tyskland', d: 'Rødskjegget og utmattelsesløs: kanoniserte Karl den store, førte fem italienske tog frem til nederlaget ved Legnano (1176) og druknet i elven Saleph på det tredje korstoget — hans skjegg sover under Kyffhäuser, Tysklands keiser som en dag skal vende tilbake.' },
  de_henry_vi: { n: 'Henrik VI', p: 'Worms, Tyskland', d: 'Barbarossas arving: tok Sicilia i et lynangrep, holdt Rikard Løvehjerte for løsepenge, manglet lite på å gjøre keiserkronen arvelig — død tretti to år gammel og etterlot et tre år gammelt barn og et splittet rike.' },
  de_philip_swabia: { n: 'Filip av Schwaben', p: 'Bamberg, Tyskland', d: 'Hans dobbeltvalg delte Tyskland i to kongedømmer — Filips side holdt rikdommen i sør, til en krenket slektning myrdet ham ved et bryllupsgjestebud (1208).' },
  de_otto_iv: { n: 'Otto IV', p: 'Braunschweig, Tyskland', d: 'Welferen som til slutt beseiret Filip, likevel bannlyst og fikk hæren knust av Frankrike ved Bouvines (1214) — den siste welferkeiseren, berøvet alt av sine egne kurfyrster.' },
  de_frederick_ii: { n: 'Fredrik II — «verdens under»', p: 'Palermo, Italia', d: 'Konge av Sicilia, «verdens under»: seks språk, den første vitenskapen om falkoneri, et hoff av arabiske, greske og jødiske lærde — fire ganger bannlyst, tok han Jerusalem med en traktat (1229) og døde på jakt: middelalderens siste keiser.' },
  de_conrad_iv: { n: 'Konrad IV', p: 'Nürnberg, Tyskland', d: 'Valgt under fars levetid og likevel aldri noen virkelig konge: kjempet for et Tyskland og et Sicilia han ikke kunne holde, døde av malaria tjueseks år gammel — slektens ende åpner det store interregnum.' },
  de_rudolf_i: { n: 'Rudolf av Habsburg', p: 'Habsburg-slottet, Sveits', d: 'Den lille greven, valgt for å avslutte det store interregnum: beseiret Ottokar av Böhmen ved Marchfeld, ga Østerrike til sønnene — og gjorde «Habsburg» til navnet på Europas neste seks århundrer.' },
  de_adolf_nassau: { n: 'Adolf av Nassau', p: 'Nassau, Tyskland', d: 'Kurfyrstenes kompromisskonge: kjøpte stemmer med løfter, pantsatte riksbyer til England for penger — slått og drept av Albrekt av Habsburg ved Göllheim (1298).' },
  de_albert_i: { n: 'Albrekt I', p: 'Wien, Østerrike', d: 'Rudolfs arving og Østerrikes herre: en hard, dyktig konge — skattene hans drev de sveitsiske skogkantonene til opprør, og hans egen nevø drepte ham ved Reuss med en dolk (1308).' },
  de_henry_vii: { n: 'Henrik VII', p: 'Luxembourg', d: 'Luxemburgeren som vakte keiserdrømmen til live: red inn i Italia, kronet i Roma (1312) — frelseren Dante ventet på — døde i feber i Toscana førti år gammel, rike og drøm ufullendte.' },
  de_louis_iv_bavaria: { n: 'Ludvig den bayerske', p: 'München, Tyskland', d: 'Bannlyst for tross mot paven, svarte med et manifest: keisere svarer bare for Gud — Marsilius og Ockham skrev saken ved hoffet hans, tidens første store politiske teorier; døde på en bjørnejakt.' },
  de_charles_iv: { n: 'Karl IV', p: 'Praha, Böhmen', d: 'Luxemburgernes gylne sønn og Böhmens konge: gjorde Praha til rikshovedstad, grunnla universitetet der (1348), skrev den gylne bullen (1356) — rikets arbeidsgrunnlov i 450 år.' },
  de_wenceslaus: { n: 'Venceslaus IV', p: 'Praha, Böhmen', d: 'Böhmens konge og keiser til navnet: slumret gjennom det store skismaet mens riket styrte seg selv — den eneste romerske kongen som kurfyrstene rett og slett stemte ut (1400).' },
  de_rupert: { n: 'Ruprecht av Pfalz', p: 'Heidelberg, Tyskland', d: 'Wittelsbacheren valgt i Venceslaus’ sted: ærlig, fattig og uten penger — hans italienske felttog falt fra hverandre uten sold, og han ble begravet i Heidelberg-kirken han selv hadde latt bygge.' },
  de_sigismund: { n: 'Sigismund', p: 'Buda, Ungarn', d: 'Den siste luxemburgeren, Ungarns konge: sammenkalte konsilet i Konstanz (1414) som helbredet skismaet — og brente Jan Hus, og tente de husittiske krigene som åt fem korstog.' },
  de_frederick_iii: { n: 'Fredrik III', p: 'Wien, Østerrike', d: 'A.E.I.O.U.-keiseren: femtitre år på tronen, de fleste av dem med tap — han overlevde hver rival, flyttet hoffet til Wien og vant halve Europa ved å gifte sønnen med Burgunds arving.' },
  de_maximilian_i: { n: 'Maximilian I — den siste ridderen', p: 'Innsbruck, Østerrike', d: 'Landsknektene, artilleriet og egenpropagandaen: tok Burgund ved ekteskap og giftet barnebarna til Spania, Böhmen og Ungarn — «Bella gerant alii, tu felix Austria nube.»' },
  de_charles_v: { n: 'Karl V', p: 'Gent, Flandern', d: 'Et rike der solen aldri gikk ned — Spania, Amerika, Nederlandene, Tyskland: kjempet mot Frankrike og osmanene, møtte Luther i Worms (1521) — og trakk seg utmattet tilbake til et kloster og delte habsburgernes arv i to.' },
  de_ferdinand_i: { n: 'Ferdinand I', p: 'Wien, Østerrike', d: 'Karls bror og Østerrikes statholder: etter Mohács (1526) tok han til seg Ungarns og Böhmens kroner, holdt tyrkerne ved Wiens dør — grunnleggeren av den østerrikske habsburglinjen.' },
  de_maximilian_ii: { n: 'Maximilian II', p: 'Wien, Østerrike', d: 'Den tolerante humanisten: holdt bekjennelsene i fred med studert utydelighet, holdt protestanter ved sitt wienerhov — og manglet lite på å lukke kløften mellom Østerrikes og Spanias habsburgere med et dobbeltbryllup som aldri helt ble av.' },
  de_rudolf_ii: { n: 'Rudolf II', p: 'Praha, Böhmen', d: 'Alkymist-keiseren: flyttet hoffet til Praha og samlet Tycho, Kepler, Arcimboldo og Europas fineste kunstkammer — mens Ungarn brant og familien presset ham inn på Hradschin.' },
  de_matthias: { n: 'Matthias', p: 'Wien, Østerrike', d: 'Broren som tok Rudolfs kroner i et familiekupp: hans regjeringstid var fred — og generalenes ettergifter i Böhmen lunten på tredveårskrigen, tent i Praha i 1618.' },
  de_ferdinand_ii: { n: 'Ferdinand II', p: 'Graz, Østerrike', d: 'Styriaren med jesuittoppdragelsen: nektet Böhmens vilkår, vant Det hvite fjell (1620), lanserte Restitutionsediktet — en krig om bekjennelsen, betalt av en tredjedel av Tysklands folk.' },
  de_ferdinand_iii: { n: 'Ferdinand III', p: 'Wien, Østerrike', d: 'Kommanderte selv i felt gjennom de tapte tiårene, og undertegnet deretter Westfalenfreden (1648): de tyske statene får suverenitet, riket et tomt skall — og Europa det moderne statssystemet.' },
  de_leopold_i: { n: 'Leopold I', p: 'Wien, Østerrike', d: 'Barokkkeiseren med habsburgkjeven: førtisju år med kriger mot Ludvig XIV og to osmanske beleiringer — Wien reddet av Sobieski (1683), Ungarn gjenerobret, og god musikk ved hoffet av keiserens eget komponering.' },
  de_joseph_i: { n: 'Josef I', p: 'Wien, Østerrike', d: 'Den energiske arvingen: knuste Rákóczis ungarske opprør, vant Blenheim (1704) ved Marlboroughs side — en lovende regjeringstid, død av kopper tretti to år gammel.' },
  de_charles_vi: { n: 'Karl VI', p: 'Wien, Østerrike', d: 'Den siste mannlige habsburgeren: kjempet et tiår for å bevise at Spania ikke var hans, og brukte deretter regjeringstiden på den pragmatiske sanksjonen — alle naboer signerte den, og alle naboer brøt ordet måneder etter hans død.' },
  de_charles_vii: { n: 'Karl VII', p: 'München, Tyskland', d: 'Wittelsbacheren som tok kronen mens Maria Teresia holdt sverdene: valgt bak franske bajonetter, kronet i Frankfurt — død i løpet av tre år, egen Bayern okkupert av østerrikske tropper.' },
  de_francis_i_lorraine: { n: 'Frans I Stefan', p: 'Wien, Østerrike', d: 'Lothringen byttet mot Toscana, deretter Maria Teresias gemal og keiser: skarp i finanser og statsmonopoler, far til seksten barn — partnerskapet som bar den habsburgske staten.' },
  de_joseph_ii: { n: 'Josef II', p: 'Wien, Østerrike', d: 'Revolusjonæren på tronen: avskaffet livegenskapen, stengte halvparten av klostrene, gjorde tysk til statsspråk, tolererte hver tro — «Jeg har gjort filosofien til lovgiver i mitt rike»; ti år med dekret, de fleste opphevet til slutt.' },
  de_leopold_ii: { n: 'Leopold II', p: 'Firenze, Italia', d: 'Storhertugen av Toscana som avskaffet dødsstraffen — den første staten noensinne — tok deretter imot et brennende rike i 1790, dempet Ungarn og Nederlandene, og døde mens den franske stormen samlet seg.' },
  de_francis_ii: { n: 'Frans II / I', p: 'Wien, Østerrike', d: 'Den siste tysk-romerske keiseren — han oppløste det tusenårige riket i 1806 under Napoleons ånde — og den første keiseren av Østerrike: Napoleons beseirede svigerfar, Metternichs reaksjonære herre, førtitre år med orden og politi.' },
  de_wilhelm_i: { n: 'Vilhelm I', p: 'Berlin, Tyskland', d: 'Den prøyssiske kongen som aldri ville ha et rike — og fikk det: tre kriger bygget av Bismarck — Danmark, Østerrike, Frankrike — og proklamasjonen til tysk keiser i Speilsalen i Versailles, syttifire år gammel.' },
  de_frederick_iii_german: { n: 'Fredrik III — de nittini dagene', p: 'Potsdam, Tyskland', d: 'Den liberale kronprinsen, tvunget til å vente på farens langlevdhet: halskreften tok «Fredrik den gode» før han rakk å liberalisere riket — Tysklands vei som ikke ble tatt.' },
  de_wilhelm_ii: { n: 'Vilhelm II', p: 'Potsdam, Tyskland', d: 'Keiseren med den atroferte armen og flottedrømmen: sparket Bismarck, sprang «Weltpolitik» inn i innringingen, rakte Østerrike den tomme sjekken — og abdiserte til nederlandsk eksil mens riket han hadde provosert fram kollapset.' },

  at_burkhard: { n: 'Burkhard', p: 'Melk, Østerrike', d: 'Markgreve av Donaumarken mot magyarerne etter Ottos seier ved Lechfeld — fradømt sin stilling for å ha støttet et bayersk opprør, hans østmark gitt til babenbergerne.' },
  at_leopold_i: { n: 'Leopold I den berømte', p: 'Melk, Østerrike', d: 'Første babenbergske markgreve: belønnet for lojalitet i den bayerske krigen — slekten som skal herske over Østerrike de neste 270 årene, med begynnelse i Melk ved Donau.' },
  at_henry_i_mg: { n: 'Henrik I', p: 'Melk, Østerrike', d: 'Den stille andre markgreven: trettifire år med bosetninger, befestninger og klostre mellom Enns og Wienerwald — et markgrevskap som blir et land.' },
  at_adalbert: { n: 'Adalbert den seierrike', p: 'Melk, Østerrike', d: 'Beseiret ungarerne ved Morava og drev grensen frem til Leitha — elven som ennå i dag er Østerrikes østgrense.' },
  at_ernst_mg: { n: 'Ernst den tapre', p: 'Melk, Østerrike', d: 'Falt ved Langensalza (1075), kjempende for keiser Henrik IV mot de saksiske opprørerne — legenden ga ham et sverd for tungt for vanlige menn: Østerrikes første heltedikt.' },
  at_leopold_ii_mg: { n: 'Leopold II den vakre', p: 'Melk, Østerrike', d: 'Stilte seg på pavens side i investiturkrigen og mistet sitt markgrevskap i tre år — og grunnla benediktinerstiftet Melk (1089), ennå i dag barokk-Østerrikes emblem.' },
  at_leopold_iii_mg: { n: 'Leopold III den fromme', p: 'Klosterneuburg, Østerrike', d: 'Sin tids fredsbygger, to ganger kongemaker: grunnla stiftet Klosterneuburg for sin brud Agnes — en keiserdatter — og ble helgenkåret som Østerrikes landspatron.' },
  at_leopold_iv_mg: { n: 'Leopold IV', p: 'Klosterneuburg, Østerrike', d: 'Fikk Bayern som staufisk krigsbytte og forente de to landene for første gang — død trettitre år gammel og etterlot alt til broren Henrik.' },
  at_henry_ii_jasomirgott: { n: 'Henrik II Jasomirgott', p: 'Wien, Østerrike', d: 'Den siste markgreven, den første hertugen: Privilegium Minus (1156) gjør Østerrike til et arvelig hertugdømme — døtre regnet med — fri fra Bayern, og Wien blir residensby; hans ed «jas mir got» («ja, så hjelpe meg Gud») ble til navnet hans.' },
  at_leopold_v: { n: 'Leopold V den dydige', p: 'Wien, Østerrike', d: 'Gav Østerrike det rød-hvitt-røde flagget — forteller legenden, fra tunikaen hans gjennomsøyt av blod ved Akko — og fanget Rikard Løvehjerte nær Wien (1192): løsepengene gjenreiste Wiens murer og reiste Wiener Neustadt.' },
  at_friedrich_i_austria: { n: 'Fredrik I av Østerrike', p: 'Wien, Østerrike', d: 'Bar farens korstogsskyld til det hellige landet i bot for Richards fangst — døde i Akko tjuetre år gammel; hertugdømmet gikk til onkelen.' },
  at_leopold_vi: { n: 'Leopold VI den ærerike', p: 'Wien, Østerrike', d: 'Wien blir gotisk, minnesangen kommer til hoffet — Walther og Neidhart synger ved hans gjestebud — og hertugen meklar mellom keisere og paver: babenberg-Østerrikes gyldne aftenstund.' },
  at_friedrich_ii_austria: { n: 'Fredrik II den stridbare', p: 'Wiener Neustadt, Østerrike', d: 'Den siste babenbergeren: kranglet med alle naboene på én gang og ble bannlyst om og om igjen — falt ved Leitha mot magyarerne, uten arving, og Europas fyrster begynner å kretse rundt Østerrike.' },
  at_gertrude: { n: 'Gertrud av Babenberg', p: 'Wiener Neustadt, Østerrike', d: 'Arvingen alle ville gifte seg med: et annullert ekteskap, en død ektemann, en fyrste fra Galicia — og ingen av dem hindret Ottokar av Böhmen i å ganske enkelt ta hertugdømmet.' },
  at_roman_danylovych: { n: 'Roman Danilovitsj av Galicia', p: 'Hainburg, Østerrike', d: 'Sønn av kong Daniel av Galicia: ved å gifte seg med babenberg-arvingen Gertrud holdt den rutenske fyrsten Østerrikes grenseland med farens kavaleri — den eneste arvingen Galicia-Volhynia noen gang satte på en vestlig trone — til Böhmen og paven feide forbundet bort.' },
  at_ottokar_ii: { n: 'Ottokar II av Böhmen', p: 'Wien, Østerrike', d: '«Jern- og gullkongen»: skar ut Østerrike, Steiermark og den adriatiske kysten av babenberg-arven — til Rudolf av Habsburg kom for å hente den og drepte ham ved Marchfeld (1278).' },
  at_rudolf_iii_austria: { n: 'Rudolf III den godmodige', p: 'Wien, Østerrike', d: 'Medhertug under faren Albrekt I, deretter med habsburgsk våpenmakt konge av Böhmen — død atten år gammel, og den bøhmiske kronen ble begravet med ham.' },
  at_friedrich_handsome: { n: 'Fredrik den vakre', p: 'Wien, Østerrike', d: 'Habsburgeren som ble nektet riket: valgt til konge mot Ludvig den bayerske, slått ved Mühldorf (1322) og fengslet — løslatt under en edsvoren vennskap med fangevokteren, til Tysklands forundring; styrte Østerrike godt til det siste.' },
  at_albert_ii_wise: { n: 'Albrekt II den vise', p: 'Wien, Østerrike', d: 'Den halte, giktrammede hertugen som tre ganger takket nei til den tyske kronen og beskyttet sine jøder under pestpogromene (1349) — Østerrike holdt sitt eget råd, og velstanden fortsatte å vokse.' },
  at_rudolf_iv: { n: 'Rudolf IV grunnleggeren', p: 'Wien, Østerrike', d: 'Et forfalsket diplom, et universitet og et gotisk skip: fant opp tittelen erkehertug (Privilegium Maius), grunnla Wiens universitet (1365), begynte Stephansdomens skip — en stat større enn sine papirer; døde i Milano tjueseks år gammel.' },
  at_albert_iii: { n: 'Albrekt III med fletta', p: 'Wien, Østerrike', d: 'Delte huset Habsburg med broren i Neuberg (1379): Albrekt beholdt Østerrike selv — den albertinske linjen som skal legge til Ungarn, Böhmen og en stund riket selv.' },
  at_leopold_iii_leopoldin: { n: 'Leopold III av den leopoldinske linjen', p: 'Graz, Østerrike', d: 'Fikk Indre Østerrike, Tirol og de vestlige forlandene, og begjærte etter Sveits — knust ved Sempach av de edsvorne (1386), slaget om Winkelrieds selvoppofrelse: Østerrikes sveitsiske drøm døde med ham.' },
  at_wilhelm_austria: { n: 'Vilhelm av Østerrike', p: 'Wien, Østerrike', d: 'Forlovet med den unge dronning Jadwiga av Polen — hun tok imot midnattsbesøket hans med en øks, Polen valgte Jagiełło, og bryllupet som ville ha forent Østersjøen med Donau ble aldri av; han styrte slektens vestlige land fra Wien.' },
  at_leopold_iv_leopoldin: { n: 'Leopold IV', p: 'Wien, Østerrike', d: 'Den edru midtbroren: styrte de spredde leopoldinske landene, holdt formynderskapet over Tirol og Ungarns anliggender — døde i Wien, og slektens krangler delte landene hans på nytt bak ryggen hans.' },
  at_albert_iv: { n: 'Albrekt IV den tålmodige', p: 'Wien, Østerrike', d: 'Hertug ved tjueto, død ved tjuesju: besvanger seg med luxemburgerne og holder den albertinske linjen rolig mens leopoldinerne krangler — sønnen hans, Albrekt V, skal få Ungarn, Böhmen og en sjanse på riket.' },
  at_albert_v: { n: 'Albrekt V — habsburgernes første krone', p: 'Wien, Østerrike', d: 'Gift med Sigismunds datter arvet han Ungarn og Böhmen med henne, og ble deretter valgt til tysk konge (1438) — den første habsburgske keiserkronen; døde førtito år gammel i felttog mot tyrkerne og etterlot en ennå ufødt sønn.' },
  at_ladislaus_posthumous: { n: 'Ladislaus Postumus', p: 'Wien, Østerrike', d: 'Født fire måneder etter farens død — derav navnet: som barn konge av Ungarn og Böhmen, myndling av ungareren Hunyadi og bøhmeren Poděbrady — døde plutselig sytten år gammel i Praha og avsluttet den albertinske linjen.' },
  at_ernst_iron: { n: 'Ernst den jernharde', p: 'Graz, Østerrike', d: 'Kranglet med broren om Tirol og med keiser Sigismund om Ungarn — «den jernharde», hvis sønn Fredrik V skal arve nesten alt og bære keiserkronen.' },
  at_friedrich_iv_tyrol: { n: 'Fredrik IV med den tomme veska', p: 'Innsbruck, Østerrike', d: 'Hjalp motpaven Johannes XXIII å flykte fra Konstanz og ble derfor fredløs: flyktet fra Tirol som en enkel mann, kom tilbake — og gjorde Innsbruck til et virkelig godt lite hoff; kallenavnet festet seg for alltid.' },
  at_sigismund_tyrol: { n: 'Sigismund av Tirol', p: 'Innsbruck, Østerrike', d: 'Prente Europas første store sølvtalere fra Schwaz-gruvene, kranglet med alle naboene — og overlot til slutt Tirol til fetteren Maximilian: den leopoldinske linjen slutter med ham.' },
  at_ferdinand_ii_tyrol: { n: 'Ferdinand II av Tirol', p: 'Innsbruck, Østerrike', d: 'Giftet seg med Philippine Welser, en augsburgsk borgerdatter, mot alle husets regler — og bygde for henne og sitt kunstkammer slottet Ambras, ett av renessansens underverker; Tirols gullalder slutter med ham.' },
  at_karl_ii_styria: { n: 'Karl II av Indre Østerrike', p: 'Graz, Østerrike', d: 'Indre Østerrikes fredsskapende hersker: toleranseavtaler med de protestantiske stendene, et universitet i Graz (1585) — hvis jesuitter siden oppdro sønnen hans, Ferdinand II, til å gjenerobre Böhmen for Roma.' },
  at_leopold_v_tyrol: { n: 'Leopold V av For-Østerrike', p: 'Innsbruck, Østerrike', d: 'Biskop av Strasbourg og Passau som forlot alteret for den tirolske kronen: holdt sine små land gjennom tredveårskrigen med små, kloke hærer — og giftet seg med Claudia de’ Medici for at linjen skulle leve.' },
  at_ferdinand_karl: { n: 'Ferdinand Karl', p: 'Innsbruck, Østerrike', d: 'Erkehertugen gal etter opera: åpnet det første stående hoffteatret nord for Alpene (1654) og pantsatte sølvet til italienske sangere — gjelden tømte kassa, og Tirol drev stille mot Wien.' },
  at_sigismund_franz: { n: 'Sigismund Frans', p: 'Innsbruck, Østerrike', d: 'Biskop av tre stifter som sa fra seg alle for å gifte seg og redde den tirolske linjen — døde i feber dager etter bryllupet trettini år gammel: Tirol går tilbake til Wien-habsburgerne, den siste selvstendige herskeren drar med ham.' },
  at_maria_theresa: { n: 'Maria Teresia', p: 'Wien, Østerrike', d: 'Den eneste kvinnen som noensinne har hersket over habsburglandene: kronet under Ungarns hurrarop som tjuetreåring, Schlesien tapt til Fredrik — deretter skoler, hær, skatter og livegne reformert, seksten barn oppdratt: «Europas svigermor».' },
  at_ferdinand_i_emp: { n: 'Ferdinand I den velvillige', p: 'Wien, Østerrike', d: 'Den epileptiske keiseren som knapt kunne skrive navnet sitt mens Metternich styrte — begge feid bort av Wiens barrikader i 1848; Ferdinand abdiserte til fordel for nevøen sin og levde lykkelig som hageeier i Praha i ytterligere tjuesei år.' },
  at_franz_joseph: { n: 'Frans Josef I', p: 'Wien, Østerrike', d: 'Sekstioåtte år, monarkiets grå anker: opp i daggry, ved skrivebordet klokka fire — tapte enhver krig han førte, en hustru til en anarkists fil, en bror til en meksikansk eksekusjonspeloton, en arving i Sarajevo — og regjerte videre: den siste premoderne monarken i et moderne rike.' },
  at_karl_i: { n: 'Karl I', p: 'Wien, Østerrike', d: 'Den siste keiseren: arvet total krigen og prøvde total freden — hemmelige fredssonderinger, en forbundsplan for sine nasjoner — for sent og for svak; forvist til Madeira, død av lungebetennelse trettifire år gammel, saligkåret av kirken i 2004.' },
});

/* jp translations — Emperors of Japan (added 2026-10-28) */
Object.assign(window.DATA_NO, {
  jp_jimmu: { n: 'Jimmu', p: 'Kashihara, Japan', d: 'Legendarisk første keiser, oldebarn av solgudinnen Amaterasu; Japan daterer sin ubrokne keiserlinje fra hans tronbestigelse — tradisjonelt 660 f.Kr.' },
  jp_suizei: { n: 'Suizei', p: 'Asuka, Japan', d: 'Andre keiser — tradisjonens første registrerte kronprins; en av de tidlige monarkene som ingen uavhengige bevis er bevart fra.' },
  jp_annei: { n: 'Annei', p: 'Asuka, Japan', d: 'Tredje legendariske keiser; krønikene husker bare palasset hans i Kawachi og en regjeringstid på trettioåtte år.' },
  jp_itoku: { n: 'Itoku', p: 'Asuka, Japan', d: 'Fjerde legendariske keiser; husket fremfor alt gjennom slektslistene — linjen hans løper ubrutt til dagens keiser.' },
  jp_kosho: { n: 'Kōshō', p: 'Asuka, Japan', d: 'Femte legendariske keiser; ingenting fra hans tid lar seg verifisere — historikerne plasserer de første sikre datoene et årtusen senere.' },
  jp_koan: { n: 'Kōan', p: 'Asuka, Japan', d: 'Sjette legendariske keiser, tilskrevet en regjeringstid på 101 år — ett av flere umulig lange tidsrom i de tidlige kongelistene.' },
  jp_korei: { n: 'Kōrei', p: 'Asuka, Japan', d: 'Sjuende legendariske keiser; tradisjonen sier at moren hans var den første keiserinnen født utenfor kongsslekten.' },
  jp_kogen: { n: 'Kōgen', p: 'Asuka, Japan', d: 'Den åttende av de «udokumenterbare» keiserne; etter regjeringstiden hans blir krønikene merkbart mer detaljerte.' },
  jp_kaika: { n: 'Kaika', p: 'Asuka, Japan', d: 'Niende og siste av de tidlige keiserne hvis regjeringstider hviler utelukkende på slektslistene.' },
  jp_sujin: { n: 'Sujin', p: 'Asuka, Japan', d: 'Halvlegendarisk «rikets første hersker»: krønikene tilskriver ham de første provinsguvernørene og Ise-helligdommens linje.' },
  jp_suinin: { n: 'Suinin', p: 'Asuka, Japan', d: 'Under ham, sier tradisjonen, ble begravelse av levende tjenere erstattet av haniwa-leirfigurene — og den første sumokampen ble utkjempet.' },
  jp_keiko: { n: 'Keikō', p: 'Asuka, Japan', d: 'Den legendariske keiseren i Yamato Takeru-sagnet — sønnens felttog i øst fyller Japans eldste heltediktning.' },
  jp_seimu: { n: 'Seimu', p: 'Asuka, Japan', d: 'Legendarisk keiser, tilskrevet å organisere de store hoffslektene i arvelige embeter for første gang.' },
  jp_chuai: { n: 'Chūai', p: 'Asuka, Japan', d: 'Døde på felttog på Kyūshū; enken hans, Jingū, ledet deretter hoffet gjennom en berømt — og mytisk — erobring av Korea.' },
  jp_ojin: { n: 'Ōjin', p: 'Naniwa (Osaka), Japan', d: 'Halvlegendarisk beskytter av vevare, skrivere og hester fra kontinentet; tilbedt etter sin død som Hachiman, krigsguden.' },
  jp_nintoku: { n: 'Nintoku', p: 'Naniwa (Osaka), Japan', d: 'Sies å hvile i Daisen Kofun — en nøkkelhullgrav med større grunnflate enn Kheopspyramiden i Giza; verdens største grav i areal.' },
  jp_richu: { n: 'Richū', p: 'Kawachi, Japan', d: 'Den første av de magre 400-tallsregjeringene; krønikene bevarer fra hans tid bare tronfølgestridene og palassstedene.' },
  jp_hanzei: { n: 'Hanzei', p: 'Kawachi, Japan', d: '400-tallskeiser hvis brødre kjempet om arvefølgen — et vindu mot det tidlige Yamatos voldelige hoffpolitikk.' },
  jp_ingyo: { n: 'Ingyō', p: 'Kawachi, Japan', d: 'En lang regjeringstid husket for straffen mot adelige som forfalsket de første husstandslistene — og for arvefølgekaoset som fulgte.' },
  jp_anko: { n: 'Ankō', p: 'Kawachi, Japan', d: 'Myrdet i søvne av en adelsmann hvis kone han hadde krevd — Japans første registrerte keisermord.' },
  jp_yuryaku: { n: 'Yūryaku', p: 'Kawachi, Japan', d: 'En mektig og fryktet konge; kinesiske annaler kan føre ham opp som «kong Bu», som ba om støtte mot sine egne rivaler ved hoffet.' },
  jp_seinei: { n: 'Seinei', p: 'Kawachi, Japan', d: 'Yūryakus sønnesønn; fem stille år — så gikk tronen til sønnene av onkelen Yūryaku hadde drept.' },
  jp_kenso: { n: 'Kensō', p: 'Kawachi, Japan', d: 'Regjerte knapt to år; 700-tallets kompilatorer klarte bare å huske palasset hans og den tidlige døden hans.' },
  jp_ninken: { n: 'Ninken', p: 'Kawachi, Japan', d: 'Gjennom døtrenes ekteskap ble hans slekt knyttet til Keitais — alle senere keisere stammer fra det forbundet.' },
  jp_buretsu: { n: 'Buretsu', p: 'Kawachi, Japan', d: 'Maltegnet av krønikene som en grusom guttekonge; hans barnløse død endte den direkte linjen og brakte Keitai til tronen.' },
  jp_keitai: { n: 'Keitai', p: 'Omi, Japan', d: 'Vokst opp langt fra hoffet i Ōmi; tronbestigelsen hans gjorde ham til en annen slektsgrunnlegger — alle senere keisere stammer fra ham.' },
  jp_ankan: { n: 'Ankan', p: 'Kawachi, Japan', d: 'Regjerte fire år; kildene forteller mest om palassene og vannverkene hans, ikke om politikk.' },
  jp_senka: { n: 'Senka', p: 'Kawachi, Japan', d: 'Hans død brakte den unge halvbroren Kinmei til tronen — stamfaren til alle senere keisere.' },
  jp_kinmei: { n: 'Kinmei', p: 'Asuka, Japan', d: 'Den første keiseren kildene lar oss datere med sikkerhet; buddhismen kom til hoffet fra Paekche i hans regjeringstid (552).' },
  jp_bidatsu: { n: 'Bidatsu', p: 'Asuka, Japan', d: 'Hoffkampene om buddhismen tilspisset seg under ham; Iwai-opprøret satte Yamatos grep om Kyūshū på prøve.' },
  jp_yomei: { n: 'Yōmei', p: 'Asuka, Japan', d: 'En hengiven konvertitt, død innen to år; arvefølgestriden som fulgte, ga den reelle makten til Soga-slekten.' },
  jp_sushun: { n: 'Sushun', p: 'Asuka, Japan', d: 'Satt på tronen av Soga, drept av dem da han vendte seg mot buddhismens beskyttere.' },
  jp_suiko: { n: 'Suiko', p: 'Asuka, Japan', d: 'Japans første regjerende keiserinne; med riksforstanderen Shōtoku Taishi sendte hun de første utsendingene til Sui-Kina og var buddhismens forkjemper.' },
  jp_jomei: { n: 'Jomei', p: 'Asuka, Japan', d: 'Åpnet offisielle forbindelser med Tang-Kina (630) — de første kentōshi-ekspedisjonene som skulle forme japansk statskunst på nytt.' },
  jp_kogyoku: { n: 'Kōgyoku', p: 'Naniwa (Osaka), Japan', d: 'Andre regjerende keiserinne; hoffet hennes ble veltet av Isshi-hendelsen i 645, statskuppet bak Taika-reformene.' },
  jp_kotoku: { n: 'Kōtoku', p: 'Naniwa (Osaka), Japan', d: 'Taika-reformens keiser: avskaffet arvelige gods, utropte et sentralisert rike og regjerte fra den nye hovedstaden Naniwa (Osaka).' },
  jp_saimei: { n: 'Saimei', p: 'Asuka, Japan', d: 'Kōgyoku gjeninnsatt under nytt navn; hun døde mens hun rustet ut en flåte for å redde den allierte Paekche fra Tang og Silla.' },
  jp_tenji: { n: 'Tenji', p: 'Otsu, Japan', d: 'Etter at Japans flåte ble utslettet ved Paekchon (663) lot han utarbeide den første skriftlige lovsamlingen og flyttet hoffet til Ōtsu.' },
  jp_kobun: { n: 'Kōbun', p: 'Otsu, Japan', d: 'Døde i Jinshin-krigen — arvefølgestriden mot onkelen Tenmu som avgjorde slektens framtid.' },
  jp_tenmu: { n: 'Tenmu', p: 'Asuka, Japan', d: 'Vant Jinshin-krigen og regjerte med en kraft uten sidestykke; fikk skrevet de første rikshistoriene og ga buddhismen statsstøtte.' },
  jp_jito: { n: 'Jitō', p: 'Asuka, Japan', d: 'Tredje regjerende keiserinne — Tenmus enke og politiske arving; under henne ble den planlagte hovedstaden Fujiwara-kyō grunnlagt.' },
  jp_monmu: { n: 'Monmu', p: 'Fujiwara-kyō, Japan', d: 'Sønnesønn av Tenmu og Jitō; hans regjeringstid lanserte Japans første kinesisk-stilte planlagte hovedstad og Taihō-lovenes æra.' },
  jp_genmei: { n: 'Genmei', p: 'Nara, Japan', d: 'Fjerde regjerende keiserinne; fikk Kojiki sammenstilt og flyttet hoffet til Heijō-kyō (Nara) i 710.' },
  jp_gensho: { n: 'Genshō', p: 'Nara, Japan', d: 'Femte regjerende keiserinne, en stabiliserende riksforstander mellom halvsøsterens og nevøens regjeringstider; Ritsuryō-staten modnet.' },
  jp_shomu: { n: 'Shōmu', p: 'Nara, Japan', d: 'Fikk reist den kjempestore bronsebuddhaen i Tōdaiji; hans pestherjede regjeringstid gjorde buddhismen til statens skjold.' },
  jp_koken: { n: 'Kōken', p: 'Nara, Japan', d: 'Sjette regjerende keiserinne; innviet Tōdaiji-buddhaen og overlevde fetterens opprør mens en ministers makt vokste rundt henne.' },
  jp_junnin: { n: 'Junnin', p: 'Nara, Japan', d: 'Satt av etter tre år og sendt for å dø i eksil på Awaji da den abdiserte keiserinnen Kōken tok tilbake hoffet.' },
  jp_shotoku: { n: 'Shōtoku', p: 'Nara, Japan', d: 'Kōkens andre regjeringstid; munken Dōkyō kom et orakelsvar fra tronen — den store skandalen i Nara-buddhismen.' },
  jp_konin: { n: 'Kōnin', p: 'Nara, Japan', d: 'Brakte Tenjis slektslinje tilbake til tronen; hoffet hans, på vakt mot Naras templer, begynte å planlegge en ny hovedstad.' },
  jp_kanmu: { n: 'Kanmu', p: 'Kyoto, Japan', d: 'Energisk reformator som flyttet hovedstaden to ganger og endte i Heian-kyō (794) — Kyotos tolvhundreårige historie begynner.' },
  jp_heizei: { n: 'Heizei', p: 'Kyoto, Japan', d: 'Abdiserte etter tre år, forsøkte å dra hoffet tilbake til Nara — opprøret hans ble knust av broren Saga.' },
  jp_saga: { n: 'Saga', p: 'Kyoto, Japan', d: 'Seierherren i opprøret i 810, dikterkeiser og beskytter av Kūkai; hans regjeringstid satte tonen for den raffinerte Heian-kulturen.' },
  jp_junna: { n: 'Junna', p: 'Kyoto, Japan', d: 'En sparsommelig, boklært keiser som fremmet Kūkais Shingon-skole og strammet inn ritsuryō-budsjettene.' },
  jp_ninmyo: { n: 'Ninmyō', p: 'Kyoto, Japan', d: 'Hoffets Jōwa-hendelse (842) renskåret det gamle gardet — utrensningen som åpnet veien til Fujiwara-overherredømmet.' },
  jp_montoku: { n: 'Montoku', p: 'Kyoto, Japan', d: 'En kort, rolig regjeringstid husket som sprangbrettet til Fujiwara Yoshifusa — neste ut som riksforstander for en barnkeiser.' },
  jp_seiwa: { n: 'Seiwa', p: 'Kyoto, Japan', d: 'Kronet åtte år gammel under bestefaren Yoshifusa — den første barnkeiseren og det første ekte Fujiwara-riksforstanderskapet.' },
  jp_yozei: { n: 'Yōzei', p: 'Kyoto, Japan', d: 'Satt av sytten år gammel etter uforutsigbar vold; manøveren som trengtes for å erstatte ham, rystet regentenes egne regler.' },
  jp_koko: { n: 'Kōkō', p: 'Kyoto, Japan', d: 'Løftet opp femtifem år gammel som en medgjørlig nødløsning; med ham ble tronen åpenbart Fujiwara Mototsunes premie.' },
  jp_uda: { n: 'Uda', p: 'Kyoto, Japan', d: 'Støttet seg på ikke-Fujiwara-ministere for å balansere regentene, og trakk seg tidlig tilbake til et klosterliv ved Ninna-ji.' },
  jp_daigo: { n: 'Daigo', p: 'Kyoto, Japan', d: '«Engi»-tidens gullalder — direkte styre uten regenter; glansen sprakk da Sugawara Michizane ble forvist og døde.' },
  jp_suzaku: { n: 'Suzaku', p: 'Kyoto, Japan', d: 'En barnkeiser mens opprørene til Taira no Masakado og Fujiwara Sumitomo rystet riket (Jōhei–Tengyō-æraen).' },
  jp_murakami: { n: 'Murakami', p: 'Kyoto, Japan', d: 'Den siste regjeringstiden med direkte keisermakt — «Tenryaku no chi», husket som Heian-kulturen på sitt mest trygge.' },
  jp_reizei: { n: 'Reizei', p: 'Kyoto, Japan', d: 'Dårlig helse og partistrid: hans korte regjeringstid så Anna-hendelsen, utrensningen som styrket Fujiwara Kanemichi.' },
  jp_enyu: { n: 'En’yū', p: 'Kyoto, Japan', d: 'Kronet elleve år gammel under Fujiwara-formynderskap; rundt ham stivnet riksforstanderskapet til rutine.' },
  jp_kazan: { n: 'Kazan', p: 'Kyoto, Japan', d: 'Dyktig og alvorlig, men utmanøvrert av Fujiwara Kaneie; abdiserte nitten år gammel og avla klosterløfter ved Ninna-ji.' },
  jp_ichijo: { n: 'Ichijō', p: 'Kyoto, Japan', d: 'Heian-prakten på sitt høyeste: Fujiwara Michinagas oppgang, Sei Shōnagons Putebok og Murasaki Shikibus Genji ved hoffet.' },
  jp_sanjo: { n: 'Sanjō', p: 'Kyoto, Japan', d: 'En øyesykdom og Fujiwara Michinagas press tvang ham til å abdisere — hans egne sønner ble fullstendig hoppet over.' },
  jp_go_ichijo: { n: 'Go-Ichijō', p: 'Kyoto, Japan', d: 'Sønn av Michinagas datter; med broren Go-Suzaku tilhørte tronen Fujiwaraene mer enn noen gang.' },
  jp_go_suzaku: { n: 'Go-Suzaku', p: 'Kyoto, Japan', d: 'En rolig regjeringstid under Fujiwara Yorimichi; hoffkulturen nådde sin topp mens ordenen i provinsene eroderte i stillhet.' },
  jp_go_reizei: { n: 'Go-Reizei', p: 'Kyoto, Japan', d: 'Barnløs; arvefølgestriden mellom rivaliserende Fujiwara-grener begynte skredet mot hoffdrevne kriger.' },
  jp_go_sanjo: { n: 'Go-Sanjō', p: 'Kyoto, Japan', d: 'Den første keiseren på 170 år med en ikke-Fujiwara-mor; han tok igjennom tømmene på godsene som mettet regentenes rikdom.' },
  jp_shirakawa: { n: 'Shirakawa', p: 'Kyoto, Japan', d: 'Abdiserte for å herske over regentene i fire tiår — hans inseistyre ble rikets nye maktsentrum.' },
  jp_horikawa: { n: 'Horikawa', p: 'Kyoto, Japan', d: 'Barnkeiser under Shirakawas inseistyre; hoffkulturen — diktning, malerkunst, antologier — blomstret videre.' },
  jp_toba: { n: 'Toba', p: 'Kyoto, Japan', d: 'Abdiserte seksten år gammel og dominerte deretter inseipolitikken i tiår; hans to husstander bevæpnet de kommende borgerkrigene.' },
  jp_sutoku: { n: 'Sutoku', p: 'Kyoto, Japan', d: 'Tvingt til å abdisere; hans forsøk på å vende tilbake i 1156 utløste Hōgen-krigen, og han døde som forvist i Sanuki.' },
  jp_konoe: { n: 'Konoe', p: 'Kyoto, Japan', d: 'Døde tjuetre år gammel; kappløpet om arvefølgen hans gav fyr på Hōgen-krigen året etter.' },
  jp_go_shirakawa: { n: 'Go-Shirakawa', p: 'Kyoto, Japan', d: 'Laget det skjebnesvangre kompromisset av 1155; som klosterkeiser overlevde han Taira og sjakkmattet de første shōgunene i tiår.' },
  jp_nijo: { n: 'Nijō', p: 'Kyoto, Japan', d: 'Kom i sammenstøt med den klosterlevende faren sin; Heiji-opprøret (1160) utslettet Minamoto Yoshitomo og løftet Taira Kiyomori til overmakt.' },
  jp_rokujo: { n: 'Rokujō', p: 'Kyoto, Japan', d: 'Kronet som spedbarn, avsatt tre år gammel av Taira Kiyomori — tydelig bevis på hvor hoffmakten nå lå.' },
  jp_takakura: { n: 'Takakura', p: 'Kyoto, Japan', d: 'Kiyomoris svigersønn; abdiserte for å sette småbarnet Antoku, med Tairablod i årene, på tronen — og riket kokte over.' },
  jp_antoku: { n: 'Antoku', p: 'Kyoto, Japan', d: 'Tairas guttekeiser druknet ved Dan-no-ura (1185) da slektens flåte falt — sagnet sier at keisersverdet sank med ham.' },
  jp_go_toba: { n: 'Go-Toba', p: 'Kyoto, Japan', d: 'Dikter og beskytter av den andre keiserlige diktantologien; ledet senere hoffets siste væpnede oppgjør mot Kamakura — Jōkyū-krigen (1221) — og døde i eksil på Oki.' },
  jp_tsuchimikado: { n: 'Tsuchimikado', p: 'Kyoto, Japan', d: 'Regjerte under Minamoto- og Fujiwara-oppsyn; forvist etter farens mislykkede Jōkyū-krig, døde han langt borte i Awa.' },
  jp_juntoku: { n: 'Juntoku', p: 'Kyoto, Japan', d: 'Sluttet seg til faren Go-Tobas opprør mot shōgunene; forvist til Sado etter nederlaget.' },
  jp_chukyo: { n: 'Chūkyō', p: 'Kyoto, Japan', d: 'Innsatt midt i Jōkyū-krigen og avsatt i løpet av måneder — shōgunenes første fjerning av en keiser.' },
  jp_go_horikawa: { n: 'Go-Horikawa', p: 'Kyoto, Japan', d: 'Valgt av Kamakura som en trygg voksen; hans regjeringstid fikk etterkrigens hofforden til å falle på plass under bakufu-oppsyn.' },
  jp_shijo: { n: 'Shijō', p: 'Kyoto, Japan', d: 'Døde brått ti år gammel; shōgunene brukte overraskelsen til å lede arvefølgen over til Tsuchimikado-linjen.' },
  jp_go_saga: { n: 'Go-Saga', p: 'Kyoto, Japan', d: 'De to sønnene hans grunnla de rivaliserende Jimyōin- og Daikakuji-linjene — pakten om å regjere på omgang, som senere delte hoffet i to.' },
  jp_go_fukakusa: { n: 'Go-Fukakusa', p: 'Kyoto, Japan', d: 'Jimyōin-keiser presset til å abdisere ung til fordel for broren — naget mellom de to linjene ble dypere.' },
  jp_kameyama: { n: 'Kameyama', p: 'Kyoto, Japan', d: 'Daikakuji-keiser under det første mongolangrepet (1274); linjene kranglet om arvingen hans, og avtalen ble hardere.' },
  jp_go_uda: { n: 'Go-Uda', p: 'Kyoto, Japan', d: 'Keiser gjennom den andre mongolinvasjonen (1281); patriark for Daikakuji-linjen i omgangsavtalen om tronen.' },
  jp_fushimi: { n: 'Fushimi', p: 'Kyoto, Japan', d: 'Jimyōin-keiser og kalligraf; hans hofflige linje ble en stor waka-skole — mens bakufu-meglerne holdt den reelle makten.' },
  jp_go_fushimi: { n: 'Go-Fushimi', p: 'Kyoto, Japan', d: 'Regjerte tre år under omgangsavtalen; de raske protestene hans mot vilkårene fordypet feiden mellom de to linjene.' },
  jp_go_nijo: { n: 'Go-Nijō', p: 'Kyoto, Japan', d: 'Forsøkte personlig styre mot både regenter og rivaliserende linje; døde ung og brått tjuetre år gammel.' },
  jp_hanazono: { n: 'Hanazono', p: 'Kyoto, Japan', d: 'Dagbokførende, hengiven og kunstnerisk; hans erindringer om å stå utenfor makten er et sjeldent keiserlig selvportrett fra epoken.' },
  jp_go_daigo: { n: 'Go-Daigo', p: 'Kyoto, Japan', d: 'Velte Kamakura-shōgunatet (1333) og gjenopprettet kortvarig direkte styre; da Ashikaga Takauji vendte seg fra ham, grunnla motstanden hans det sørlige hoffet.' },
  jp_go_murakami: { n: 'Go-Murakami', p: 'Kyoto, Japan', d: 'Det sørlige hoffets keiser, regjerende fra Yoshino og med flyttende leirer; hans slekt holdt de «ekte» riksregaliene gjennom tiår av krig.' },
  jp_chokei: { n: 'Chōkei', p: 'Kyoto, Japan', d: 'Den sørlige keiseren i lang tilbaketrekning; Yoshinos sak bleknet da krigerkoalisjonene skiftet til Ashikaga-norden.' },
  jp_go_kameyama: { n: 'Go-Kameyama', p: 'Kyoto, Japan', d: 'Siste sørlige keiser; overleverte riksregaliene til nord i 1392 og «forente» hoffene på nordens vilkår.' },
  jp_kogon: { n: 'Kōgon', p: 'Kyoto, Japan', d: 'Innsatt av Hōjō-regentene etter Go-Daigos første opprør; feid til side da Go-Daigo vendte tilbake i 1333.' },
  jp_komyo: { n: 'Kōmyō', p: 'Kyoto, Japan', d: 'Ashikaga Takaujis første nordlige keiser etter at Kenmu-restaureringen brøt sammen; de rettmessige riksregaliene forble i sør.' },
  jp_suko: { n: 'Sukō', p: 'Kyoto, Japan', d: 'Nordlig keiser avsatt midt i Kan’ō-urolighetene — Ashikaga-brødrenes feide som rystet begge hoffene.' },
  jp_go_kogon: { n: 'Go-Kōgon', p: 'Kyoto, Japan', d: 'En lang nordlig regjeringstid mens det sørlige leiret streifet omkring; Kyotos hoffkultur holdt stand på krigens nordside.' },
  jp_go_enyu: { n: 'Go-En’yū', p: 'Kyoto, Japan', d: 'Nordlig keiser mens Yoshimitsus shōgunat vokste; abdiserte til fordel for gutten Go-Komatsu, hvis regjeringstid skulle gjenforene hoffene.' },
  jp_go_komatsu: { n: 'Go-Komatsu', p: 'Kyoto, Japan', d: 'Siste nordlige tronpretendent, deretter eneste keiser etter foreningen i 1392 — første hersker av den gjenforente keiserslekten.' },
  jp_shoko: { n: 'Shōkō', p: 'Kyoto, Japan', d: 'Døde barnløs; tronen hoppet til en sidegren, og omgangsavtalen mellom de to linjene gikk stille ut.' },
  jp_go_hanazono: { n: 'Go-Hanazono', p: 'Kyoto, Japan', d: 'Hans trettiseksårige regjeringstid endte tre år før Ōnin-krigen — den siste roen før Kyoto brant.' },
  jp_go_tsuchimikado: { n: 'Go-Tsuchimikado', p: 'Kyoto, Japan', d: 'Keiser gjennom Ōnin-krigen (1467–77) som svelget Kyoto; hoffet ble fattig, provinsielt og oversett.' },
  jp_go_kashiwabara: { n: 'Go-Kashiwabara', p: 'Kyoto, Japan', d: 'Så fattig at kroningen hans ble utsett med tjueen år — keisertronen på sitt dypeste lavmål.' },
  jp_go_nara: { n: 'Go-Nara', p: 'Kyoto, Japan', d: 'Regjerte gjennom Sengoku-krigene; tronen overlevde på lån, gaver og salg av keiserlig kalligrafi.' },
  jp_ogimachi: { n: 'Ōgimachi', p: 'Kyoto, Japan', d: 'Så Nobunaga etablere seg i Kyoto (1568) og reparere hoffets finanser; abdiserte til fordel for Go-Yōzei.' },
  jp_go_yozei: { n: 'Go-Yōzei', p: 'Kyoto, Japan', d: 'Innsatt under Toyotomi Hideyoshi og satt til side av Tokugawa — hans regjeringstid spenner over Japans gjenforening og Edos erobring av politikken.' },
  jp_go_mizunoo: { n: 'Go-Mizunoo', p: 'Kyoto, Japan', d: 'Gift med shōgunens datter — forseglingen av hoffets overenskomst med bakufu; tvisten om de «purpurrøde kappene» og tempelhedrene gjorde forholdet surt senere.' },
  jp_meisho: { n: 'Meishō', p: 'Kyoto, Japan', d: 'Sjuende regjerende keiserinne — den første på 850 år; abdiserte til fordel for halvbroren Go-Kōmyō.' },
  jp_go_komyo: { n: 'Go-Kōmyō', p: 'Kyoto, Japan', d: 'En ildfull ung kritiker av shōgunatets pretensjoner; døde tjueto år gammel midt i vedvarende rykter om gift.' },
  jp_go_sai: { n: 'Go-Sai', p: 'Kyoto, Japan', d: 'Løftet opp etter Go-Kōmyōs brå død; abdiserte til fordel for Reigen og grunnla Go-Sai-linjen som hoffets reserve.' },
  jp_reigen: { n: 'Reigen', p: 'Kyoto, Japan', d: 'Abdiserte tidlig og tilbrakte tretti år som en formidabel klosterkeiser — den siste med reell politisk vekt.' },
  jp_higashiyama: { n: 'Higashiyama', p: 'Kyoto, Japan', d: 'Genroku-prakten — Chikamatsus skuespill, Bashōs haiku — blomstret mens den reelle makten satt i Edo.' },
  jp_nakamikado: { n: 'Nakamikado', p: 'Kyoto, Japan', d: 'Regjerte gjennom Kyōhō-reformene; hoffets verdighet kom seg mens shōgunatets finanser stagnerte.' },
  jp_sakuramachi: { n: 'Sakuramachi', p: 'Kyoto, Japan', d: 'Sammen med rådgiveren Kanamori gjenreiste han hofffinansene og vakte lenge nedlagte seremonier til live — en stille keiserlig renessanse.' },
  jp_momozono: { n: 'Momozono', p: 'Kyoto, Japan', d: 'Døde tjueen år gammel; tronen gikk til søsteren hans — Japans nest siste regjerende keiserinne.' },
  jp_go_sakuramachi: { n: 'Go-Sakuramachi', p: 'Kyoto, Japan', d: 'Tiende og siste regjerende keiserinne; en omhyggelig beskytter for den unge nevøen sin, og en skarpsindig hoffgestalt i tiår etterpå.' },
  jp_go_momozono: { n: 'Go-Momozono', p: 'Kyoto, Japan', d: 'Døde barnløs nitten år gammel uten å navngi en arving; hoffet improviserte en adopsjon for å holde arvefølgen ubrutt.' },
  jp_kokaku: { n: 'Kōkaku', p: 'Kyoto, Japan', d: 'Valgt fra en sidegren åtte år gammel; en kraftfull lang regjeringstid som gjenoppbygde keiserprestisjen på bakumatsus terskel.' },
  jp_ninko: { n: 'Ninkō', p: 'Kyoto, Japan', d: 'En from og flittig keiser; hans regjeringstid så sultår, Tenpō-reformene og de første dundrene av det utenlandske spørsmålet.' },
  jp_komei: { n: 'Kōmei', p: 'Kyoto, Japan', d: 'Urokkelig uvennlig innstilt til utlendinger; hoffediktene hans mot å åpne Japan næret bakumatsu-krisen — døde brått trettiseks år gammel.' },
  jp_meiji: { n: 'Meiji', p: 'Tokyo, Japan', d: 'Den gjeninnsatte keiseren bak et moderniseringsunder: grunnlov, jernbaner, industri — og seire over Kina og Russland.' },
  jp_taisho: { n: 'Taishō', p: 'Tokyo, Japan', d: 'Skrøpelig helse holdt ham borte fra politikken og flyttet makten til partiministerier — Japans korte «Taishō-demokrati».' },
  jp_showa: { n: 'Shōwa (Hirohito)', p: 'Tokyo, Japan', d: 'Regjerte gjennom krig, nederlag, okkupasjon og et økonomisk under — sekstito år, det lengste i japansk historie.' },
  jp_akihito: { n: 'Akihito', p: 'Tokyo, Japan', d: 'Heisei-keiseren som gjorde tronen til en røst for fred og erindring; abdiserte av egen fri vilje — den første på to århundrer.' },
  jp_naruhito: { n: 'Naruhito', p: 'Tokyo, Japan', d: 'Reiwa-ærens keiser, historiker med middelalderens vannveier som fagfelt; det symbolske monarkiet fortsetter inn i et fjerde tiår av fred.' },
});

/* Roman rulers (189 entries) — 2026-10-29 */
Object.assign(window.DATA_NO, {
  rk_romulus: { n: 'Romulus', p: 'Roma', d: 'Legendarisk grunnlegger og første konge; ifølge romersk myte oppfostret av en ulvinne, ga han navnet sitt til byen, dens første legioner og dens første senatorer.' },
  rk_numa: { n: 'Numa Pompilius', p: 'Roma', d: 'Den fromme andre kongen, som får æren for Romas kalender, presteskapene og Janustempelet, der portene holdt seg lukket i fredstid.' },
  rk_tullus: { n: 'Tullus Hostilius', p: 'Roma', d: 'Den krigerske tredje kongen, som ødela Alba Longa og flyttet folket der til Roma — et styre som legendene ender med pest og tordenlyn.' },
  rk_ancus: { n: 'Ancus Marcius', p: 'Roma', d: 'Barnebarn av Numa; han utvidet Roma til havet ved å grunnlegge Ostia og spente over Tiberen med den første Pons Sublicius.' },
  rk_tarquinius_priscus: { n: 'Tarquinius Priscus', p: 'Roma', d: 'Femte konge, etrusker av fødsel; han drenerte Forum, begynte Circus Maximus og lovde det store Jupitertempelet på Kapitol.' },
  rk_servius_tullius: { n: 'Servius Tullius', p: 'Roma', d: 'Sjette konge og stor reformator — han talte Romas befolkning inn i stammer og centurier, og skapte folketellingen, forsamlingene og den servianske muren.' },
  rk_superbus: { n: 'Tarquinius Superbus', p: 'Roma', d: 'Den siste, tyranniske kongen; harmen over familien hans utløste opprøret i 509 f.Kr. som endte monarkiet og grunnla republikken.' },
  rr_brutus: { n: 'Lucius Junius Brutus', p: 'Roma', d: 'Republikkens første konsul; han drev tarquinierne ut og henrettet sine egne sønner for å ha konspirert om deres tilbakekomst.' },
  rr_publicola: { n: 'Publius Valerius Publicola', p: 'Roma', d: 'Fire ganger konsul og folkets venn — lovene hans tok øksene fra liktorene og ga den unge republikken forfatningen sin.' },
  rr_cincinnatus: { n: 'Cincinnatus', p: 'Roma', d: 'Innkalt fra plogen for å bli diktator, knuste han aequierne på seksten dager og ga straks fra seg den øverste makten.' },
  rr_camillus: { n: 'Camillus', p: 'Roma', d: 'Erobreren av Veii og Romas andre grunnlegger — han reddet byen etter at gallerne brente den i 390 f.Kr.' },
  rr_appius_claudius: { n: 'Appius Claudius Caecus', p: 'Roma', d: 'Censor som bygde Via Appia og Romas første akvedukt; blind og gammel overtalte han senatet til å nekte fred med Pyrrhos.' },
  rr_fabius_cunctator: { n: 'Fabius Maximus Cunctator', p: 'Roma', d: 'Diktator etter at Hannibal knuste Roma ved Trasimeno; hans utsettende «fabianske strategi» reddet staten — og ga ham hatet fra de dristige.' },
  rr_scipio_africanus: { n: 'Scipio Africanus', p: 'Roma', d: 'Romas beste hærfører; han bar krigen til Afrika og beseiret Hannibal ved Zama i 202 f.Kr., og avsluttet dermed den andre punerkrigen.' },
  rr_cato: { n: 'Cato den eldre', p: 'Roma', d: 'Censor av streng gammel romersk dyd; han avsluttet hver tale med «Kartago må ødelegges» — og den tredje punerkrigen fulgte.' },
  rr_tiberius_gracchus: { n: 'Tiberius Gracchus', p: 'Roma', d: 'Tribun som prøvde å gi offentlig jord til de fattige; slått i hjel av senatorer på Forum — republikkens første politiske blodbad på generasjoner.' },
  rr_gaius_gracchus: { n: 'Gaius Gracchus', p: 'Roma', d: 'Yngre bror og radikal tribun bak kornutdelingen og utvidet statsborgerskap; jaget ned og drept da senatet slo tilbake.' },
  rr_marius: { n: 'Gaius Marius', p: 'Roma', d: 'Sju ganger konsul; han åpnet legionene for menn uten jord og utslettet kimbrerne og teutonerne — men striden med Sulla fikk Roma til å blø.' },
  rr_sulla: { n: 'Sulla', p: 'Roma', d: 'Første hærfører som marsjerte mot Roma selv; som diktator slaktet han fiender gjennom proskripsjonslister, for så — forbløffende nok — å gi makten tilbake.' },
  rr_pompey: { n: 'Pompeius den store', p: 'Roma', d: 'Renset havet for pirater og erobret Østen, tre ganger konsul og Caesars store rival — myrdet på en egyptisk strand etter Pharsalos.' },
  rr_crassus: { n: 'Marcus Licinius Crassus', p: 'Roma', d: 'Den rikeste mannen i Roma og den tredje i det første triumviratet; han marsjerte mot Partia for ærens skyld og døde ved Carrhae, med legionene sine tapt i ørkenen.' },
  rr_cicero: { n: 'Cicero', p: 'Roma', d: 'Konsul som avslørte den catilinarske sammensvergelsen med talene sine; Romas største taler og en varig røst for konstitusjonell frihet.' },
  rr_m_brutus: { n: 'Marcus Junius Brutus', p: 'Roma', d: 'Caesars venn og republikkens siste forsvarer — leder for frigjørerne som drepte diktatoren, beseiret og død ved Filippi.' },
  rr_cassius: { n: 'Gaius Cassius Longinus', p: 'Roma', d: 'Den drivende hjernen bak idus i mars; han reiste Østen mot triumvirerne og døde ved Filippi, villført av en falsk melding.' },
  rr_lepidus: { n: 'Lepidus', p: 'Roma', d: 'Den tredje i det andre triumviratet, alltid den mindre partneren; skjøvet ut av Oktavian og etterlatt til å ende dagene sine som Pontifex Maximus.' },
  rr_antony: { n: 'Marcus Antonius', p: 'Roma', d: 'Briljant hærfører og triumvir, Caesars høyre hånd; alliansen — og kjærligheten — med Kleopatra endte ved Actium og et selvmords sverd.' },
  rr_octavian: { n: 'Oktavian', p: 'Roma', d: 'Caesars atten år gamle arving som overlevde og beseiret enhver rival; i 27 f.Kr. ga senatet ham navnet Augustus — monarki i republikansk drakt.' },
  re_augustus: { n: 'Augustus', p: 'Roma', d: 'Første keiser; han tok vare på republikkens skall mens han styrte alt selv — førti år med fred som fant Roma i tegl og etterlot det i marmor.' },
  re_tiberius: { n: 'Tiberius', p: 'Roma', d: 'Motvillig, briljant og sur keiser som trakk seg tilbake til Capri og lot pretorianeren Sejanus terrorisere Roma med forræderirettssaker.' },
  re_caligula: { n: 'Caligula', p: 'Roma', d: 'Ung keiser som begynte elsket og endte som et monster — kildene anklager ham for grusomhet, sløst gull og samtaler om å gjøre hesten sin til konsul.' },
  re_claudius: { n: 'Claudius', p: 'Roma', d: 'Den stammande lærde ingen regnet med; han erobret Britannia, drenerte Fucino-sjøen og styrte riket med uventet dyktighet.' },
  re_nero: { n: 'Nero', p: 'Roma', d: 'Modermyrder og showmann av en keiser; Roma brant i 64, han skyldte på de kristne, bygde det gylne huset — og senatet erklærte ham som folkefiende.' },
  re_galba: { n: 'Galba', p: 'Roma', d: 'Året med de fire keiserne begynner: en stri gammel general, myrdet av pretorianerne etter sju måneder med gjerrige reformer.' },
  re_otho: { n: 'Otho', p: 'Roma', d: 'Pretorianernes favoritt, som regjerte nittifem dager og tapte Bedriacum for Vitellius — og tok livet sitt for at borgerkrigen ikke skulle tilspisses.' },
  re_vitellius: { n: 'Vitellius', p: 'Roma', d: 'Den gladspiste seierherren fra det første Bedriacum; åtte måneder senere brente de flaviske hærene Cremona og slepte ham gjennom Roma til døden.' },
  re_vespasian: { n: 'Vespasian', p: 'Roma', d: 'Den kløktige generalen fra muldyrhandelen som endte borgerkrigen, begynte Colosseum — og skattla urin for å fylle statskassen igjen.' },
  re_titus: { n: 'Titus', p: 'Roma', d: 'Elsket keiser i ulykkenes tid: han fullførte Colosseum, gravla Vesuvs døde, kjempet mot den store brannen i 80 — og døde altfor tidlig.' },
  re_domitian: { n: 'Domitian', p: 'Roma', d: 'Effektiv autokrat og skrekk for aristokratiet; han gjenoppbygde Roma, befestet linjen Rhinen–Donau — og døde i et palasskomplott.' },
  re_nerva: { n: 'Nerva', p: 'Roma', d: 'Aldrende senator løftet frem for å gjenopprette friheten etter Domitian; barnløs adopterte han Trajan og åpnet de fem gode keisernes tidsalder.' },
  re_trajan: { n: 'Trajan', p: 'Roma', d: '«Fyrstenes beste» — under ham nådde Roma sin største utstrekning, fra de dakiske gullgruvene til Persiabukten, og Forum fikk sin søyle.' },
  re_hadrian: { n: 'Hadrian', p: 'Roma', d: 'Reisende byggmesterkeiser som festet grensene — Hadrians mur, Pantheon — og omdøpte Judea etter å ha knust opprøret der.' },
  re_antoninus_pius: { n: 'Antoninus Pius', p: 'Roma', d: 'Den roligste regjeringstiden i romersk historie — tjuetre år uten større krig, riket på sitt mest blomstrende, den antoninske muren ved grensen.' },
  re_marcus_aurelius: { n: 'Marcus Aurelius', p: 'Roma', d: 'Filosofen på tronen; han skrev Meditasjonene i leiren mens pest og markomanniske inntrengere hamret på Donau-grensen.' },
  re_lucius_verus: { n: 'Lucius Verus', p: 'Roma', d: 'Medkeiser med Marcus Aurelius; han vant parterkrigen mens generalene hans gjorde jobben, og døde av pest på veien hjem.' },
  re_commodus: { n: 'Commodus', p: 'Roma', d: 'Marcus Aurelius’ sønn og Romas mareritt; han kjempet som gladiator i sin egen arena, ga månedene navn etter seg selv — og ble kvalt av en bryter.' },
  re_pertinax: { n: 'Pertinax', p: 'Roma', d: 'Streng sønn av en frigitt slave; pretorianerne — allerede solgt til Didius Julianus — drepte ham etter åttisju dager med disiplin.' },
  re_didius_julianus: { n: 'Didius Julianus', p: 'Roma', d: 'Han kjøpte riket på pretorianernes auksjon — og tapte det på ni uker til Septimius Severus, marsjerende fra Donau.' },
  re_septimius_severus: { n: 'Septimius Severus', p: 'Roma', d: 'Soldatkeiser født i Afrika og grunnlegger av det severanske dynastiet; dødsrådet hans — berik soldatene, forakt alt det andre.' },
  re_caracalla: { n: 'Caracalla', p: 'Roma', d: 'Morderen av broren Geta og av sin egen pretorianerprefekt; ediktet hans i 212 gjorde enhver fri innbygger i riket til romersk borger.' },
  re_geta: { n: 'Geta', p: 'Roma', d: 'Caracallas bror og med-Augustus i to år; myrdet i morens armer, minnet hans fordømt og navnet hans meislet bort fra monumentene.' },
  re_macrinus: { n: 'Macrinus', p: 'Antiokia', d: 'Pretorianerprefekt som tok purpuren etter Caracallas mord — den første keiseren utenfor senatsklassen; fjorten måneder senere var han død.' },
  re_elagabalus: { n: 'Elagabalus', p: 'Roma', d: 'Tenårig prestkeiser for den syriske solguden El-Gabal; skandalene hans vekket så mye avsky hos pretorianerne at de drepte ham og moren hans i leiren.' },
  re_severus_alexander: { n: 'Severus Alexander', p: 'Roma', d: 'Styrt av moren Julia Mamaea; mild og rådgitt av den store juristen Ulpianus — og myrdet i Mainz da hæren ville ha en hardere mann.' },
  re_maximinus_thrax: { n: 'Maximinus Thrax', p: 'Roma', d: 'Kjempestor bondegeneral, den første av soldatkeiserne; tre år med endeløs krig før egne tropper drepte ham utenfor Aquileia.' },
  re_gordian_i: { n: 'Gordian I', p: 'Kartago', d: 'Rik prokonsul utropt til keiser i Afrika mot Maximinus; etter trettiseks dager beseiret — han hengte seg med kappebeltet sitt.' },
  re_gordian_ii: { n: 'Gordian II', p: 'Kartago', d: 'Sønn og partner av Gordian I; han falt i slaget utenfor Kartago, og faren fulgte ham i døden i løpet av timer.' },
  re_pupienus: { n: 'Pupienus', p: 'Roma', d: 'Senatorkeiser valgt av senatet for å møte Maximinus; tyrannens hær hadde alt drept ham — deretter drepte pretorianerne Pupienus også.' },
  re_balbinus: { n: 'Balbinus', p: 'Roma', d: 'Pupienus’ kranglende medkeiser, valgt for å blidgjøre folket; begge ble dratt ut av palasset og drept av pretorianerne.' },
  re_gordian_iii: { n: 'Gordian III', p: 'Roma', d: 'Tretten år gammel barnebarn av den første Gordian; han marsjerte mot Persia og vant ved Resaena — og ble fordrevet av sin egen prefekt Philippus.' },
  re_philip_arab: { n: 'Philippus Arabs', p: 'Roma', d: 'Han sluttet fred med Persia og feiret Romas tusenårsdag med praktfulle leker — så falt han for Decius nær Verona.' },
  re_decius: { n: 'Decius', p: 'Roma', d: 'Beordret den riksdekkende kristenforfølgelsen; han og sønnen døde i kamp mot goterne ved Abritus — de første keiserne drept av barbarer.' },
  re_trebonianus_gallus: { n: 'Trebonianus Gallus', p: 'Roma', d: 'Han kjøpte fred fra goterne med gull, pesten kom likevel — og egne soldater overleverte ham til Aemilianus ved Interamna.' },
  re_aemilian: { n: 'Aemilianus', p: 'Roma', d: 'Tre måneder som keiser; utropt for å ha slått tilbake goterne, myrdet av egne menn da Valerian marsjerte fra Rhinen.' },
  re_valerian: { n: 'Valerian', p: 'Roma', d: 'Den eneste keiseren som noensinne ble tatt til fange i slag — tatt levende ved Edessa av den persiske kongen Shapur I, hvis fange han forble til sin død.' },
  re_gallienus: { n: 'Gallienus', p: 'Roma', d: 'Medregent mens faren satt i fangenskap, ble han en briljant, dødsdømt improvisator — han holdt kjernen mens Gallia og Palmyra løsrev seg, til han falt for egne offiserer.' },
  re_claudius_gothicus: { n: 'Claudius Gothicus', p: 'Roma', d: 'Kavalerigeneral som knuste goterne ved Naissus; pesten hentet ham før han rakk å samle det knuste riket igjen.' },
  re_quintillus: { n: 'Quintillus', p: 'Roma', d: 'Claudius’ bror, valgt av senatet mot hærens vilje; et klokt selvmord etter noen dager løste striden.' },
  re_aurelian: { n: 'Aurelianus', p: 'Roma', d: 'Verdens gjenoppretter — han tok tilbake Palmyras Zenobia og det galliske riket, bygde Romas siste mur — og døde i offiserenes komplott.' },
  re_tacitus: { n: 'Tacitus', p: 'Roma', d: 'En syttifem år gammel senator hæren valgte etter et mellomspill; han døde i Tyana, på vei østover mot gotere og persere.' },
  re_florianus: { n: 'Florianus', p: 'Roma', d: 'Tacitus’ halvbror; østhærene nektet å godta ham og utropte Probus — uker senere drepte egne menn ham i Tarsos.' },
  re_probus: { n: 'Probus', p: 'Roma', d: 'Gjenoppretter av Rhinens og Donaus grenser, som plantet vingårder oppover Donaudalen; soldatene hans, satt til grøftearbeid, drepte ham i Sirmium.' },
  re_carus: { n: 'Carus', p: 'Roma', d: 'Pretorianerprefekt blitt keiser; han slo quadiene og sarmatene, men døde — legenden sier av lynnedslag — før han tok Ktesifon.' },
  re_carinus: { n: 'Carinus', p: 'Roma', d: 'Carus’ eldste sønn, luksuselskende og grusom; han vant slaget ved Margus — og ble drept der av en tribun hvis kone han hadde forført.' },
  re_numerian: { n: 'Numerian', p: 'Roma', d: 'Carus’ yngre sønn, dikter og taler; svigerfaren Aper ble funnet sammen med guttens lik — Diokletian hogg ham ned foran hæren.' },
  re_diocletian: { n: 'Diokletian', p: 'Nikomedia', d: 'Den store omorganisatoren: tetrarkiet, doblede provinser, prisvedtak, den store kristenforfølgelsen — så den første keiseren som gikk av frivillig, for å dyrke kål i Split.' },
  re_maximian: { n: 'Maximian', p: 'Milano', d: 'Diokletians rå medkeiser i vest, i kamp mot røvere, britoner og tronranere; tvunget til å abdisere sammen med kollegaen, intrigerte han til det siste.' },
  re_constantius_chlorus: { n: 'Konstantius Klorus', p: 'Trier', d: 'Tetrarkiets vestlige Caesar, deretter Augustus; han gjenvant Britannia fra Allectus og døde i York etter å ha utnevnt sønnen Konstantin til arving.' },
  re_galerius: { n: 'Galerius', p: 'Sirmium', d: 'Arkitekten bak den store kristenforfølgelsen; døende i kvaler avsluttet han den med edikt i 311 — en endring kristne husket med ærefrykt.' },
  re_severus_ii: { n: 'Severus II', p: 'Milano', d: 'Konstantius’ Caesar, forfremmet til Augustus; Maxentius’ opprør og Maximians forræderi leverte ham ut til henrettelse utenfor Roma.' },
  re_maxentius: { n: 'Maxentius', p: 'Roma', d: 'Tronraneren ved Tiberen som druknet i den — hæren hans brøt sammen ved Milviske bro mot Konstantins korstegn.' },
  re_maximinus_daza: { n: 'Maximinus Daza', p: 'Antiokia', d: 'Den villeste av forfølgerne; Galerius’ nevø kjempet Licinius tilbake til Taurusfjellene, døde så av sykdom i Tarsos — med forfølgelsen opphevet.' },
  re_constantine_i: { n: 'Konstantin den store', p: 'Konstantinopel', d: 'Sønn av Konstantius; han samlet riket etter Milviske bro, legaliserte kristendommen og grunnla Konstantinopel som et nytt Roma.' },
  re_licinius: { n: 'Licinius', p: 'Sirmium', d: 'Konstantins svoger og siste rival; beseiret ved Chrysopolis, avsatt tross et løfte om trygghet — og henrettet innen ett år.' },
  re_constantine_ii: { n: 'Konstantin II', p: 'Trier', d: 'Konstantins eldste sønn; han krevde mer av vestriket fra brødrene sine og ble drept i et bakhold ved Aquileia, trettitre år gammel.' },
  re_constans: { n: 'Constans', p: 'Milano', d: 'Konstantins yngste sønn, vinner over broren Konstantin II; han fremmedgjorde hæren med favoritter og døde på flukt fra Magnentius’ kupp.' },
  re_constantius_ii: { n: 'Konstantius II', p: 'Konstantinopel', d: 'Mistenksom, lenge regjerende midterste sønn og arianer; han kjempet mot Persia og et dusin tronranere, og døde av feber på vei for å kjempe mot Julian.' },
  re_julian: { n: 'Julian den frafalne', p: 'Antiokia', d: 'Filosofkeiser som prøvde å vekke de gamle gudene til live og kutte sløseriet ved hoffet; han døde av et sår i Persia-felttoget, trettien år gammel.' },
  re_jovian: { n: 'Jovian', p: 'Ancyra', d: 'Valgt under tilbaketrekningen fra Ktesifon; han kjøpte hærens vei ut med persisk territorium og døde åtte måneder senere i Ancyra, i farens hus.' },
  re_valentinian_i: { n: 'Valentinian I', p: 'Trier', d: 'Pannonisk soldat som delte riket med broren Valens; han forsvarte Rhinen vilt og døde av raseri, ropende til utsendinger.' },
  re_valens: { n: 'Valens', p: 'Konstantinopel', d: 'Østkeiser under broren; han lot de gotiske flyktningene krysse Donau, kjempet mot dem halvt ubevæpnet — og brant levende ved Adrianopel.' },
  re_gratian: { n: 'Gratian', p: 'Trier', d: 'Givende sønn av Valentinian I, med på makten fra barndommen; han ga fra seg den hedenske tittelen Pontifex Maximus — og ble forlatt av hæren for tronraneren Maximus.' },
  re_valentinian_ii: { n: 'Valentinian II', p: 'Milano', d: 'Barnekeiser, først marionett for moren Justina, så for Theodosius; funnet hengt i Vienne — Ambrosius holdt gravtalen hans.' },
  re_theodosius_i: { n: 'Theodosius den store', p: 'Konstantinopel', d: 'Siste keiser som styrte begge deler; han gjorde nikensk kristendom til statsreligion og etterlot sønnene øst og vest — en deling som aldri grodde igjen.' },
  re_honorius: { n: 'Honorius', p: 'Ravenna', d: 'Den gjør-ingenting-keiseren i Ravenna som fikk Stilicho drept; Alarik plyndret Roma i 410 mens han, spotten sier, passet hønsene sine.' },
  re_constantius_iii: { n: 'Konstantius III', p: 'Ravenna', d: 'Generalen som dro vesten tilbake fra randen — tronranere knust, gotere bosatt i Gallia — medkeiser i sju måneder før lungebetennelsen tok ham.' },
  re_joannes: { n: 'Johannes', p: 'Ravenna', d: 'Overnotar som ble keiser da Honorius døde; Aetius kom med hunner for sent til å redde ham fra Galla Placidias østhær.' },
  re_valentinian_iii: { n: 'Valentinian III', p: 'Roma', d: 'Galla Placidias gutt på den vestlige tronen; han tapte Afrika til vandalene, drepte Aetius med egne hender — og ble hugget ned av Aetius’ menn.' },
  re_petronius_maximus: { n: 'Petronius Maximus', p: 'Roma', d: 'Senatoren bak mordet på Aetius og Valentinian; to måneder med makt, sluttet med at den romerske mengden steinet ham mens vandalflåten nærmet seg.' },
  re_avitus: { n: 'Avitus', p: 'Arles', d: 'Gallo-romersk aristokrat gjort til keiser med visigotisk hjelp; Ricimer avsatte ham, og han endte dagene sine som biskop i Piacenza.' },
  re_majorian: { n: 'Majorian', p: 'Ravenna', d: 'Den siste vestkeiseren som virkelig prøvde — lover mot skattemisbruk fortsatt sitert, en gjenerobringsflåte tapt ved Cartagena; Ricimer fikk ham kledd av og halshugget.' },
  re_libius_severus: { n: 'Libius Severus', p: 'Ravenna', d: 'Ricimers skyggekeiser, aldri anerkjent av øst; han døde i Roma — forgiftet, sa ryktet, av sin egen beskytter.' },
  re_anthemius: { n: 'Anthemius', p: 'Roma', d: 'Østens valg, en greker fra en stor arkitektfamilie; felttoget hans mot vandalene mislyktes, og Ricimer beleiret og drepte ham.' },
  re_olybrius: { n: 'Olybrius', p: 'Roma', d: 'Giftet inn i det theodosianske dynastiet, Ricimers valg som keiser; sju stille måneder — så vattersot, med vestriket fire år fra utryddelse.' },
  re_glycerius: { n: 'Glycerius', p: 'Ravenna', d: 'Gundobads utnevnelse etter Ricimers død; Julius Nepos landet ved Portus, hæren hoppet av — og Glycerius endte som biskop i Salona.' },
  re_julius_nepos: { n: 'Julius Nepos', p: 'Salona', d: 'Østens legitime vestkeiser; Orestes jaget ham til Dalmatia i 475 — han holdt Salona til sin egen husholder knivstakk ham.' },
  re_romulus_augustulus: { n: 'Romulus Augustulus', p: 'Ravenna', d: 'Gutten «lille Augustus» — den siste vestkeiseren; Odoaker pensjonerte ham av til Campania, og vestriket stanset rett og slett.' },
  bz_arcadius: { n: 'Arcadius', p: 'Konstantinopel', d: 'Første keiser av den varige østlige halvdelen — en svak yngling styrt av ministre som Rufinus og evnukken Eutropius mens vesten falt fra hverandre.' },
  bz_theodosius_ii: { n: 'Theodosius II', p: 'Konstantinopel', d: 'Førtito år med den boklige keiseren hvis Theodosius-lovverk og Theodosius-murer i Konstantinopel overlevde ham med et årtusen.' },
  bz_marcian: { n: 'Marcian', p: 'Konstantinopel', d: 'Soldatkeiser gift med Pulcheria; han nektet Attila skatt — gull til soldatene, ingenting til fienden — og konsilet i Khalkedon ble holdt under ham.' },
  bz_leo_i: { n: 'Leo I', p: 'Konstantinopel', d: 'Første keiser kronet av patriarken; han brøt goternes grep om hæren med isauriske rekrutter — og den store flåten mot vandalenes Kartago led forlis ved Kapp Bon.' },
  bz_leo_ii: { n: 'Leo II', p: 'Konstantinopel', d: 'Barnebarn av Leo I og Zeno, kronet ved seks, død av feber ved sju — tronen gikk til faren hans, Zeno.' },
  bz_zeno: { n: 'Zeno', p: 'Konstantinopel', d: 'Isaurisk keiser to ganger nesten styrtet — av Basiliscus, så av opprør; Henotikon hans prøvde å avslutte kirkestriden, og vestriket opphørte i hans regjeringstid.' },
  bz_basiliscus: { n: 'Basiliscus', p: 'Konstantinopel', d: 'Tronraner og bror av keiserinnen Verina — admiralen som mistet Kapp Bon-flåten; de monofysittiske ediktene hans utløste opptøyer, og Zeno vendte tilbake uten motstand.' },
  bz_anastasius_i: { n: 'Anastasius I', p: 'Konstantinopel', d: 'Varsom finansgeni — 320 000 pund gull i reserve, den lange muren reist, myntene reformert; folkemengder gjorde opprør over de monofysittiske sympatiene hans.' },
  bz_justin_i: { n: 'Justin I', p: 'Konstantinopel', d: 'Illyrisk bondevakt som hæren løftet opp; han helbrede det akacianske skismaet med Roma og banet vei for nevøen Justinian.' },
  bz_justinian_i: { n: 'Justinian I', p: 'Konstantinopel', d: 'Den siste latinsktalende keiseren og den travleste: gjenerobringen av Afrika og Italia, Corpus Iuris, Hagia Sofia — og overlevd Nika-opptøyet og pesten.' },
  bz_justin_ii: { n: 'Justin II', p: 'Konstantinopel', d: 'Nevø av Justinian; perser- og italienskrigene hans tømte statskassen, forstanden ga seg — og han utnevnte Tiberius til arving for å spare riket en arvefølgekrig.' },
  bz_tiberius_ii: { n: 'Tiberius II', p: 'Konstantinopel', d: 'Den generøse keiseren — han delte ut Justinians oppsparte skatt i soldaterlønn og fattighjelp; Persia og avarerne tok provinser i retur.' },
  bz_maurice: { n: 'Maurikios', p: 'Konstantinopel', d: 'Soldatlærd som vant perserkrigen ved å støtte Khosrow II og skrev Strategikon — så ble henrettet av Fokas med de seks sønnene foran øynene.' },
  bz_phocas: { n: 'Fokas', p: 'Konstantinopel', d: 'Centurionen hvis mytteri innledet rikets mørkeste århundre; skrekkvelde hans tok slutt da Herakleios’ flåte dukket opp utenfor Konstantinopel.' },
  bz_heraclius: { n: 'Herakleios', p: 'Konstantinopel', d: 'Han trakk riket tilbake fra dødens grense — Ktesifon tatt, det sanne korset gjenreist — for så å se Syria, Egypt og Armenia falle til arabene.' },
  bz_constantine_iii: { n: 'Konstantin III', p: 'Konstantinopel', d: 'Herakleios’ eldste sønn; han regjerte fire måneder og døde av tuberkulose — eller gift, mistenkte mengden — mens Martinas fraksjon sirkulerte.' },
  bz_heraklonas: { n: 'Heraklonas', p: 'Konstantinopel', d: 'Herakleios’ sønn med niesen Martina; lemlastingsopptøyene i september 641 avsatte ham — med nesen skåret opp — og slekten var over.' },
  bz_constans_ii: { n: 'Constans II', p: 'Konstantinopel', d: 'Barnebarn av Herakleios; han kjempet mot arabiske flåter ved mastene, kranglet med kirken, flyttet til Syrakus — og ble slått i hjel i badekaret.' },
  bz_constantine_iv: { n: 'Konstantin IV', p: 'Konstantinopel', d: 'Han brøt den første arabiske beleiringen av Konstantinopel med gresk ild i 678 og avsluttet den monotelittiske striden ved det sjette økumeniske konsil.' },
  bz_justinian_ii: { n: 'Justinian II', p: 'Konstantinopel', d: 'Hovmodig sønn av Konstantin IV, beseiret ved Sebastopolis og avsatt med nesen skåret — han vendte tilbake fra eksil i 705 for en regjeringstid av ren hevn.' },
  bz_leontios: { n: 'Leontios', p: 'Konstantinopel', d: 'General blitt tronraner etter Sebastopolis; tre år med arabiske nederlag, så et kupp, en neseskjæring — og i 706 endte Justinian IIs tilbakekomst ham.' },
  bz_tiberios_iii: { n: 'Tiberios III', p: 'Konstantinopel', d: 'Admiral i Kibyrraiot-flåten som tok tronen; han holdt østgrensen godt nok — til Justinian II seilte tilbake med bulgarsk hjelp.' },
  bz_philippikos: { n: 'Philippikos', p: 'Konstantinopel', d: 'Han halshugg Justinian II i hippodromen, gjenopplivet den monotelittiske striden — og tapte Armenia til arabene før et blindingskupp fjernet ham.' },
  bz_anastasios_ii: { n: 'Anastasios II', p: 'Konstantinopel', d: 'Forberedte seg strengt på den kommende arabiske beleiringen — kornmagasiner, en flåte, til og med et spionplot mot kalifen; egne tropper gjorde mytteri og valgte en munk.' },
  bz_theodosios_iii: { n: 'Theodosios III', p: 'Konstantinopel', d: 'Den motvillige skatteembedsmannen som opprørerne kronet; to år med arabisk fremrykking senere trakk han seg tilbake til et kloster og lot Leo III kjempe beleiringen.' },
  bz_leo_iii: { n: 'Leo III', p: 'Konstantinopel', d: 'Han brøt den årslange arabiske beleiringen 717–718 med gresk ild og bulgarske allierte, rekodifiserte loven — og innledet ikonoklasmen.' },
  bz_constantine_v: { n: 'Konstantin V', p: 'Konstantinopel', d: 'Briljant og brutal soldat som knuste bulgarerne ved Ankhialos og bygget opp themene — og gjorde ikonoklasmen til en utrenskning av dem som æret ikonene.' },
  bz_artabasdos: { n: 'Artabasdos', p: 'Konstantinopel', d: 'Konstantin Vs svoger, som holdt hovedstaden i seksten måneder og gjenopprettet ikonene; blindet med sønnene sine da borgerkrigen gikk mot ham.' },
  bz_leo_iv: { n: 'Leo IV', p: 'Konstantinopel', d: 'Sønn av Konstantin V og khanen av khasarenes datter; moderat i ikonsaken, han stoppet abbasidene og etterlot riket til sin ti år gamle sønn.' },
  bz_constantine_vi: { n: 'Konstantin VI', p: 'Konstantinopel', d: 'Barnekeiseren under morens regentskap; etter tabber mot bulgarere og arabere, og et angrep på Irene, blindet agentene hennes ham i soverommet hans.' },
  bz_irene: { n: 'Irene av Athen', p: 'Konstantinopel', d: 'Den første kvinnen som styrte riket alene; hun gjenopprettet ikonene på det andre konsilet i Nikea og døde i eksil på Lesbos da ministrene hennes kronet Nikeforos.' },
  bz_nikephoros_i: { n: 'Nikeforos I', p: 'Konstantinopel', d: 'Gjerrig logotet-keiser; han bygget opp finansene, tapte slag mot arabere — og mot Krums bulgarere, hvis khan laget drikkebeger av skallen hans.' },
  bz_staurakios: { n: 'Staurakios', p: 'Konstantinopel', d: 'Båret bort fra Pliska-katastrofen med dødelig sår; ti uker med nominelt styre — så kronet han svogeren Mikael I og tok munnerkappen.' },
  bz_michael_i: { n: 'Mikael I', p: 'Konstantinopel', d: 'From, prangende, hjelpeløs; hæren flyktet fra Krum ved Versinikia, troppene hyllet Leo den armenske — og Mikaels sønner ble kastrert og klostret.' },
  bz_leo_v: { n: 'Leo V', p: 'Konstantinopel', d: 'Han slo bulgarerne ved Mesembria og kjøpte fred, startet så ikonoklasmen igjen — og ble hogget ned under julemorgenbønnene av mennene han stolte på.' },
  bz_michael_ii: { n: 'Mikael II', p: 'Konstantinopel', d: 'Den stammande amoriske grunnleggeren; han brente Thomas Slavens årslange beleiring ut av hovedstaden, tapte Kreta og Sicilia — og overlot ikonoklastkompromisset til sønnen.' },
  bz_theophilos: { n: 'Teofilos', p: 'Konstantinopel', d: 'Den siste ikonoklasten — alvorlig, rettferdighetskjærlig, en bygger av palasser; Amorion falt for kalifens hærer i 838, tiårets sår.' },
  bz_michael_iii: { n: 'Mikael III', p: 'Konstantinopel', d: 'Ikonoklasmen tok slutt under moren Theodora; han kjempet mot abbasidene, sendte Kyrillos og Methodios til slaverne — og oppdro den makedonske Basileios, som drepte ham.' },
  bz_basil_i: { n: 'Basileios I', p: 'Konstantinopel', d: 'Bonde, hestetrener, morder av sin beskytter; han rekodifiserte loven i Basilika og falt under jakt — muligens myrdet av Leo VIs folk.' },
  bz_leo_vi: { n: 'Leo VI', p: 'Konstantinopel', d: 'Den vise — fire ekteskap for en sønn skapte Tetragami-skandalen; han tapte den bulgarske krigen for Symeon, skrev prekener og manualer — og kronet det makedonske århundret.' },
  bz_alexander: { n: 'Alexander', p: 'Konstantinopel', d: 'Leos late medkeiser i ett år; han rev ned brorens monumenter, ofret til en statue av Zevs — og døde av dysenteri etter en tzykanionkamp.' },
  bz_constantine_vii: { n: 'Konstantin VII', p: 'Konstantinopel', d: 'Lærdekeiseren, født i purpuren; regentskap holdt ham ventende i trettito år, men De Administrando og De Ceremoniis ble Bysants minne.' },
  bz_romanos_i: { n: 'Romanos I', p: 'Konstantinopel', d: 'Admiral som gjorde seg selv til øverste keiser over den unge Konstantin VII — tjuefire år med sunn forstand, nederlag for Symeon, jordlover — til sønnene forrådte ham.' },
  bz_romanos_ii: { n: 'Romanos II', p: 'Konstantinopel', d: 'Vakker, nytelseselskende sønn av den lærde; Nikeforos Fokas tok Kreta for ham, og han døde tjuefire år gammel — gift mistenkt.' },
  bz_nikephoros_ii: { n: 'Nikeforos II', p: 'Konstantinopel', d: 'Den bleke, munker-ansiktede erobreren av Kreta og Antiokia; han giftet seg med Theofano og skattla kirken — og ble myrdet i soverommet sitt av Tzimiskes og keiserinnen.' },
  bz_john_i_tzimiskes: { n: 'Johannes I Tzimiskes', p: 'Konstantinopel', d: 'Den vakre lille generalen; han knuste Svjatoslavs rusere ved Silistra og marsjerte til Bagdads murer — døde av tyfus på det østlige felttoget.' },
  bz_basil_ii: { n: 'Basileios II Bulgaroksen', p: 'Konstantinopel', d: 'Bulgaroksens førtini år var rikets høydepunkt: Bulgaria annektert, themene sterke, 200 000 pund i reserve — og ingen arving, den stille katastrofen.' },
  bz_constantine_viii: { n: 'Konstantin VIII', p: 'Konstantinopel', d: 'Broren som ventet trettitre år på å styre alene; tre år med favoritter og lemlastinger — så gikk tronen til døtrene Zoe og Theodora.' },
  bz_zoe: { n: 'Zoe', p: 'Konstantinopel', d: 'Femti år og oppdratt til å gifte seg med den hoffet valgte — Romanos III, Mikael IV, Konstantin IX; myntverket preget ansiktet hennes ved siden av hver ektemanns.' },
  bz_romanos_iii: { n: 'Romanos III', p: 'Konstantinopel', d: 'Zoes første ektemann, en intellektuell som lekte keiser; skattene steg, et syrisk angrep feilet — og han druknet i badekaret mens kildene bare trakk på skuldrene over keiserinnen.' },
  bz_michael_iv: { n: 'Mikael IV', p: 'Konstantinopel', d: 'Zoes vakre elsker, gjort til keiser av broren, evnukken Johannes; epilepsien åt ham opp mens bulgarerne reiste seg — han døde som munk, krigen vunnet ved Ostrovo.' },
  bz_michael_v: { n: 'Mikael V', p: 'Konstantinopel', d: 'Adoptivnevø av Mikael IV; han forviste sin velgjenger Zoe i hovmod — folket gjorde opprør i fire dager, og han ble ført bort blindet, til et kloster.' },
  bz_theodora: { n: 'Theodora', p: 'Konstantinopel', d: 'Zoes yngre søster, medkeiserinne under opptøyene i 1042, endelig enehersker i 1055 — streng, kysk, syttifire, den siste av det makedonske huset.' },
  bz_constantine_ix: { n: 'Konstantin IX', p: 'Konstantinopel', d: 'Zoes tredje ektemann; hoffet hans var Konstantinopels gylne ettermiddag — en jusskole, filosofi — men mynten ble forringet og Manzikerts frø ble sådd.' },
  bz_michael_vi: { n: 'Mikael VI', p: 'Konstantinopel', d: 'Den aldrende sivilisten Theodora valgte; han gav østgeneralene en kold skulder, Isak Komnenos marsjerte — og abdikasjonen kjøpte ham en ærefull pensjonering.' },
  bz_isaac_i: { n: 'Isak I', p: 'Konstantinopel', d: 'Første Komnenos-keiser; han rev tilbake kirkens jorder og aristokratiske forleninger, ble forkjølet i en storm — og overdro tronen til Konstantin X Dukas.' },
  bz_constantine_x: { n: 'Konstantin X', p: 'Konstantinopel', d: 'Sivilstyre igjen — hæren ubetalt, grensene tynnede ut; normannerne gjorde slutt på Italia, tyrkere herjet Armenia, og enken hans giftet seg snart igjen.' },
  bz_romanos_iv: { n: 'Romanos IV', p: 'Konstantinopel', d: 'Soldatkeiser som marsjerte for å stanse turkmenernes herjingstog; forrådt ved Manzikert — tatt til fange av Alp Arslan, løskjøpt, blindet, død.' },
  bz_michael_vii: { n: 'Mikael VII', p: 'Konstantinopel', d: '«Parapinakios» — keiseren av den dyre brøden; Psellos’ elev, han så på mens normannerne tok Bari og statskassen kollapset under petsjenegerkrigen.' },
  bz_nikephoros_iii: { n: 'Nikeforos III', p: 'Konstantinopel', d: 'Den aldrende generalen som Anatolia reiste mot Mikael VII; tre år med kaos — så endte Alexios Komnenos’ tronran ham i et kloster.' },
  bz_alexios_i: { n: 'Alexios I', p: 'Konstantinopel', d: 'Han bygde opp fra avgrunnen — venetiansk handel mot gull, petsjenegene knust ved Levounion, og det første korstoget ført trygt forbi, til hans avtales fordel.' },
  bz_john_ii: { n: 'Johannes II', p: 'Konstantinopel', d: '«Johannes den gode», den mildeste i en voldsom slekt; Donaufelttog, Ungarn temmet, Antiokia underkuet — han døde av en jaktskade, og de fattige sørget over ham.' },
  bz_manuel_i: { n: 'Manuel I', p: 'Konstantinopel', d: 'Den vestliggjørende ridderkeiseren; turneringer, diplomati fra Ungarn til Outremer, Myriokephalon overlevd — og riket glitret, til det ikke gjorde det lenger.' },
  bz_alexios_ii: { n: 'Alexios II', p: 'Konstantinopel', d: 'Elleve år gammel arving under den regjerende moren; Andronikos red inn, mengden myrdet Maria av Antiokia — og gutten ble kvalt med en buestreng.' },
  bz_andronikos_i: { n: 'Andronikos I', p: 'Konstantinopel', d: 'Briljant, brutal skrekk for aristokratiet; to år med terror — så rev Isak Angelos’ kupp og en hippodrommengde ham i stykker.' },
  bz_isaac_ii: { n: 'Isak II', p: 'Konstantinopel', d: 'Han slo normannerne, sløste statskassen på fester, tapte Bulgaria til asenene — og ble blindet, så gjeninnsatt, av egen bror og sønn.' },
  bz_alexios_iii: { n: 'Alexios III', p: 'Konstantinopel', d: 'Han blindet Isak og ruinerte staten; da det fjerde korstogets flåte nådde Gylne Horn i 1203, flyktet han med juvelene i en fiskebåt.' },
  bz_alexios_iv: { n: 'Alexios IV', p: 'Konstantinopel', d: 'Han lovet korsfarerne månen for farens trone — kunne ikke betale, og Mourtzouflos’ fraksjon kvalte ham mens byen sultet.' },
  bz_alexios_v: { n: 'Alexios V', p: 'Konstantinopel', d: 'To måneder med heroisk forsvar — den venetianske flåten brant utenfor murene; så flyktet han, og korsfarerne henrettet ham ved Theodosius-søylen.' },
  bz_theodore_i: { n: 'Teodor I Laskaris', p: 'Nikaia', d: 'Restrikets overlever: fra Nikaia slo han latinerne, tok en patriark-bekreftet krone og giftet seg inn i de store slektene for å holde det greske Asia.' },
  bz_john_iii: { n: 'Johannes III Dukas Vatatzes', p: 'Nikaia', d: 'Den største av nikeanerne — Rhyndakos vunnet, Kreta tatt, Bulgaria stoppet, Konstantinopel blokkert; grekerne helgenkåret ham som Johannes den barmhjertige.' },
  bz_theodore_ii: { n: 'Teodor II Laskaris', p: 'Nikaia', d: 'Lærd på tronen — korrespondanse, filosofi, en kjerne av utdannede nye menn; epilepsi og dødsfall i familien skygget fire korte år.' },
  bz_john_iv: { n: 'Johannes IV Laskaris', p: 'Nikaia', d: 'Kronet ved sju, blindet ved elleve — på Mikael Palaiologos’ juleordre, samme dag Konstantinopel ble gjenerobret; gutten levde videre i en festning.' },
  bz_michael_viii: { n: 'Mikael VIII Palaiologos', p: 'Konstantinopel', d: 'Han tok Konstantinopel fra latinerne i 1261 og gjenforente kirken i Lyon for å holde Karl av Anjou i sjakk — hatet, fryktet, effektiv til det siste.' },
  bz_andronikos_ii: { n: 'Andronikos II', p: 'Konstantinopel', d: 'From og sparsommelig til rikets skade — skatter kuttet, flåten skrapet, det katalanske kompaniet sluppet løs og ubetalt; barnebarnets borgerkrig endte de førtiseks årene hans.' },
  bz_andronikos_iii: { n: 'Andronikos III', p: 'Konstantinopel', d: 'En yngling av skandaler som styrte overraskende godt — lovkodifisering, Lésvos gjenerobret, Epiros gjenvunnet — mens osmanene tok sitt første fotfeste ved Gallipoli.' },
  bz_john_v: { n: 'Johannes V', p: 'Konstantinopel', d: 'Et halvt århundre med borgerkriger, osmansk vasallskap og en pavelig omvendelsesturné; han døde som Bayezids vasall, riket hans en by og noen spredte havner.' },
  bz_john_vi: { n: 'Johannes VI', p: 'Konstantinopel', d: 'Stor domestikos som ble medkeiser gjennom borgerkrig; han ga datteren sin til en osmansk bey, trakk seg tilbake til et kloster — og skrev sitt eget forsvar i historien.' },
  bz_andronikos_iv: { n: 'Andronikos IV', p: 'Konstantinopel', d: 'Han tok tronen fra faren Johannes V med osmansk og genovesisk hjelp — og tapte den på samme måte; Gallipoli forble tyrkisk uansett.' },
  bz_john_vii: { n: 'Johannes VII', p: 'Konstantinopel', d: 'Fem måneder med tronran mellom bestefar og onkel; senere holdt han Konstantinopel for Manuel II mot Bayezid og forhandlet med Timurs storm.' },
  bz_manuel_ii: { n: 'Manuel II', p: 'Konstantinopel', d: 'Lærdekeiser av den lange tilbaketrekningen — den berømte samtalen om troen med en perser, tiggingsturnéer til vestlige hoffer som brakte lite hjelp.' },
  bz_john_viii: { n: 'Johannes VIII', p: 'Konstantinopel', d: 'Han søkte kirkeforening i Firenze og vestlig hjelp ved Varna — ingen av delene holdt; Pisanello og Benozzo Gozzoli malte den merkelige hatten hans for alltid.' },
  bz_constantine_xi: { n: 'Konstantin XI Palaiologos', p: 'Konstantinopel', d: 'Den siste romerske keiseren; han døde med sverdet i hånden i bresjen ved St. Romanus-porten mens Mehmed IIs hær tok Konstantinopel 29. mai 1453.' },
});

/* pharaohs of Egypt - 143 entries (2026-10-29) */
Object.assign(window.DATA_NO, {
  ph_narmer: { n: 'Narmer', p: 'Hierakonpolis, Egypt', d: 'Den som forente Øvre og Nedre Egypt under én krone — den utskårne paletten hans viser ham som den første kongen av den første store territorielle staten på jorden.' },
  ph_aha: { n: 'Hor-Aha', p: 'Memfis, Egypt', d: 'Tradisjonen tilskriver ham grunnleggelsen av Memfis, og graven hans ved Abydos rommet tjenere som ble begravd for å tjene kongen sin i etterlivet.' },
  ph_djer: { n: 'Djer', p: 'Abydos, Egypt', d: 'Egyptere fra senere århundrer dyrket graven hans ved Abydos som gravstedet til guden Osiris selv.' },
  ph_djet: { n: 'Djet', p: 'Abydos, Egypt', d: 'Gravstelen hans, risset med et slangetegn, er et av de fineste bevarte verkene fra tidlig dynastisk kunst.' },
  ph_merneith: { n: 'Merneith', p: 'Abydos, Egypt', d: 'Dronning og regent for guttekongen Den, oppført både blant kongene og blant dronningene — ganske muligens Egypts første kvinnelige hersker.' },
  ph_den: { n: 'Den', p: 'Abydos, Egypt', d: 'Den første som tok tittelen konge av Øvre og Nedre Egypt med dobbeltkronen; den lange regjeringstiden hans satte mønsteret for den unge staten.' },
  ph_anedjib: { n: 'Anedjib', p: 'Memfis, Egypt', d: 'En urolig regjeringstid, husket for opprør i Øvre Egypt og for samtidige påstander om at han hadde ranet til seg tronen.' },
  ph_semerket: { n: 'Semerkhet', p: 'Abydos, Egypt', d: 'Senere tradisjon, via Manetho, kalte hans tid en ulykkens tid — likevel fikk han en fullverdig kongelig begravelse ved Abydos.' },
  ph_qaa: { n: 'Qa’a', p: 'Abydos, Egypt', d: 'Siste konge av 1. dynasti, begravd med et rikt hoff rundt seg; døden hans utløste en tronfølgestrid.' },
  ph_hotepsekhemwy: { n: 'Hotepsekhemwy', p: 'Memfis, Egypt', d: 'Grunnleggeren av 2. dynasti; navnet hans — «de to maktene er i fred» — lover forsoning etter dynastikrisen som avsluttet 1. dynasti.' },
  ph_raneb: { n: 'Raneb', p: 'Memfis, Egypt', d: 'Den første kongen som tok solguden Ra inn i navnet sitt, et tidlig varsel om solretningen som skulle dominere det gamle riket.' },
  ph_nynetjer: { n: 'Nynetjer', p: 'Memfis, Egypt', d: 'En regjeringstid på nesten førti år, ført inn i de kongelige annalene; etter den gled dynastiet inn i tiår med omstridt tronfølge.' },
  ph_peribsen: { n: 'Peribsen', p: 'Abydos, Egypt', d: 'Den eneste kongen som satte guden Set, ikke Horus, over navnet sitt — et religiøst valg forskere fortsatt strides om.' },
  ph_khasekhemwy: { n: 'Khasekhemwy', p: 'Hierakonpolis, Egypt', d: 'Den siste tidligdynastiske kongen, Horus og Sets forsoner; den gigantiske innhegningen av soltørket leirstein som han reiste ved Abydos, er jordens eldste store leirsteinsbygg.' },
  ph_sanakht: { n: 'Sanakht', p: 'Memfis, Egypt', d: 'Muligens grunnleggeren av 3. dynasti; et relieffragment viser en høy og bred konge hvis identitet forskere fortsatt diskuterer.' },
  ph_djoser: { n: 'Djoser', p: 'Memfis, Egypt', d: 'Arkitekten hans, Imhotep, reiste trappepyramiden i Saqqara — verdens første store steinbygg — og begge ble dyrket som guder i 2 000 år.' },
  ph_sekhemkhet: { n: 'Sekhemkhet', p: 'Memfis, Egypt', d: 'Han begynte en andre trappepyramide ved siden av Djoser, men døden etter seks år lot den ligge begravd og uferdig — funnet intakt i 1952.' },
  ph_khaba: { n: 'Khaba', p: 'Memfis, Egypt', d: 'Trolig byggeren av Lagpyramiden i Zawyet el-Aryan, et nytt tidlig forsøk på kongelige steingraver.' },
  ph_huni: { n: 'Huni', p: 'Memfis, Egypt', d: 'Siste konge av 3. dynasti, trolig den herskeren som begynte pyramiden i Meidum på terskelen til det gamle rikets store tid.' },
  ph_sneferu: { n: 'Snofru', p: 'Memfis, Egypt', d: 'Egypts største pyramidebygger — han reiste tre pyramider, blant dem den første ekte med glatte sider, i Dahshur, og ble husket i generasjoner som en velvillig idealkonge.' },
  ph_khufu: { n: 'Kheops', p: 'Memfis, Egypt', d: 'Byggeren av den store pyramiden i Giza, oldtidens eneste bevarte underverk — 146 meter stein, innrettet mot ekte nord innenfor en brøkdel av en grad.' },
  ph_djedefre: { n: 'Djedefre', p: 'Memfis, Egypt', d: 'Han flyttet den kongelige gravlunden til Abu Rawash, Egypts høyestliggende pyramideplass, og får æren for den første kolossale kongelige sfinksen.' },
  ph_khafre: { n: 'Kefren', p: 'Memfis, Egypt', d: 'Byggeren av Gizas andre pyramide og av den store sfinksen som vokter den; ettersom graven står på høyere grunn, ser den høyere ut enn pyramiden til Kheops.' },
  ph_menkaure: { n: 'Mykerinos', p: 'Memfis, Egypt', d: 'Pyramiden hans i Giza fikk kostbar granittbekledning, og de milde triadestatuene av ham sammen med gudinnen Hathor fastla idealet for kongelig portrettkunst.' },
  ph_shepseskaf: { n: 'Shepseskaf', p: 'Memfis, Egypt', d: 'Den siste kongen av 4. dynasti forlot pyramidene til fordel for en gigantisk sarcofagformet mastaba i Saqqara, og avsluttet Egypts største epoke for gravbygging.' },
  ph_userkaf: { n: 'Userkaf', p: 'Memfis, Egypt', d: 'Grunnleggeren av 5. dynasti; han bygde det første soltempelet — en kjempestor obelisk i en åpen gårdsplass — og gjorde solkulten til statens ideologi.' },
  ph_sahure: { n: 'Sahure', p: 'Memfis, Egypt', d: 'Relieffene hans skildrer den første egyptiske sjøreisen til Punt og de eldste kjente flåtescenene; komplekset hans i Abusir satte den kunstneriske normen for generasjoner.' },
  ph_neferirkare: { n: 'Neferirkare Kakai', p: 'Memfis, Egypt', d: 'Tempelarkivet hans i Abusir bevarte de eldste kjente administrasjons- og medisinske papyrusene fra Egypt.' },
  ph_shepseskare: { n: 'Shepseskare', p: 'Memfis, Egypt', d: 'En gåtefull regjeringstid innklemt mellom lengre, merket bare av et uferdig soltempel i Abusir.' },
  ph_neferefre: { n: 'Neferefre', p: 'Memfis, Egypt', d: 'Døde rundt tjue år gammel; den uferdige pyramiden hans ble i hast omgjort til en lav mastaba i Abusir, der statuene hans ble begravd.' },
  ph_nyuserre: { n: 'Nyuserre Ini', p: 'Memfis, Egypt', d: 'En trettiårig regjeringstid som fylte Abusir med monumenter, blant dem soltempelet med årstidsrelieffer som ledsager Egypts eldste tempelregnskaper.' },
  ph_menkauhor: { n: 'Menkauhor Kaiu', p: 'Memfis, Egypt', d: 'Pyramiden hans, «Ras stjerne er fullkommen», var forsvunnet i over et århundre og ble først identifisert i 2008.' },
  ph_djedkare: { n: 'Djedkare Isesi', p: 'Memfis, Egypt', d: 'En førtiårig regjeringstid med administrativ reform, som mot slutten fikk de første beskyttende trylleformlene til å dukke opp i de kongelige pyramidene — frøene til Pyramidetekstene.' },
  ph_unas: { n: 'Unas', p: 'Memfis, Egypt', d: 'Siste konge av 5. dynasti; Saqqara-pyramiden hans bærer de første innhugne Pyramidetekstene, menneskehetens eldste religiøse litteratur, med løftet til kongen om evig liv blant stjernene.' },
  ph_teti: { n: 'Teti', p: 'Memfis, Egypt', d: 'Grunnleggeren av 6. dynasti, som senere tradisjon sier ble myrdet av sine egne livvakter; de rike gravene til embedsmennene hans er en hovedkilde til tiden.' },
  ph_userkare: { n: 'Userkare', p: 'Memfis, Egypt', d: 'Han tok tronen mellom Teti og Pepi I, og senere egyptisk erindring mistenkte ham for mordet på Teti.' },
  ph_pepi_i: { n: 'Pepi I', p: 'Memfis, Egypt', d: 'Han overlevde en haremssammensvergelse, regjerte i fire tiår og etterlot seg en ragende kobberstatue — den største metallfiguren fra oldtidens Nære Østen.' },
  ph_merenre_i: { n: 'Merenre Nemtyemsaf I', p: 'Memfis, Egypt', d: 'Han sendte den berømte guvernøren Harkhuf dypt inn i Nubia og døde ung, og etterlot tronen til en liten gutt.' },
  ph_pepi_ii: { n: 'Pepi II', p: 'Memfis, Egypt', d: 'En regjeringstid på rundt nitti år — trolig den lengste i historien — som åpnet med et brev som lovte en dansende pygme, og sluttet med det gamle riket i forfall.' },
  ph_merenre_ii: { n: 'Merenre Nemtyemsaf II', p: 'Memfis, Egypt', d: 'En konge av ett eneste år, kjent nesten bare gjennom dronningen som fulgte ham.' },
  ph_nitocris: { n: 'Nitokris', p: 'Memfis, Egypt', d: 'Herodot og Manethos siste hersker av 6. dynasti, historiens første navngitte kvinnelige farao — enten en dronning med det navnet virkelig regjerte eller ikke.' },
  ph_khety_i: { n: 'Meryibre Khety', p: 'Herakleopolis, Egypt', d: 'Grunnleggeren av det herakleopolitiske dynastiet som gjorde krav på nord, mens thebanske fyrster samlet makt i sør — to maktsentre mot hverandre i den første mellomperioden.' },
  ph_intef_i: { n: 'Intef I', p: 'Tebe, Egypt', d: 'Den første thebanske herskeren av sin slekt som tok den kongelige kartusjen, mens Tebe reiste seg mot det herakleopolitiske Egypt.' },
  ph_intef_ii: { n: 'Intef II', p: 'Tebe, Egypt', d: '«Skjønnhetsbringeren», hvis femtiårige regjeringstid presset Tebes grense nordover forbi Abydos og satte gjenforeningen i gang.' },
  ph_intef_iii: { n: 'Intef III', p: 'Tebe, Egypt', d: 'Han fullførte den thebanske oppbyggingen, og svigersønnen hans, Mentuhotep II, skulle høste det gjenforente kongeriket; århundrer senere ble han fortsatt dyrket i Koptos.' },
  ph_mentuhotep_ii: { n: 'Mentuhotep II', p: 'Tebe, Egypt', d: 'Gjenforeneren — han knuste det herakleopolitiske nord og innledet det midtre riket; det terrasserte tempelet hans i Deir el-Bahari ble en modell som ble etterlignet i årtusener.' },
  ph_mentuhotep_iii: { n: 'Mentuhotep III', p: 'Tebe, Egypt', d: 'Han sendte den første dokumenterte ekspedisjonen til landet Punt og åpnet Rødehavshandelen igjen etter borgerkrigene.' },
  ph_mentuhotep_iv: { n: 'Mentuhotep IV', p: 'Tebe, Egypt', d: 'En skygge på slutten — den kongelige oppsynsmannen Amenemhat, som fikk hogd ut sarcofaglokket hans, tok trolig tronen selv som Amenemhat I.' },
  ph_amenemhat_i: { n: 'Amenemhat I', p: 'Itj-taui, Egypt', d: 'Grunnleggeren av 12. dynasti: han flyttet hovedstaden til det nybygde Itj-taui og opphøyde sønnen sin til medregent — en klok forholdsregel, for han ble myrdet i sitt trettiende regjeringsår.' },
  ph_senusret_i: { n: 'Senusret I', p: 'Itj-taui, Egypt', d: 'Medregenten som overtok makten knirkefritt; under ham ble Fortellingen om Sinuhe nedskrevet, og obelisken hans i Heliopolis står den dag i dag.' },
  ph_amenemhat_ii: { n: 'Amenemhat II', p: 'Itj-taui, Egypt', d: 'Annalene hans forteller om gruveflåter til Nubia og handelsoppdrag til Libanon — det midtre riket på sitt kommersielle høydepunkt.' },
  ph_senusret_ii: { n: 'Senusret II', p: 'Itj-taui, Egypt', d: 'Han drenerte Fayum-myrene til jordbruksland og flyttet pyramiden sin til El-Lahun, hvis arbeiderby bevarer hverdagslivet i det gamle Egypt.' },
  ph_senusret_iii: { n: 'Senusret III', p: 'Itj-taui, Egypt', d: 'Krigeren og administratoren hvis festninger lenket Nubias andre katarakt, hvis kanaler skar gjennom den, og hvis strenge statuer oppfant en ny realisme i kongekunsten.' },
  ph_amenemhat_iii: { n: 'Amenemhat III', p: 'Itj-taui, Egypt', d: 'Det midtre rikets økonomiske høydepunkt — labyrinten hans i Hawara imponerte greske besøkende, og Fayum-anleggene hans forvandlet myr til Egypts kornkammer.' },
  ph_amenemhat_iv: { n: 'Amenemhat IV', p: 'Itj-taui, Egypt', d: 'Den siste mannlige kongen av 12. dynasti, muligens fosterbarnet og ektefellen til dronningen som fulgte etter ham.' },
  ph_sobekneferu: { n: 'Sobekneferu', p: 'Itj-taui, Egypt', d: 'Den første kvinnen som etterrettelig regjerte Egypt som konge; med henne tok det store 12. dynastiet — og stabiliteten i det midtre riket — slutt.' },
  ph_khendjer: { n: 'Khendjer', p: 'Itj-taui, Egypt', d: 'En konge med semittisk navn fra det sviktende 13. dynastiet — den eneste faraoen fra det midtre riket som vi vet bygget en pyramide, i Sør-Saqqara.' },
  ph_khyan: { n: 'Khyan', p: 'Avaris, Egypt', d: 'En hyksoshersker i Avaris hvis skarabéer strekker seg fra Kreta til Mesopotamia — de fremmedes kongedømme lå inne i en større handelsverden.' },
  ph_apepi: { n: 'Apepi', p: 'Avaris, Egypt', d: 'Hyksoskongen fra senere legender som kom i strid med Tebe — byen hans, Avaris, holdt deltaet i et helt århundre før thebanerne slo tilbake.' },
  ph_seqenenre_tao: { n: 'Seqenenre Tao', p: 'Tebe, Egypt', d: 'Thebaneren hvis mumie bærer forferdelige øksehogg — han falt trolig i kamp da Egypts frigjøringskrig mot hyksosene tok til.' },
  ph_kamose: { n: 'Kamose', p: 'Tebe, Egypt', d: 'Den siste kongen av 17. dynasti; ordene på stelen hans — «Jeg vil redde Egypt og slå ned asiaterne» — innledet krigen som broren Ahmose fullførte.' },
  ph_ahmose_i: { n: 'Ahmose I', p: 'Tebe, Egypt', d: 'Han drev hyksosene ut av Egypt og forfulgte dem inn i Kanaan, og grunnla 18. dynasti og det nye rikets imperium.' },
  ph_amenhotep_i: { n: 'Amenhotep I', p: 'Tebe, Egypt', d: 'Sammen med moren Ahmose-Nefertari ble han dyrket i århundrer som beskytterguden for Tebes kongelige arbeidere.' },
  ph_thutmose_i: { n: 'Thutmosis I', p: 'Tebe, Egypt', d: 'Den første faraoen som ble begravd i Kongenes dal; hæren hans marsjerte til Eufrat, lengst Egypt noensinne hadde kommet.' },
  ph_thutmose_ii: { n: 'Thutmosis II', p: 'Tebe, Egypt', d: 'Den korte regjeringstiden hans ble styrt av den store kongelige hustruen Hatsjepsut; i 2025 ble den tapte graven hans den første kongelige begravelsen som er funnet siden Tutankhamons.' },
  ph_hatshepsut: { n: 'Hatsjepsut', p: 'Tebe, Egypt', d: 'Dronningen som regjerte som fullverdig farao i to tiår — Punt-ekspedisjonen, det terrasserte tempelet i Deir el-Bahari, obelisker høyere enn noen før — til senere konger hugget vekk bildene hennes.' },
  ph_thutmose_iii: { n: 'Thutmosis III', p: 'Tebe, Egypt', d: '«Soldatfaraoen»: sytten felttog fra Megiddo til Eufrat skapte Egypts største imperium i Asia, lenge skyggelagt i historien av tanten som regjerte før ham.' },
  ph_amenhotep_ii: { n: 'Amenhotep II', p: 'Tebe, Egypt', d: 'En pralende atletkonge som skjøt piler gjennom kobbermål — og en gang hengte sju drepte opprørere fra baugen på skipet sitt for å skremme Syria.' },
  ph_thutmose_iv: { n: 'Thutmosis IV', p: 'Tebe, Egypt', d: 'Han frigjorde den store sfinksen fra drivende sand og reiste drømmestelen mellom labbene dens — monumentets første kjente restaurering.' },
  ph_amenhotep_iii: { n: 'Amenhotep III', p: 'Tebe, Egypt', d: '«Den praktfulle»: han giftet seg med prinsesser fra Babylon til Mitanni, reiste Memnonkolossene og styrte et imperium i fred og på sitt rikeste.' },
  ph_akhenaten: { n: 'Eknaton', p: 'Akhetaton, Egypt', d: 'Kjetterkongen — han stengte de gamle tempelene, dyrket bare solskiven Aten, bygget en ny hovedstad i Amarna og tvang gjennom en revolusjon i kunst og tro som døde med ham.' },
  ph_tutankhamun: { n: 'Tutankhamon', p: 'Tebe, Egypt', d: 'Guttekongen som gjenopprettet de gamle gudene og døde rundt atten år gammel; den intakte graven hans, funnet i 1922, gjorde ham til den mest berømte egypteren som har levd.' },
  ph_ay: { n: 'Ay', p: 'Tebe, Egypt', d: 'En aldrende hoffmann som giftet seg med Tutankhamons enke for å ta tronen; den tiltenkte arvingen hans døde ung, og hæren overtok makten etterpå.' },
  ph_horemheb: { n: 'Horemheb', p: 'Tebe, Egypt', d: 'Generalen som lukket Amarna-kapittelet — han utslettet Eknatons minne, reformerte domstolene mot korrupsjon og valgte en soldat som arving.' },
  ph_ramses_i: { n: 'Ramses I', p: 'Pi-Ramses, Egypt', d: 'En yrkessoldat og Horemhebs valgte arving, som regjerte i knapt halvannet år og nesten tilfeldigvis grunnla et dynasti.' },
  ph_seti_i: { n: 'Seti I', p: 'Pi-Ramses, Egypt', d: 'Imperiets gjenoppretter — krigen hans gjenerobret tapt syrisk område, og tempelet hans i Abydos og graven KV17 hører til Egypts finest dekorerte bygg.' },
  ph_merneptah: { n: 'Merneptah', p: 'Pi-Ramses, Egypt', d: 'Han knuste en stor libysk invasjon i sitt femte år, og seiershymnen hans inneholder den første skriftlige omtalen av Israel utenfor Bibelen.' },
  ph_seti_ii: { n: 'Seti II', p: 'Pi-Ramses, Egypt', d: 'Regjeringstiden hans ble bestridt av en rivaliserende konge, Amenmesse, i Tebe — hoffintriger hadde erstattet imperiets militære storhet.' },
  ph_siptah: { n: 'Siptah', p: 'Pi-Ramses, Egypt', d: 'En lyttet guttekonge — klumpfoten hans synes på mumien — styrt av den mektige syriskfødte kansleren Bay.' },
  ph_twosret: { n: 'Tausret', p: 'Pi-Ramses, Egypt', d: 'Egypts andre dokumenterte kvinnelige farao; det korte styret hennes endte med 19. dynasti, midt i uroen som brakte et nytt dynasti til makten.' },
  ph_setnakhte: { n: 'Setnakhte', p: 'Pi-Ramses, Egypt', d: 'En outsider som grep den ledige tronen, gjenopprettet orden og grunnla 20. dynasti, som han overlot til den berømte sønnen sin, Ramses III.' },
  ph_ramses_iii: { n: 'Ramses III', p: 'Pi-Ramses, Egypt', d: 'Egypts siste store farao — han beseiret havfolkene til lands og til vanns i en krig som reddet det østlige Middelhavet, og døde i en haremssammensvergelse hvis rettsprotokoll er bevart.' },
  ph_ramses_iv: { n: 'Ramses IV', p: 'Pi-Ramses, Egypt', d: 'Steinbruddspapyrusen hans viser kongelige byggeprosjekter i sjelden detalj; doblede kornrasjoner til arbeiderne avslører en økonomi under press.' },
  ph_ramses_v: { n: 'Ramses V', p: 'Pi-Ramses, Egypt', d: 'Mumien hans bærer det eldste kjente tilfellet av kopper; onkelen tok både tronen og graven fra ham.' },
  ph_ramses_vi: { n: 'Ramses VI', p: 'Pi-Ramses, Egypt', d: 'Han overtok nevøens grav; gravkammeret i KV9 rommer de fineste kosmiske tekstene — solgudens nattlige ferd — i Kongenes dal.' },
  ph_ramses_vii: { n: 'Ramses VII', p: 'Pi-Ramses, Egypt', d: 'Kornprisene steg voldsomt, og de thebanske arbeiderne streiket igjen under ham — staten begynte å gå tom for sølv og brød.' },
  ph_ramses_viii: { n: 'Ramses VIII', p: 'Pi-Ramses, Egypt', d: 'Et spøkelse i kongelistene — knapt et år på tronen, ingen monumenter, ingen kjent grav, ingen mumie.' },
  ph_ramses_ix: { n: 'Ramses IX', p: 'Pi-Ramses, Egypt', d: 'Under ham undersøkte embedsmenn gravplyndringene hvis rettspapyri er bevart — staten var i ferd med å fortære sine egne døde konger.' },
  ph_ramses_x: { n: 'Ramses X', p: 'Pi-Ramses, Egypt', d: 'En dunkel siste regjeringstid: arbeiderne holdt seg hjemme av frykt for libyske plyndrere, og graven hans ble knapt påbegynt.' },
  ph_ramses_xi: { n: 'Ramses XI', p: 'Pi-Ramses, Egypt', d: 'Den siste Ramses regjerte bare til navnet, mens borgerkrig delte Egypt mellom generaler og Amons yppersteprester — døden hans avsluttet det nye riket.' },
  ph_smendes: { n: 'Smendes', p: 'Tanis, Egypt', d: 'Grunnleggeren av 21. dynasti, som styrte fra Tanis mens Amons yppersteprester regjerte i Tebe — et splittet land i skjør sameksistens.' },
  ph_amenemnisu: { n: 'Amenemnisu', p: 'Tanis, Egypt', d: 'En kort og dunkel regjeringstid mellom Smendes og den langlivede Psusennes I, i en epoke hvis kilder har tynnet seg ut til nesten ingenting.' },
  ph_psusennes_i: { n: 'Psusennes I', p: 'Tanis, Egypt', d: 'Den intakte sølvkisten og gullmasken hans, funnet i 1940, beviste at kongene i Tanis ennå rådet over skatter — i sølv, der faraoene i gamle dager hadde brukt gull.' },
  ph_amenemopet: { n: 'Amenemopet', p: 'Tanis, Egypt', d: 'Et rolig tiår i Tanis; begravelsen hans ble proppet inn i et gjenbrukt kammer etter hvert som kongerikets ressurser svant inn.' },
  ph_siamun: { n: 'Siamun', p: 'Tanis, Egypt', d: 'En sterkere konge i Tanis, husket for tempelbygging i Tanis og utover og knyttet av senere forskere til Egypt i Salomos tid.' },
  ph_psusennes_ii: { n: 'Psusennes II', p: 'Tanis, Egypt', d: 'Den siste kongen av 21. dynasti; ekteskapet mellom datteren hans og den mektige libyske familien til Sjosjenk brola neste dynastis vei til tronen.' },
  ph_shoshenq_i: { n: 'Sjosjenk I', p: 'Bubastis, Egypt', d: 'Etterkommeren av den libyske høvdingen som samlet Egypt igjen og marsjerte inn i Israel og Juda — Bibelens «Sjisjak», som førte bort tempelskattene i Jerusalem rundt 925 f.Kr.' },
  ph_osorkon_i: { n: 'Osorkon I', p: 'Bubastis, Egypt', d: 'Han arvet imperiet og brukte dets felttogsrikdom på templer — alene gavene hans til Bubastis løp opp i tonnvis av gull og sølv.' },
  ph_takelot_i: { n: 'Takelot I', p: 'Bubastis, Egypt', d: 'Regjeringstiden hans holdt nord i ro, men Tebe glapp ut av kongelig kontroll og over mot sine egne presterkonger — neste århundres splittelse var allerede synlig.' },
  ph_osorkon_ii: { n: 'Osorkon II', p: 'Bubastis, Egypt', d: 'De praktfulle Sed-festivalrelieffene hans skjuler den første store krisen: beseiret i slaget ved Karkar, så han Tebe krone en rivaliserende farao.' },
  ph_takelot_ii: { n: 'Takelot II', p: 'Bubastis, Egypt', d: 'Regjeringstiden hans falt sammen med et thebansk opprør som delte landet i rivaliserende kongeriker — krøniken til sønnen hans, Osorkon, daterer hvert eneste år av den lange borgerkrigen.' },
  ph_shoshenq_iii: { n: 'Sjosjenk III', p: 'Bubastis, Egypt', d: 'Han regjerte i 52 år over en krympet nord, mens Tebe adlød andre dynastier — kongedømmet i Egypt hadde blitt en regional affære.' },
  ph_pedubast_i: { n: 'Pedubast I', p: 'Tebe, Egypt', d: 'Den thebanske generalen som grunnla 23. dynasti som en åpen utfordring av Tanis — i tiår regjerte tre faraoer samtidig i et delt land.' },
  ph_tefnakht: { n: 'Tefnakht', p: 'Sais, Egypt', d: 'Fyrsten i det vestlige deltaet som bygget en koalisjon mot kushittene — slått av Pije, erklærte han seg likevel som farao i nord og grunnla 24. dynasti.' },
  ph_bakenranef: { n: 'Bakenranef', p: 'Sais, Egypt', d: '«Bokkoris» hos grekerne, husket som en lovgivende konge — helt til Sjabaka fikk ham brent levende og tok Egypt for Kush.' },
  ph_piye: { n: 'Pije', p: 'Napata, Nubia', d: 'Den nubiske kongen som seilte nordover og gjorde Egypt til sin; seiersstelen hans påbød generalene å bade og be før slaget, og kongelige pyramider reiste seg igjen i El-Kurru.' },
  ph_shabaka: { n: 'Sjabaka', p: 'Memfis, Egypt', d: 'Han konsoliderte kushittisk styre fra Memfis, restaurerte gamle monumenter og lot den memfitiske skapelsesteologien hugge inn i stein — Sjabaka-stenen som bevarte den for ettertiden.' },
  ph_shebitku: { n: 'Shebitku', p: 'Memfis, Egypt', d: 'Han sendte kushittiske hærer for å stanse Assyrias fremmarsj i Levanten — det første sammenstøtet som trakk assyrernes hevn ned over Egypt.' },
  ph_taharqa: { n: 'Taharka', p: 'Memfis, Egypt', d: 'Bibelens Tirhaka, en byggende konge hvis monumenter strakte seg fra Nubia til deltaet — helt til Assyria herjet Memfis og Tebe og gjorde slutt på kushittisk makt i Egypt.' },
  ph_tantamani: { n: 'Tantamani', p: 'Memfis, Egypt', d: 'Den siste kushittiske faraoen: han gjenerobret Egypt for en kort stund, men Assyrias motstøt brant Tebe så grundig at byen aldri fikk tilbake sin gamle storhet.' },
  ph_psamtik_i: { n: 'Psametik I', p: 'Sais, Egypt', d: 'En assyrisk vasall som overlevde herrene sine og gjorde Egypt uavhengig igjen — de greske leiesoldatene hans innledet deltaets greske tidsalder.' },
  ph_necho_ii: { n: 'Neko II', p: 'Sais, Egypt', d: 'Kanalgraveren og flåtebyggeren som drepte Josjia av Juda ved Megiddo — og sendte fønikere på historiens første dokumenterte seilas rundt Afrika.' },
  ph_psamtik_ii: { n: 'Psametik II', p: 'Sais, Egypt', d: 'Han ledet et straffetog dypt inn i Kush; graffitien fra de greske leiesoldatene hans i Abu Simbel er den eldste daterte greske skriften kjent fra Egypt.' },
  ph_apries: { n: 'Apries', p: 'Sais, Egypt', d: 'Bibelens «Hofra», hvis hær ikke klarte å redde Jerusalem fra Babylon; favoriseringen hans av greske tropper utløste det innfødte opprøret som reiste Amasis til tronen.' },
  ph_amasis_ii: { n: 'Amasis II', p: 'Sais, Egypt', d: 'Tronraneren som ble Herodots bilde på en klok og avslappet konge — han grunnla den greske handelsbyen Naukratis og overøste templene med gaver.' },
  ph_psamtik_iii: { n: 'Psametik III', p: 'Sais, Egypt', d: 'Konge i rundt seks måneder; perserne til Kambyses oversvømmet Egypt, og henrettelsen hans etter et håpløst opprør avsluttet det innfødte styrets tidsalder i et århundre.' },
  ph_cambyses_ii: { n: 'Kambyses II', p: 'Memfis, Egypt', d: 'Perserrikets erobrer av Egypt, kronet til farao i en bevisst omfavnelse av egyptisk tradisjon — selv om greske forfattere malte ham som en gal mann fordi han drepte helligoksen Apis.' },
  ph_darius_i: { n: 'Dareios I', p: 'Memfis, Egypt', d: 'En bedre konge enn gresk tradisjon innrømmer: han kodifiserte egyptisk lov, fullførte kanalen til Rødehavet og reparerte templer, og gjorde Egypt til imperiets rikeste provins.' },
  ph_xerxes_i: { n: 'Xerxes I', p: 'Memfis, Egypt', d: 'Storkongen fra perserkrigene styrte Egypt hardere, og de tunge kravene hans fremkalte opprøret etterfølgeren måtte slå ned.' },
  ph_artaxerxes_i: { n: 'Artaxerxes I', p: 'Memfis, Egypt', d: 'Egypt brøt ut under Inaros med athensk hjelp, og det krevde seks år og en stor flåte før Persia vant den rike provinsen tilbake.' },
  ph_darius_ii: { n: 'Dareios II', p: 'Memfis, Egypt', d: 'Persisk kontroll forfalt gjennom regjeringstiden hans; innen et år etter døden hans holdt den egyptiske fyrsten Amyrtaios deltaet igjen.' },
  ph_amyrtaeus: { n: 'Amyrtaios', p: 'Sais, Egypt', d: 'Opprørsfyrsten i Sais som kastet ut de persiske garnisonene og regjerte som den eneste kongen av 28. dynasti.' },
  ph_nefaarud_i: { n: 'Nefaarud I', p: 'Mendes, Egypt', d: 'Grunnleggeren av 29. dynasti i Mendes og en alliert av Sparta i den greske krigen mot Persia.' },
  ph_achoris: { n: 'Akoris', p: 'Mendes, Egypt', d: 'En energisk hersker som finansierte Kypros og Athen mot Persia og stemplet kartusjen sin på monumenter over alt — det innfødte Egypts dyktige sene blomstring.' },
  ph_nectanebo_i: { n: 'Nektanebos I', p: 'Sebennytos, Egypt', d: 'En general fra den mendesiske slekten som grep tronen, slo tilbake Persias store gjenerobringsforsøk og begynte Istempelet på File.' },
  ph_teos: { n: 'Teos', p: 'Sebennytos, Egypt', d: 'Han ledet Egypts siste offensive krig, inn i Syria — så tronranet nevøen hans med leiesoldatenes støtte, og felttoget kollapset.' },
  ph_nectanebo_ii: { n: 'Nektanebos II', p: 'Sebennytos, Egypt', d: 'Egypts siste innfødte farao, en overdådig beskytter av templer — helt til den store invasjonen til Artaxerxes III gjorde slutt på det innfødte styret for godt; legenden gjorde ham senere til Alexanders hemmelige far.' },
  ph_artaxerxes_iii: { n: 'Artaxerxes III', p: 'Memfis, Egypt', d: 'Den persiske gjenerobreren, hvis gjenerobring av Egypt var brutal; et tiår senere ødela Alexander imperiet, og Egypt skiftet hender igjen.' },
  ph_ptol_i: { n: 'Ptolemaios I Soter', p: 'Alexandria, Egypt', d: 'Aleksanders general som gjorde Egypt til sitt eget kongerike — han sikret seg Aleksanders kropp til Alexandria, grunnla Biblioteket og Museet og skrev den første historien om krigene.' },
  ph_ptol_ii: { n: 'Ptolemaios II Filadelfos', p: 'Alexandria, Egypt', d: '«Søsterkjærlig»: han giftet seg med fullsøsteren sin, Arsinoe II, løftet fyrtårnet på Faros og Biblioteket til sine høydepunkter og førte Egypt til sin største utstrekning.' },
  ph_ptol_iii: { n: 'Ptolemaios III Euergetes', p: 'Alexandria, Egypt', d: '«Velgjøreren» hevnet søsteren sin ved å invadere Syria og hente Egypts gudestatuer hjem; regjeringstiden hans var det ptolemeiske imperiets største utstrekning.' },
  ph_ptol_iv: { n: 'Ptolemaios IV Filopator', p: 'Alexandria, Egypt', d: 'Han slo Antiokos III ved Raphia — et slag med 100 000 menn og krigselefanter — ved å satse på innfødte egyptiske tropper, hvis nye makt innledet dynastiets fall.' },
  ph_ptol_v: { n: 'Ptolemaios V Epifanes', p: 'Alexandria, Egypt', d: 'En barnekonge hvis dekret på Rosettastenen — historiens nøkkel til hieroglyfene — belønnet prestenes lojalitet mens imperiet smuldret bort.' },
  ph_ptol_vi: { n: 'Ptolemaios VI Filometor', p: 'Alexandria, Egypt', d: 'Trettifem år med borgerkrig i egen familie, mot broren og med den medregjerende dronningen; han døde av skadene etter et fall, like etter en syrisk seier, og striden ulmet videre etter ham.' },
  ph_ptol_viii: { n: 'Ptolemaios VIII Euergetes II', p: 'Alexandria, Egypt', d: 'Den oppblåste, nådeløse overleveren: han drepte nevøkongen sin, giftet seg med søsteren og deretter med datteren hennes, og testamenterte Egypt til den dronningen som overlevde ham.' },
  ph_ptol_ix: { n: 'Ptolemaios IX Soter II', p: 'Alexandria, Egypt', d: '«Lathyros», kikertkongen — to ganger jaget ut av morens egen fraksjon og to ganger gjeninnsatt; feidene hans tømte Alexandria for de greske lærdene.' },
  ph_ptol_x: { n: 'Ptolemaios X Alexander I', p: 'Alexandria, Egypt', d: 'Han stjal tronen fra broren og skrev Egypt til Roma i testamentet sitt — et papirkrav Augustus innkrevde et århundre senere.' },
  ph_ptol_xi: { n: 'Ptolemaios XI Alexander II', p: 'Alexandria, Egypt', d: 'Nitten dager etter at han giftet seg med stemoren sin som medregent, drepte han henne — og folkmengden i Alexandria rev ham i stykker som hevn.' },
  ph_ptol_xii: { n: 'Ptolemaios XII Auletes', p: 'Alexandria, Egypt', d: '«Fløytespilleren» kjøpte romersk anerkjennelse med ruinøse bestikkelser, flyktet fra et innfødt opprør i 58 f.Kr. og vendte tilbake bak romerske legioner; den eldste datteren hans var Kleopatra VII.' },
  ph_berenice_iv: { n: 'Berenike IV', p: 'Alexandria, Egypt', d: 'Hun regjerte i farens eksilår og døde for det — den tilbakevendte Ptolemaios XII henrettet sin egen datter.' },
  ph_ptol_xiii: { n: 'Ptolemaios XIII', p: 'Alexandria, Egypt', d: 'Bror-ektefellen hvis regenter jaget Kleopatra ut og beleiret Cæsar i Alexandria; han druknet i Nilen, i rustning, etter sitt siste nederlag.' },
  ph_ptol_xiv: { n: 'Ptolemaios XIV', p: 'Alexandria, Egypt', d: 'Den yngre broren, innsatt som Kleopatras ektefelle — død innen tre år, angivelig på ordre fra søster-ektefellen.' },
  ph_caesarion: { n: 'Ptolemaios XV Cæsarion', p: 'Alexandria, Egypt', d: '«Lille Cæsar», Kleopatras sønn med Julius Cæsar og den siste av ptolemeerne — Oktavian lot den syttenårige henrette etter Actium, med bemerkningen at for mange Cæsarer ikke var godt.' },
});

/* Mesopotamian rulers - 45 entries (2026-10-30) */
Object.assign(window.DATA_NO, {
  me_enmebaragesi: { n: 'Enmebaragesi', p: 'Kish, Mesopotamia', d: 'Den første mesopotamiske herskeren arkeologien kan bevise — attestert på en knust vase fra Nippur, og i tradisjonen husket som far til kongen Gilgamesj kjempet mot.' },
  me_gilgamesh: { n: 'Gilgamesj', p: 'Uruk, Mesopotamia', d: 'En virkelig konge i Uruk omkring 2700 f.Kr., senere helten i verdens første store epos — bymuren hans, forteller den sumeriske kongelisten, strakte seg over fem kilometer.' },
  me_mesannepada: { n: 'Mesannepada', p: 'Ur, Mesopotamia', d: 'Grunnleggeren av Urs første dynasti, hvis kongelige gravlund frembrakte de gylne hjelmene og lyrerne med oksehoder som definerer Sumers storhetstid.' },
  me_eannatum: { n: 'Eannatum', p: 'Lagash, Mesopotamia', d: 'Han hogg ut Gribbstelen, som hyller seieren over Umma — historiens første detaljerte bilde av et slag, med skjoldmur, spydmenn og en konge på stridsvogn.' },
  me_lugalzagesi: { n: 'Lugalzagesi', p: 'Uruk, Mesopotamia', d: 'Den siste sumeriske overherren: han samlet sørlandet fra Uruk, og tapte så alt til Sargon av Akkad, som ifølge sagnet førte ham i hundehalsbånd til Nippurs porter.' },
  me_sargon: { n: 'Sargon av Akkad', p: 'Akkad, Mesopotamia', d: 'Munnskjenken som grep kongemakten og smed historiens første flernasjonale imperium fra sin by Agade — hvis beliggenhet fortsatt er ukjent; sagnene fortalte hvordan spedbarnet i en sivkurv drev nedover Eufrat.' },
  me_naram_sin: { n: 'Naram-Sin', p: 'Akkad, Mesopotamia', d: 'Den første mesopotamiske kongen som erklærte seg selv for gud — fjellseiersrelieffet hans viser gudekongen marsjere over Zagros, og under ham nådde imperiet sin største utstrekning før det begynte å sprekke.' },
  me_sharkalisharri: { n: 'Shar-Kali-Sharri', p: 'Akkad, Mesopotamia', d: '«Konge over de fire verdenshjørnene»: en regjeringstid med endeløse felttog som holdt imperiet sammen — etter ham oppløste Akkad seg under gutienes styre i løpet av én generasjon.' },
  me_utuhegal: { n: 'Utu-Hegal', p: 'Uruk, Mesopotamia', d: 'Uruk-kongen som drev ut gutiene fra fjellene og gjenopprettet den sumeriske kongemakten — seiersstelen hans er blant de siste store monumentene fra det gamle Sumer.' },
  me_gudea: { n: 'Gudea', p: 'Lagash, Mesopotamia', d: 'Herskeren i Lagash som etterlot seg mer enn to dusin fredfulle diorittstatuer — og en beretning på leiresylindre om et gudepåbudt drømmebilde som fikk ham til å bygge Ningirsus tempel.' },
  me_urnammu: { n: 'Ur-Nammu', p: 'Ur, Mesopotamia', d: 'Grunnleggeren av Ur III-imperiet: hans store ziggurat i Ur står fortsatt, og lovsamlingen hans — århundrer før Hammurapis — er den eldste som er funnet.' },
  me_shulgi: { n: 'Shulgi', p: 'Ur, Mesopotamia', d: 'En 48 år lang regjeringstid med veistasjoner, standardiserte skriverskoler og lovverk for hele riket — kronet av en hymne han dikterte selv, der han skrøt av å ha løpt 320 kilometer på én dag.' },
  me_ibbisin: { n: 'Ibbi-Sin', p: 'Ur, Mesopotamia', d: 'Den siste kongen i Ur, utsultet av amorittiske herjinger og elamittiske hærer — klagesangen over Urs fall ble tidens mest kopierte dikt.' },
  me_ishbierra: { n: 'Ishbi-Erra', p: 'Isin, Mesopotamia', d: 'En amorittisk offiser i Urs tjeneste som kastet ut elamittene og grunnla Isin-dynastiet, og gjorde krav på det fallne imperiets lærde og hellige arv.' },
  me_lipitishtar: { n: 'Lipit-Ishtar', p: 'Isin, Mesopotamia', d: 'Lovsamlingen hans, hugget ut halvannet århundre før Hammurapis, beskyttet enker og foreldreløse — og skolehymnene hans gjorde ham senere til skrivernes gud.' },
  me_rimsin: { n: 'Rim-Sin I', p: 'Larsa, Mesopotamia', d: 'Han regjerte i seksti år over Larsa — lengre enn noen dokumentert konge før moderne tid — og tapte så hovedstaden sin til Hammurapi av Babylon i ett eneste felttog.' },
  me_sumuabum: { n: 'Sumu-abum', p: 'Babylon, Mesopotamia', d: 'Amoritkhøvdingen som gjorde Babylon til et dynastisete — en liten elveby som hans slekt skulle løfte frem til verdens sentrum.' },
  me_hammurabi: { n: 'Hammurapi', p: 'Babylon, Mesopotamia', d: 'Skaperen av Babylons imperium — han tok Larsa, Mari og Assyria etter tur, og lovstelen hans, reist «for at de sterke ikke skulle undertrykke de svake», ble i århundrer stående som selve rettferdighetens symbol.' },
  me_samsuiluna: { n: 'Samsu-iluna', p: 'Babylon, Mesopotamia', d: 'Han arvet farens imperium, slo tilbake en kassittisk invasjon, og så det fjerne sør løsrive seg som dynastiet i Sjølandet — imperiets kanter var allerede i ferd med å rakne.' },
  me_burnaburiash: { n: 'Burna-Buriash II', p: 'Babylon, Mesopotamia', d: 'Kassittkongen hvis brev til Egyptens faraoer, funnet i Amarna, forhandler om gull og kongelige bruder — bronsealderens stormaktsdiplomati på sitt aller beste.' },
  me_kurigalzu_ii: { n: 'Kurigalzu II', p: 'Babylon, Mesopotamia', d: 'En stridende kassittkonge som stanset Assyrias fremvekst i hard kamp og prydet Dur-Kurigalzu med en ziggurat hvis stubbe fortsatt ruver vest for Bagdad.' },
  me_nebuchadnezzar_i: { n: 'Nebukadnesar I', p: 'Babylon, Mesopotamia', d: 'Han hevnet Babylons ydmykelse: herjet dypt inn i Elam og førte guden Marduks stjålne statue hjem i triumf — en gjerning senere babylonske konger feiret igjen og igjen.' },
  me_mardukaplaiddina: { n: 'Marduk-apla-iddina II', p: 'Babylon, Mesopotamia', d: 'Bibelens «Merodak-Baladan»: en kaldeisk høvding som tok Babylon to ganger og trotset Sargon II og Sanherib i to tiår, mens han søkte allierte så langt borte som i Juda.' },
  me_shamashshumukin: { n: 'Shamash-shum-ukin', p: 'Babylon, Mesopotamia', d: 'Assurbanipals bror, innsatt som Babylons konge under assyrisk overherredømme — hans seks år lange opprør for Babylons frihet endte i en beleiring der han, ifølge én kilde, brant i sitt eget palass.' },
  me_nabopolassar: { n: 'Nabopolassar', p: 'Babylon, Mesopotamia', d: 'Kaldeeren som gjenopprettet Babylons frihet og begravde Assyria — med mediske allierte stormet han Ninive i 612 f.Kr. og overlot de siste felttogene i vest til sønnen sin.' },
  me_nebuchadnezzar_ii: { n: 'Nebukadnesar II', p: 'Babylon, Mesopotamia', d: 'Babylons største konge: han slo Egypt ved Karkemisj, tok Jerusalem og brente det i 586 f.Kr., og bygde Ishtarporten og zigguraten som huskes som Babels tårn.' },
  me_amelmarduk: { n: 'Amel-Marduk', p: 'Babylon, Mesopotamia', d: 'Bibelens «Evil-Merodak», som løslatte den fangne kongen av Juda fra fengselet — to år senere myrdet svogeren hans, Neriglissar, ham.' },
  me_neriglissar: { n: 'Neriglissar', p: 'Babylon, Mesopotamia', d: 'En babylonsk general som tok tronen ved mord, førte krig i Kilikia og døde etter fire år — han etterlot en guttearving til sammensvornes nåde.' },
  me_labashimarduk: { n: 'Labashi-Marduk', p: 'Babylon, Mesopotamia', d: 'En guttekonge i ni måneder, myrdet av sammensvorne som ga kronen videre til Nabonidus — dynastiets siste rykk før fallet.' },
  me_nabonidus: { n: 'Nabonidus', p: 'Babylon, Mesopotamia', d: 'Babylons siste konge: en tilbeder av måneguden Sin som fikk Marduks prester mot seg, tilbrakte et tiår ved oasen Teima, og tapte byen sin til Kyros av Persia uten kamp i 539 f.Kr.' },
  me_shamshiadad: { n: 'Shamshi-Adad I', p: 'Shubat-Enlil, Assyria', d: 'Amoritten som hogde ut et imperium i Øvre Mesopotamia, fra Assur til Middelhavet, og plasserte sønnene sine som guvernører — brevene der han irettesetter en vill arving er bevart i arkivene i Mari.' },
  me_zimrilim: { n: 'Zimri-Lim', p: 'Mari, Mesopotamia', d: 'Kongen av Mari hvis palassarkiv — tusenvis av brev, rettssaker og profetier — er vinduet vårt inn til det gammelbabylonske livet; Hammurapi tok byen hans og brente den.' },
  me_ashuruballit_i: { n: 'Assuruballit I', p: 'Assur, Assyria', d: 'Han kastet av seg Mitannis åk og gjorde Assyria til en stormakt — den første assyreren som skrev til Egypt som jevnbyrdig blant «store konger».' },
  me_tukultininurta_i: { n: 'Tukulti-Ninurta I', p: 'Assur, Assyria', d: 'Han knuste kassittene og tok Babylon, og fraktet Marduks statue bort — deretter bygde han en ny hovedstad, Kar-Tukulti-Ninurta, og døde myrdet av egne sønner.' },
  me_tiglathpileser_i: { n: 'Tiglat-Pileser I', p: 'Assur, Assyria', d: 'En bronsealderens kriger og jeger som marsjerte til Middelhavet og hevdet å ha drept 920 løver fra stridsvognen; etter ham skrumpet Assyria inn til hjemlandet i to århundrer.' },
  me_adadnirari_ii: { n: 'Adad-nirari II', p: 'Assur, Assyria', d: 'Gjenreiseren: han brøt den arameiske ringen rundt Assur, gjenerobret Khabur-landene, og satte Assyria på den to århundrer lange veien mot imperiet.' },
  me_ashurnasirpal_ii: { n: 'Assurnasirpal II', p: 'Nimrud, Assyria', d: 'Levantens skrekk, som flyttet hovedstaden til Nimrud — relieffer av flådde opprørere og et gjestebud for 69 574 gjester viser begge sidene av assyrisk kongemakt.' },
  me_shalmaneser_iii: { n: 'Salmanassar III', p: 'Nimrud, Assyria', d: 'Hans 34 år med felttog møtte Levantens første store koalisjon ved Karkar i 853 f.Kr. — og den svarte obelisken viser Israels Jehu som bøyer seg for å yte tributt.' },
  me_tiglathpileser_iii: { n: 'Tiglat-Pileser III', p: 'Assur, Assyria', d: 'Reformkeiseren: en profesjonell hær, masseportering som politikk, Babylon erobret som «Pulu», og Juda og Israel gjort til tributtstater — Bibelens «Pul».' },
  me_sargon_ii: { n: 'Sargon II', p: 'Dur-Sharrukin, Assyria', d: 'Han tok Samaria og gjorde slutt på Israels kongedømme, bygde en ny hovedstad med firkantete murer ved Dur-Sharrukin, og falt i kamp mot kimmerierne — liket hans ble aldri funnet.' },
  me_sennacherib: { n: 'Sanherib', p: 'Ninive, Assyria', d: 'Han gjorde Ninive til et underverk av kanaler og murer, brente Babylon i 689 f.Kr. og beleiret Jerusalem i 701 f.Kr. — og ble myrdet av egne sønner i et tempel.' },
  me_esarhaddon: { n: 'Esarhaddon', p: 'Ninive, Assyria', d: 'Han gjenreiste Babylon som faren jevnet med jorden, erobret Egypt og tok Memfis i 671 f.Kr., og døde siden på veien til Egypt igjen — etter å ha sikret en nøye planlagt dobbel arvefølge.' },
  me_ashurbanipal: { n: 'Assurbanipal', p: 'Ninive, Assyria', d: 'Den lærde kongen: biblioteket hans i Ninive bevarte eposet om Gilgamesj for ettertiden, relieffene viser ham holde fest under en død fiendes hode — og innen én generasjon etter hans død var imperiet borte.' },
  me_sinsharishkun: { n: 'Sin-shar-ishkun', p: 'Ninive, Assyria', d: 'Regjeringstiden hans rant ut i borgerkrig — så kom mederne og babylonerne: Ninive falt i 612 f.Kr. så fullstendig at stedet ble glemt i løpet av århundrer.' },
  me_ashuruballit_ii: { n: 'Assuruballit II', p: 'Harran, Assyria', d: 'Assyrias siste konge, kronet i Harran over imperiets rester; egyptisk unnsetning mislyktes, og med nederlaget hans forsvant Assyria fra historien i to tusen år.' },
});
/* no translations — Napoleonic Wars battles (2026-10-30) */
Object.assign(window.DATA_NO, {
  nb_toulon: { n: 'Beleiringen av Toulon', p: 'Toulon, Frankrike', d: 'En ung artillerikaptein ved navn Napoleon Bonaparte planlegger erobringen av den britiskokkuperte marinebasen — hans første kommando, og springbrettet til alt som følger.' },
  nb_lodi: { n: 'Slaget ved Lodi', p: 'Lodi, Italia', d: 'Angrepet over Addabroen gjør den unge generalen til en helt for sine egne soldater — «den lille korporalen» er født, og Italia blir hans laboratorium.' },
  nb_arcole: { n: 'Slaget ved Arcole', p: 'Arcole, Italia', d: 'Tre dager med kamp i Alpone-myrene: Napoleon tar personlig den berømte broen under beskytning og tvinger til slutt Alvinczis østerrikere tilbake.' },
  nb_rivoli: { n: 'Slaget ved Rivoli', p: 'Rivoli, Italia', d: 'Mesterstykket som avslutter det første italienske felttoget — konsentriske angrep knuser fire østerrikske kolonner, og Mantua kapitulerer endelig.' },
  nb_pyramids: { n: 'Slaget ved pyramidene', p: 'Giza, Egypt', d: '«Soldater, fra høyden av disse pyramidene ser førti århundrer ned på dere» — infanterikvadrene knuser mamelukkenes kavaleri foran Kairo.' },
  nb_nile: { n: 'Slaget på Nilen', p: 'Abukirbukta, Egypt', d: 'Nelson ankrer opp ved siden av den franske flåten og tilintetgjør den i nattens løp — hæren i Egypt er strandet, og Storbritannia hersker over Middelhavet.' },
  nb_novi: { n: 'Slaget ved Novi', p: 'Novi Ligure, Italia', d: 'Suvorovs østerriksk-russiske hær knuser franskmennene i Appenninenes forberge; den unge generalen Joubert blir drept av den første salven.' },
  nb_marengo: { n: 'Slaget ved Marengo', p: 'Marengo, Italia', d: 'Et slag er tapt, og reddes så av Desaix’ tilbakevendende kolonne og et massert kavaleriangrep — og gjenfortelles av Napoleon for alltid som konsulatets grunnleggende legende.' },
  nb_hohenlinden: { n: 'Slaget ved Hohenlinden', p: 'Hohenlinden, Tyskland', d: 'Moreaus bakhold i de frosne skogene vest for München knuser en østerriksk hær og driver Wien inn i freden i Lunéville.' },
  nb_copenhagen: { n: 'Slaget ved København', p: 'København, Danmark', d: 'Nelson holder kikkerten for det blinde øyet, ignorerer signalet om å trekke seg tilbake og tilintetgjør den danske flåten — Storbritannias svar på det væpnede nøytralitetsforbundet i nord.' },
  nb_ulm: { n: 'Slaget ved Ulm', p: 'Ulm, Tyskland', d: 'Syv franske korps svinger i en kjempebue rundt Schwarzwald og svelger hele Macks østerrikske hær — 60 000 fanger for knapt 500 franske falne.' },
  nb_trafalgar: { n: 'Slaget ved Trafalgar', p: 'Kap Trafalgar, Spania', d: 'Nelson bryter den fransk-spanske linjen utenfor Kap Trafalgar og vinner den mest avgjørende sjøseieren i britisk historie — han dør i triumfens øyeblikk; en invasjon av England blir umulig.' },
  nb_austerlitz: { n: 'Slaget ved Austerlitz', p: 'Austerlitz, Mähren', d: 'Napoleons mesterstykke: han lokker de allierte til å forlate Pratzenhøyden og deler senteret deres i tåken — «solen over Austerlitz» avslutter den tredje koalisjonen.' },
  nb_jena_auerstedt: { n: 'Slaget ved Jena–Auerstedt', p: 'Jena, Tyskland', d: 'To slag på én morgen: Napoleon knuser en prøyssisk hær ved Jena mens Davout slår en større ved Auerstedt — Preussen kollapser i løpet av tre uker.' },
  nb_eylau: { n: 'Slaget ved Eylau', p: 'Eylau, Preussen', d: 'Et frossent, uavgjort slakteri i snøen — Napoleons første store motgang, mot Bennigsens russere; Ney rir over slagmarken: «For et slakteri! Og uten noe resultat».' },
  nb_friedland: { n: 'Slaget ved Friedland', p: 'Friedland, Preussen', d: 'Lannes låser fast russerne med ryggen mot elven Alle, og Napoleon gjør jobben ferdig — veien til Tilsit åpner seg, der to keisere deler Europa.' },
  nb_bailen: { n: 'Slaget ved Bailén', p: 'Bailén, Spania', d: 'Et helt fransk korps under general Dupont kapitulerer for spanske regulære styrker — det første store nederlaget for Napoleons våpen, og nyheten tenner opprør over hele Europa.' },
  nb_vimeiro: { n: 'Slaget ved Vimeiro', p: 'Vimeiro, Portugal', d: 'Wellesleys linjer på baksiden av høyden knuser Junots angrep — det første slaget utkjempet av Storbritannias halvøyhær åpner seks år med nesten uavbrutt fremgang.' },
  nb_zaragoza: { n: 'Beleiringen av Zaragoza', p: 'Zaragoza, Spania', d: 'To beleiringer og gatekamper fra hus til hus gjør Palafox’ by til et synonym for folkelig motstand — rundt 50 000 spanjoler dør på få måneder.' },
  nb_somosierra: { n: 'Slaget ved Somosierra', p: 'Somosierrapasset, Spania', d: 'Polske lettkavalerister rir rett opp det røykhyllede fjellpasset og inn i de spanske kanonene og åpner veien til Madrid — epokens mest berømte kavaleriprestasjon.' },
  nb_corunna: { n: 'Slaget ved A Coruña', p: 'A Coruña, Spania', d: 'Den grufulle retretten til kysten koster den britiske hæren dens øverstkommanderende: Sir John Moore faller som seierherre mens flåten bærer troppene hjem.' },
  nb_talavera: { n: 'Slaget ved Talavera', p: 'Talavera, Spania', d: 'En natt med forvirret kamp og et hardt angrep ved middagstid mislykkes mot Wellesleys linje — et visegrevskap til Wellington, og bevis på at krigen i Spania kan vinnes.' },
  nb_eckmuhl: { n: 'Slaget ved Eckmühl', p: 'Eckmühl, Tyskland', d: 'Davouts korps holder stand alene, og så tar Napoleon personlig østerrikerne i flanken — erkehertug Karl unnslipper nord for Donau, slått.' },
  nb_aspern_essling: { n: 'Slaget ved Aspern-Essling', p: 'Wien, Østerrike', d: 'Napoleons første store nederlag: Donauflommene kutter pontongbroene, og Lannes dør mens han forsvarer kornmagasinet i Essling — Europa lærer at keiseren kan slås.' },
  nb_wagram: { n: 'Slaget ved Wagram', p: 'Wagram, Østerrike', d: '300 000 mann og det største slaget Europa så langt har sett: en frontal utmattelseskamp over Marchfeld, med storbatterier som fyrer med direktesikte, avslutter den femte koalisjonen.' },
  nb_busaco: { n: 'Slaget ved Bussaco', p: 'Bussaco, Portugal', d: 'Masséna kaster hæren oppover gjennom morgentåken og blir blodig slått tilbake på Serra — Wellington smetter deretter bak Torres Vedras-linjene.' },
  nb_torres_vedras: { n: 'Torres Vedras-linjene', p: 'Torres Vedras, Portugal', d: '152 fort og redutter skjuler Wellingtons hær for en fransk vinter i sult — «den mest ubehagelige kampanjen» Masséna noensinne utkjempet, uten ett eneste åpent slag.' },
  nb_fuentes_onoro: { n: 'Slaget ved Fuentes de Oñoro', p: 'Fuentes de Oñoro, Spania', d: 'Tre dager rundt en brennende landsby — «Hadde Boney vært her, hadde vi tapt»: Wellington holder stand, og Massénas siste offensiv i Portugal er over.' },
  nb_albuera: { n: 'Slaget ved Albuera', p: 'Albuera, Spania', d: 'Soults flankemarsj møter Beresfords mangespråklige hær: den britiske fusilierbrigaden avgjør hele krigens blodigste ettermiddag.' },
  nb_ciudad_rodrigo: { n: 'Beleiringen av Ciudad Rodrigo', p: 'Ciudad Rodrigo, Spania', d: 'Wellington stormer grensefestningen på tolv vinterdager, og hans tunge stormavdeling inntar den store breksjen — porten til felttoget i 1812.' },
  nb_badajoz: { n: 'Beleiringen av Badajoz', p: 'Badajoz, Spania', d: 'Krigens blodigste storm: tre breksjer erobres i en natt av raseri, og en plyndring som blir en flekk på hærens minne.' },
  nb_salamanca: { n: 'Slaget ved Salamanca', p: 'Salamanca, Spania', d: 'Wellington ser Marmonts hær strekke seg for langt ut og slår til i de førti minuttene som ødelegger den — «min dyktigste seier», i hans egne ord.' },
  nb_smolensk: { n: 'Slaget ved Smolensk', p: 'Smolensk, Russland', d: 'Grande Armée tar en brennende by og finner ingen avgjørelse — Kutuzovs hær unnslipper østover og lokker franskmennene stadig dypere inn i Russland.' },
  nb_borodino: { n: 'Slaget ved Borodino', p: 'Borodino, Russland', d: 'Den blodigste enkeltdagen i Napoleonskrigene: den store redutten tas og gjenerobres, 70 000 faller — og Kutuzovs hær trekker seg intakt unna for å kjempe igjen.' },
  nb_maloyaroslavets: { n: 'Slaget ved Malojaroslavets', p: 'Malojaroslavets, Russland', d: 'En liten by skifter eier åtte ganger; når støvet legger seg, vender Napoleon fra den nye sørlige veien tilbake til den utbrente hovedveien fra Moskva — retretten er beseglet.' },
  nb_berezina: { n: 'Slaget ved Berezina', p: 'Berezina, Russland', d: 'Éblés pontongbyggere bygger broer ut i en iskald elv mens begge bredder brenner — Grande Armée unnslipper en dødelig felle, og «Bérézina» blir franskmennenes ord for en overlevd katastrofe.' },
  nb_lutzen: { n: 'Slaget ved Lützen', p: 'Lützen, Tyskland', d: 'Napoleon, tilbake fra Russland med en hær av ferske rekrutter, overrasker de allierte i solsikkeåkrene der Gustav Adolf falt 180 år tidligere — de lister seg unna igjen under natten.' },
  nb_bautzen: { n: 'Slaget ved Bautzen', p: 'Bautzen, Tyskland', d: 'En to dagers seier uten fellen: en tapt ordre lar de allierte unnslippe østover — begge sider går med på våpenstillstanden i Pläswitz og teller rekrutter.' },
  nb_grossbeeren: { n: 'Slaget ved Großbeeren', p: 'Großbeeren, Tyskland', d: 'Oudinots marsj mot Berlin stoppes i et tordenvær av Bülows prøyssere — mange av dem ferske landvermenn — og hovedstaden kommer for godt utenfor franskmennenes rekkevidde.' },
  nb_dresden: { n: 'Slaget ved Dresden', p: 'Dresden, Tyskland', d: 'Napoleons siste store seier på tysk jord: et motangrep fra den tallmessig underlegne garnisonen svelger 35 000 allierte fanger — gjengjeldt innen få dager ved Kulm.' },
  nb_kulm: { n: 'Slaget ved Kulm', p: 'Kulm, Böhmen', d: 'Vandamme forfølger fienden nedover fjellovergangene og blir tatt i dalens munning — 13 000 franske fanger utligner regnskapet fra Dresden.' },
  nb_dennewitz: { n: 'Slaget ved Dennewitz', p: 'Dennewitz, Tyskland', d: 'En andre marsj mot Berlin dør i et prøyssisk motstøt som knuser Neys korps — Bernadottes svensker forsegler flanken.' },
  nb_leipzig: { n: 'Slaget ved Leipzig (1813)', p: 'Leipzig, Tyskland', d: 'Folkeslaget ved Leipzig: 600 000 mann over fire dager, Europas største slag frem til verdenskrigen — det saksiske korpset deserterer midt i kampen, og keiserdømmet øst for Rhinen er over.' },
  nb_hanau: { n: 'Slaget ved Hanau', p: 'Hanau, Tyskland', d: 'Wrede forsøker å sperre franskmennenes vei hjem bak Kinzig — Grande Armée på retrett trenger likevel rett gjennom ham og når Rhinen.' },
  nb_victoria: { n: 'Slaget ved Vitoria', p: 'Vitoria, Spania', d: 'Den franske hæren oppløses i en trafikkork av plyndringsvogner på veien til Frankrike: Joseph Bonaparte mister Spania, tronen sin — og kammersølvet sitt.' },
  nb_la_rothiere: { n: 'Slaget ved La Rothière', p: 'La Rothière, Frankrike', d: 'Napoleon angriper de allierte kolonnene i snøen i Champagne — og for første gang føres slaget mot ham i bokene.' },
  nb_montmirail: { n: 'Slaget ved Montmirail', p: 'Montmirail, Frankrike', d: 'Seksdagersfelttoget på sitt høydepunkt: to allierte hærer slås den ene etter den andre av samme franske styrke på to dager — den gamle magien vender kort tilbake.' },
  nb_craonne: { n: 'Slaget ved Craonne', p: 'Craonne, Frankrike', d: 'Den unge garden blør seg hvit i stormingen av platået over Chemin des Dames — en seier kjøpt til en pris som sjokkerer selv marskalkene; veien til Laon holder seg stengt.' },
  nb_paris_battle: { n: 'Slaget om Paris', p: 'Paris, Frankrike', d: 'Seks dager med allierte angrep; marskalkene overgir hovedstaden — og Napoleon, forlatt av sitt eget senat, abdiserer i Fontainebleau i løpet av uken.' },
  nb_toulouse: { n: 'Slaget ved Toulouse', p: 'Toulouse, Frankrike', d: 'Soults feltbefestninger koster halvøyhæren dens blodigste franske ettermiddag — begge sider kjemper videre i en krig som tok slutt da Paris falt og Napoleon abdiserte.' },
  nb_ligny: { n: 'Slaget ved Ligny', p: 'Ligny, Belgia', d: 'Napoleons siste seier: prøysserne slås tilbake fra bekken ved Ligny, den gamle Blücher kastes av hesten i et kavaleriangrep — likevel er hæren ikke knust, og den vil marsjere.' },
  nb_quatre_bras: { n: 'Slaget ved Quatre Bras', p: 'Quatre Bras, Belgia', d: 'Neys langsomme angrep møtes av Wellingtons linjer, ankommet i siste stund, midt blant rugen — veikrysset holder, og de to koalisjonshærene samles ved Waterloo to dager senere.' },
  nb_wavre: { n: 'Slaget ved Wavre', p: 'Wavre, Belgia', d: 'Grouchy kjemper en sideforestilling ved Wavre mens Waterloo-kanonene dundrer — 33 000 mann og hele felttoget avhenger av en marsj han aldri gjennomfører.' },
});

/* no translations — Aleksander den stores felttog (2026-10-30) */
Object.assign(window.DATA_NO, {
  aw_granicus: { n: 'Slaget ved Granikos', p: 'Elven Granikos, Anatolia', d: 'I sitt første store slag i Asia rir Aleksander nesten rett mot det persiske senteret over elven og unngår døden så vidt — men det makedonske kavaleriet knuser satrapenes linje; veien inn i Dareios’ rike står åpen.' },
  aw_issus: { n: 'Slaget ved Issos', p: 'Issos, Kilikia', d: 'Dareios III kommer seg bak Aleksander i Kilikia — og møter ham på en kystslette for smal til hans tallmessige overmakt; storkongen flykter og etterlater mor, kone og det gylne teltet, mens Aleksander avslår alle fredstilbud.' },
  aw_tyre: { n: 'Beleiringen av Tyros', p: 'Tyros, Fønikia', d: 'Tyros nekter å slippe Aleksander inn og holder stand i sju måneder fra øya en halv kilometer utenfor kysten; han fyller sundet med en vall — oldtidens store ingeniørbeleiring, som ender med storm, massakre og 30 000 innbyggere solgt som slaver.' },
  aw_alexandria_found: { n: 'Grunnleggelsen av Alexandria', p: 'Nildeltaet, Egypt', d: 'Tilbake fra Ammons orakel i Siwa stikker Aleksander ut Alexandria ved Faros, øya Homer sang om — byen som blir ptolmeernes hovedstad og hjemmet til biblioteket, museion og Faros-fyrtårnet.' },
  aw_gaugamela: { n: 'Slaget ved Gaugamela', p: 'Gaugamela, Assyria', d: 'Dareios planerer terrenget for sigdstridsvognene og en enorm hær; Aleksander glir med linjen mot høyre og kaster kilen gjennom det persiske senteret — storkongen flykter til Ekbatana, og Babylon, Susa og Persepolis åpner portene.' },
  aw_persian_gate: { n: 'Slaget ved perserportene', p: 'Zagros-fjellene, Persia', d: 'Ariobarzanes stenger det trange passet med noen tusen mann og stopper hele hæren i ukevis — Thermopylene baklengs; Aleksander deler styrkene og går ham i flanken gjennom snøen, med Persepolis og rikets skattkammer like bortenfor.' },
  aw_alexandria_eschate: { n: 'Grunnleggelsen av Alexandria Eschate', p: 'Jaxartes, Sogdia', d: 'Ved Jaxartes — for grekerne verdens ytterste rand — grunnlegger Aleksander «Aleksandria den ytterste», dagens Khujand, og slår de skytiske rytterne som rider over elven for å møte ham.' },
  aw_hydaspes: { n: 'Slaget ved Hydaspes', p: 'Elven Hydaspes, India', d: 'I monsunregn setter Aleksander en del av hæren over den flommende elven om natten og beseirer Porus’ 200 krigselefanter — hans kostbareste seier; ved Hyphasis nekter veteranene å marsjere østover, og Aleksander vender om.' },
  ww_sarajevo: { n: 'Attentatet i Sarajevo', p: 'Sarajevo, Bosnia', d: 'Gavrilo Princip skyter erkehertug Franz Ferdinand ved Latinerbroen — gnisten som Wiens ultimatum forvandler til en europeisk storkrig i løpet av fem uker.' },
  ww_july_crisis: { n: 'Julkrisen', p: 'Wien, Østerrike', d: 'En måned med ultimatum og mobiliseringsur: Wien straffer Serbia, Berlin gir Wien en «blank sjekk», Russland mobiliserer — og hver generalstabs tidsplan starter en krig ingen kan stoppe.' },
  ww_frontiers: { n: 'Grenseslagene', p: 'Charleroi, Belgia', d: 'Den franske Plan XVII marsjerer inn i tyske kanoner i Lorraine og Ardennene; ved Mons avfyrer det lille britiske ekspedisjonskorpset sine første skudd — så faller alle de allierte tilbake for Schlieffen-fremrykkingen.' },
  ww_tannenberg: { n: 'Slaget ved Tannenberg', p: 'Stębark (Tannenberg), Øst-Preussen', d: 'Hindenburg og Ludendorff omringer Samsonovs andre armé i de østprøyssiske sjøene — 90 000 fanger, generalen skyter seg selv, og Tysklands legende om østfronten er født.' },
  ww_galicia_1914: { n: 'Slaget om Galicia', p: 'Lwów, Galicia', d: 'Det største slaget i 1914: russiske hærer bryter den østerriksk-ungarske fronten, tar Lwów og når Karpatene — imperiet mister sin beste felthær, og krigen kommer til ukrainsk jord.' },
  ww_marne_1: { n: 'Det første slaget ved Marne', p: 'Marne, Frankrike', d: 'Joffres motstøt — parisiske taxier som frakter reserver til fronten — bryter det tyske fremstøtet mot Paris; bevegelseskrigen ender i skyttergravslinjer som knapt vil flytte seg på fire år.' },
  ww_masurian_1: { n: 'Det første slaget om de masuriske sjøene', p: 'Masuriske sjøer, Øst-Preussen', d: 'En ny tysk seier kaster Rennenkampfs første armé ut av Preussen — og østfronten legger seg for vinteren i den polske frontbuen.' },
  ww_antwerp: { n: 'Beleiringen av Antwerpen', p: 'Antwerpen, Belgia', d: 'Tysklands tunge haubitser knuser Belgias siste festning på ti dager; den belgiske hæren slipper unna langs kysten — og vestfronten strekker seg til Nordsjøen.' },
  ww_ypres_1: { n: 'Det første slaget ved Ypres', p: 'Ypres, Belgia', d: 'Rundt den flamske kledebyen ofres den britiske regulærhæren fra før krigen i kampen om Belgias siste åpne hjørne — de «gamle foraktelige» dør her, og frontbuen ved Ypres blir til.' },
  ww_kolubara: { n: 'Slaget ved Kolubara', p: 'Kolubara, Serbia', d: 'Serbia motangir gjennom vinterens gjørme og gjenerobrer Beograd — Ententens første klare seier over Østerrike-Ungarn, vunnet av veteraner fra to balkankriger.' },
  ww_coronel: { n: 'Slaget ved Coronel', p: 'Utenfor Coronel, Chile', d: 'Graf Spees østasiatiske skvadron senker to britiske panserkryssere utenfor Chiles kyst — Storbritannias første nederlag til sjøs på et århundre — og sender Royal Navy på jakt over halve kloden.' },
  ww_falkland_battle: { n: 'Slaget ved Falklandsøyene', p: 'Falklandsøyene', d: 'Fem uker etter Coronel hevner Sturdees slagkryssere nederlaget: Spees skvadron tilintetgjøres i Sør-Atlanteren, og Tysklands oversjøiske sjøkrig er over.' },
  ww_tsingtao: { n: 'Beleiringen av Tsingtao', p: 'Tsingtao, Kina', d: 'Japan, Storbritannias allierte, stormer Tysklands befestede kinesiske havn — krigens eneste store slag i Øst-Asia, og Japans krav på en stormaktplass ved freden.' },
  ww_christmas_truce: { n: 'Julevåpenhvilen', p: 'Ploegsteert, Belgia', d: 'Langs strekninger av vestfronten møtes tyske og britiske soldater i ingenmannsland — julesanger, sigaretter, fotball — så skremmende for overkommandoene at det aldri får lov å skje igjen.' },
  ww_east_africa: { n: 'Felttoget i Øst-Afrika', p: 'Dar-es-Salaam, Tysk Øst-Afrika', d: 'General von Lettow-Vorbeck binder opp hundretusenvis av allierte soldater i fire år med bushkrigføring — og kapitulerer i Nord-Rhodesia, ubeseiret, elleve dager etter våpenhvilen.' },
  ww_sarikamish: { n: 'Slaget ved Sarıkamış', p: 'Sarıkamış, Kaukasus', d: 'Enver pasjas vinteroffensiv inn i Kaukasus kollapser i snøen — en hær på 90 000 knuses, og krigspropagandaen leter etter noen å skyldne på: armenerne.' },
  ww_dogger_bank: { n: 'Slaget ved Doggerbanken', p: 'Nordsjøen', d: 'Britiske slagkryssere avskjærer et tysk raid mot Yorkshire-kysten og senker panserkrysseren Blücher — det første tegnet på at Hochseeflotten foretrekker havn fremfor slag.' },
  ww_przemysl: { n: 'Beleiringen av Przemyśl', p: 'Przemyśl, Galicia', d: 'Østerrike-Ungarns store galisiske festning faller i mars etter seks måneder — 120 000 fanger, krigens største beleiring — og kanonene er knapt blitt kalde før Gorlice innleder den russiske retretten.' },
  ww_ypres_2: { n: 'Det andre slaget ved Ypres', p: 'Ypres, Belgia', d: 'Klorgass driver over skyttergravene for første gang i historien; kanadiere lukker den brutte linjen — og kjemisk krigføring blir en realitet i det tjuende århundre.' },
  ww_gallipoli: { n: 'Gallipoli-felttoget', p: 'Gallipoli-halvøya, Det osmanske rike', d: 'Ententens forsøk på å tvinge Dardanellene dør på klippene: ANZAC-landingen, ni måneder med stillstand, en kvart million tap — og en hemmelig evakuering som blir et grunnleggende minne for Australia, New Zealand og Tyrkia.' },
  ww_armenian: { n: 'Folkemordet på armenerne', p: 'Konstantinopel, Det osmanske rike', d: '24. april arresterer den osmanske regjeringen Konstantinopels armenske elite og begynner deportasjonene til den syriske ørkenen — rundt en million mennesker dør på veien: det tjuende århundrets første folkemord.' },
  ww_gorlice: { n: 'Gjennombruddsoffensiven ved Gorlice-Tarnów', p: 'Gorlice, Galicia', d: 'Mackensens tysk-østerrikske gjennombrudd river opp den russiske fronten i Galicia — Przemyśl og Lwów gjenerobres i løpet av uker, og tsarens hærer begynner «den store retretten».' },
  ww_lusitania: { n: 'Senkningen av Lusitania', p: 'Utenfor Kinsale, Irland', d: 'En enkelt torpedo sender det store atlanterhavsskipet til bunns på atten minutter — 1 198 døde, 128 av dem amerikanere — og Tysklands første uinnskrenkede ubåtkampanje avblåses under amerikanske protester.' },
  ww_italy_enters: { n: 'Italia går inn i krigen', p: 'Roma, Italia', d: 'Storbritannia kjøper Roma med den hemmelige London-avtalen: Italia erklærer Østerrike-Ungarn krig «for Trento og Trieste» — og åpner en fjellfront som vil koste en million tap.' },
  ww_isonzo: { n: 'De elleve slagene ved Isonzo', p: 'Gorizia, Italia', d: 'Cadornas hærer kaster seg elleve ganger på to år mot karstlandskapet over Isonzo for noen få kilometer med steinete dal — det tolvte forsøket, ved Caporetto, vil gå den andre veien.' },
  ww_warsaw_1915: { n: 'Warszawas fall', p: 'Warszawa, Polen', d: 'Innen august har tsarens hærer oppgitt Warszawa, Vilna og det meste av Polen — fronten stabiliserer seg et års marsj lenger øst, og Russland blir krigens minst pålitelige stormakt.' },
  ww_serbia_1915: { n: 'Serbias fall', p: 'Beograd, Serbia', d: 'Bulgaria slutter seg til sentralmaktene, og tre hærer knuser Serbia på seks uker; den beseirede hæren trekker seg tilbake over de albanske fjellene til Korfu — og Ententens Saloniki-front blir til.' },
  ww_kut: { n: 'Beleiringen av Kut', p: 'Kut, Mesopotamia', d: 'Townshends britisk-indiske divisjon beleires i den mesopotamiske gjørmen i 147 dager; alle unnsetningsforsøk mislykkes — Storbritannias verste ydmykelse i krigen, og halvparten av fangene dør i fangenskap.' },
  ww_verdun: { n: 'Slaget om Verdun', p: 'Verdun, Frankrike', d: '«De skal ikke passere»: Falkenhayns maskin for å blø Frankrike hvitt maler videre i ti måneder i åsene ved Meuse — 700 000 tap, historiens lengste slag, Frankrikes nasjonalepos.' },
  ww_sykes_picot: { n: 'Sykes-Picot-avtalen', p: 'London', d: 'En britisk og en fransk diplomat deler Mellomøsten etter krigen med en blyant — Syria til Paris, Mesopotamia til London — et kart så hemmelig at bolsjevikenes trykking av det i 1917 knuser arabernes tillit.' },
  ww_jutland: { n: 'Jyllandsslaget', p: 'Nordsjøen, ved Jylland', d: 'Den eneste sammenstøtet mellom de store dreadnought-flåtene: 250 skip, 8 600 døde — Tyskland senker mest tonnasje, Storbritannia beholder blokaden, og begge sider gjør krav på havet.' },
  ww_brusilov: { n: 'Brusilov-offensiven', p: 'Luck, Volhynia', d: 'Russlands siste store seier: overraskelsesangrep langs en 500 km lang front i Volhynia og Galicia knuser Østerrike-Ungarns hærer — 400 000 fanger — men tapene bryter tsarens hær ned, og revolusjonen er ett år unna.' },
  ww_arab_revolt: { n: 'Det arabiske opprøret', p: 'Medina, Hijaz', d: 'Sherifen av Mekka gjør opprør mot osmanene med britisk gull og geværer: ørkenraidene og Lawrence rir inn i legenden — og Damaskus loves et hashemittisk kongerike.' },
  ww_somme: { n: 'Slaget ved Somme', p: 'Somme, Frankrike', d: '57 470 britiske tap den første morgenen; stridsvogner dukker opp i september; da novemberegnet gjør slutt på det, ligger en halv million mann døde for ti kilometer av Picardie — krigens varige bilde av bortkastelse.' },
  ww_bucharest: { n: 'Romania går inn i krigen', p: 'Bukarest, Romania', d: 'Bukarest satser på Ententen mens Brusilov rykker frem — og mister alt på fire måneder: Transilvania overrendes, hovedstaden tas i desember, regjeringen i eksil i Iaşi.' },
  ww_zimmermann: { n: 'Zimmermann-telegrammet', p: 'Mexico by, Mexico', d: 'Londons kodeknekkere overleverer Washington Berlins tilbud til Mexico — Texas, Arizona og New Mexico for en allianse; trykt i amerikansk presse gjør det mer enn noen ubåt for å gjøre slutt på USAs nøytralitet.' },
  ww_unrestricted: { n: 'Uinnskrenket ubåtkrig', p: 'Berlin, Tyskland', d: 'Tysklands admiraler lover å sulte ut Storbritannia på fem måneder — og hvert handelsskip i Atlanteren blir et mål, med konsekvenser i Washington de ikke hadde regnet med.' },
  ww_us_enters: { n: 'USA går inn i krigen', p: 'Washington, USA', d: '«Verden må gjøres trygg for demokrati»: Wilson ber Kongressen om krig i april 1917 — to millioner amerikanere krysser Atlanteren, og Ententen får et arsenal som ikke kan tømmes.' },
  ww_nivelle: { n: 'Nivelle-offensiven og mytteriene', p: 'Chemin des Dames, Frankrike', d: 'Nivelle lover gjennombrudd på 48 timer; da miraklet uteblir, nekter halve den franske hæren å angripe mer — 68 divisjoner i mytteri, i det stille dempet av Pétains reformer.' },
  ww_kerensky: { n: 'Kerenskij-offensiven', p: 'Ternopil, Galicia', d: 'Den provisoriske regjeringens siste hasardspill — et angrep i Galicia for å bevise at det revolusjonære Russland fortsatt kjemper; det kollapser i løpet av dager, og hundretusener av desertører bærer geværene hjem til sovjeterne.' },
  ww_riga_1917: { n: 'Erobringen av Riga', p: 'Riga, Latvia', d: 'Tysklands nye stormtropp-taktikk overrunner Riga og deretter de estiske øyene (Operasjon Albion) — en generalprøve på 1918 på en front som allerede er i oppløsning.' },
  ww_passchendaele: { n: 'Det tredje slaget ved Ypres', p: 'Passchendaele, Belgia', d: 'Haigs flandernoffensiv drukner i den våteste høsten på tretti år — en halv million tap på begge sider for åtte kilometer med gjørme; Passchendaele blir krigens ord for meningsløshet.' },
  ww_caporetto: { n: 'Slaget ved Caporetto', p: 'Kobarid (Caporetto), Slovenia', d: 'Tyske fjelltropper og gass driver den italienske andre arméen inn i en 100 km lang flukt — 265 000 fanger; Cadorna avsettes, og Italia holder bare Piave-linjen.' },
  ww_balfour: { n: 'Balfourerklæringen', p: 'London', d: 'Et brev på 67 ord fra den britiske utenriksministeren støtter «et nasjonalt hjem for det jødiske folket» i Palestina — en setning fra krigstidens diplomati hvis konsekvenser fortsatt drøftes hundre år senere.' },
  ww_cambrai: { n: 'Slaget ved Cambrai', p: 'Cambrai, Frankrike', d: 'Nesten 400 stridsvogner og intet forberedende bombardement: 20. november knekker det første masseangrepet med stridsvogner Hindenburg-linjen — og det tyske motangrepet ti dager senere lærer begge sider den nye krigføringens regler.' },
  ww_jerusalem: { n: 'Storbritannia tar Jerusalem', p: 'Jerusalem, Palestina', d: 'Allenby går — ikke rir — inn i den hellige byen 11. desember og avslutter fire århundrer med osmansk styre; Gaza og Bersjeba har allerede falt på veien som skal ende i Damaskus.' },
  ww_brest_litovsk: { n: 'Freden i Brest-Litovsk', p: 'Brest-Litovsk, Hviterussland', d: 'I Brest-festningen slutter sentralmaktene først fred med Den ukrainske folkerepublikken (9. februar, med anerkjennelse av uavhengigheten), deretter med Sovjet-Russland — Tyskland tar en fjerdedel av det gamle imperiet, og mister det innen året er omme.' },
  ww_spring_offensive: { n: 'Tysklands våroffensiv', p: 'Somme, Frankrike', d: 'Ludendorffs fem store angrep — stormtropper, gass, og intet mål utover et gjennombrudd: tyskerne rykker lenger frem enn noensinne siden 1914 og tærer seg opp mot et forsvar som ikke bryter sammen.' },
  ww_czechoslovak_legion: { n: 'Den tsjekkoslovakiske legion', p: 'Tsjeljabinsk, Russland', d: 'Femti tusen tidligere krigsfanger kjemper seg over Sibir etter at sovjeterne prøver å avvæpne dem — besetter den transsibirske jernbanen — og tvinger de allierte til å anerkjenne et uavhengig Tsjekkoslovakia.' },
  ww_marne_2: { n: 'Det andre slaget ved Marne', p: 'Marne, Frankrike', d: 'Det siste tyske angrepet går tom ved Marne igjen — og det allierte motstøtet bringer inn 85 000 ferske amerikanere og hundrevis av lette stridsvogner; fra juli 1918 stopper aldri Ententens fremrykking.' },
  ww_amiens: { n: 'Slaget ved Amiens', p: 'Amiens, Frankrike', d: 'Med stridsvogner, fly og taus sperreild rykker angrepet elleve kilometer frem 8. august — Ludendorffs «den tyske hærs svarte dag»: de hundre dagene ruller videre mot den belgiske grensen.' },
  ww_meuse_argonne: { n: 'Meuse-Argonne-offensiven', p: 'Argonne-skogen, Frankrike', d: '1,25 millioner amerikanske soldater maler seg gjennom Argonne i 47 dager — det største slaget i USAs historie — for å kutte den tyske hærens siste jernbanelinje ut av Frankrike.' },
  ww_megiddo: { n: 'Slaget ved Megiddo', p: 'Megiddo, Palestina', d: 'Allenbys mesterstykke i kombinert våpenbruk tar hele den osmanske hæren i Palestina på 38 dager — Lawrence rir foran inn i Damaskus — og krigen i Mellomøsten ender to måneder før våpenhvilen.' },
  ww_vittorio_veneto: { n: 'Slaget ved Vittorio Veneto', p: 'Vittorio Veneto, Italia', d: 'Italias hevn for Caporetto: den habsburgske fronten går i oppløsning på en uke, og 400 000 overgir seg — Østerrike-Ungarn, i våpen i fire år, undertegner en våpenhvile som egentlig er en oppløsning.' },
  ww_mudros: { n: 'Våpenhvilen i Mudros', p: 'Moudros, Lemnos', d: 'På Lemnos signerer Det osmanske rike krigens slutt 30. oktober — stredene åpnes, og Storbritannias flåte seiler gjennom Dardanellene som den ikke klarte å ta i 1915.' },
  ww_villa_giusti: { n: 'Våpenhvilen i Villa Giusti', p: 'Padua, Italia', d: 'Habsburg-monarkiet undertegner sin våpenhvile i Padua 3. november — men imperiet har allerede oppløst seg i tsjekkoslovakiske, polske, jugoslaviske, ungarske og østerrikske etterfølgerstater.' },
  ww_kiel_mutiny: { n: 'Matrosopprøret i Kiel og novemberrevolusjonen', p: 'Kiel, Tyskland', d: 'Matroser nekter et siste, selvmordsaktig utfall, det røde flagget heises over flåten, råd overtar i hver eneste tysk by — 9. november proklameres republikken, og keiseren rømmer til Holland.' },
  ww_armistice: { n: 'Våpenhvilen 11. november 1918', p: 'Rethondes, Frankrike', d: 'I en jernbanevogn i skogen ved Compiègne undertegner delegasjonene klokken 5.10 om morgenen, og kanonene tier klokken elleve — tjue millioner døde — «en våpenhvile på tjue år», vil Foch si, og tar feil med to måneder.' },
  ww_poland_1918: { n: 'Polen gjenoppstår', p: 'Warszawa, Polen', d: 'Den dagen krigen slutter, overtar Piłsudski kommandoen i Warszawa: etter 123 år med delinger er Polen tilbake på kartet — med grenser som fortsatt må kjempes for.' },
  ww_czechoslovakia: { n: 'Tsjekkoslovakia grunnlegges', p: 'Praha, Tsjekkia', d: '28. oktober overtar den nasjonale komiteen makten i Praha: en republikk av tsjekkere og slovaker, bygget av Masaryk fra Pittsburgh-avtalen til Paris’ anerkjennelse — mellomkrigstidens eneste stabile nye demokrati.' },
  ww_habsburg_end: { n: 'Østerrike-Ungarn oppløses', p: 'Wien, Østerrike', d: 'I de siste ukene av oktober 1918 går imperiets folkeslag rett og slett ut av det — Praha, Zagreb, Budapest og Wien proklamerer egne stater; Habsburg-monarkiet slutter ikke ved traktat, men ved vakuum.' },
  ww_yugoslavia: { n: 'Jugoslavia proklameres', p: 'Beograd, Serbia', d: 'Staten for slovenere, kroater og serbere slås sammen med Serbia 1. desember — et kongerike med tre navn, to alfabeter og fire religioner, satt sammen av ruinene av Østerrike-Ungarn.' },
  ww_russian_civil_war: { n: 'Den russiske borgerkrigen', p: 'Tsaritsyn, Russland', d: 'Røde mot hvite fra Østersjøen til Stillehavet, med et dusin fremmede hærer og den tsjekkiske legionen imellom — tre år, ti millioner døde, og enpartistaten: Sovjetunionen proklameres i 1922.' },
  ww_saint_germain: { n: 'Freden i Saint-Germain', p: 'Saint-Germain-en-Laye, Frankrike', d: 'Østerrike signerer seg ned til en restrepublikk på syv millioner — Sør-Tirol til Italia, Galicia til Polen, Sudetenland til Tsjekkoslovakia — og selve ordet «Anschluss» forbys.' },
  ww_weimar: { n: 'Weimarrepublikken', p: 'Weimar, Tyskland', d: 'Tysklands første demokrati er født av revolusjon og nederlag — en grunnlov som er et vidunder, kvinnelig stemmerett inkludert — men den får skylden for Versailles av sine fiender og forsvarses aldri av sine venner før det er for sent.' },
  ww_neuilly: { n: 'Freden i Neuilly', p: 'Neuilly-sur-Seine, Frankrike', d: 'Bulgaria, den første som gir seg, mister kysten mot Egeerhavet og betaler krigserstatninger — Balkan-kartet justert, og ingenting løst.' },
  ww_league: { n: 'Opprettelsen av Folkeforbundet', p: 'Genève, Sveits', d: 'Pakten trer i kraft i januar 1920: den første verdensorganisasjonen for fred, Wilsons Nobelpris — og, uten USA, en vokter som er for svak for 1930-årene.' },
  ww_trianon: { n: 'Freden i Trianon', p: 'Versailles, Frankrike', d: 'Ungarn mister to tredjedeler av territoriet og seksti prosent av befolkningen til Romania, Tsjekkoslovakia og Jugoslavia — et sår som organiserer ungarsk politikk den dag i dag.' },
  ww_sevres: { n: 'Freden i Sèvres', p: 'Sèvres, Frankrike', d: 'Traktaten som skulle dele opp Anatolia — Smyrna til Hellas, stredene internasjonalisert — undertegnes av en sultan som ikke lenger kontrollerer landet: Kemals Ankara forkaster den, og kampen begynner igjen.' },
  ww_turkish_war: { n: 'Den tyrkiske uavhengighetskrigen', p: 'Ankara, Tyrkia', d: 'Fra Ankara kjemper Mustafa Kemal mot sultanen, grekerne og Ententen til en seier ingen ventet: Republikken Tyrkia proklameres i 1923, og sultanatet avskaffes.' },
  ww_lausanne: { n: 'Freden i Lausanne', p: 'Lausanne, Sveits', d: 'Traktaten som erstatter Sèvres anerkjenner det nye Tyrkia, ratifiserer en gresk-tyrkisk utveksling av 1,6 millioner mennesker, og avslutter det østlige spørsmålet som begynte med Europas syke mann.' },
});

/* ww2 translations — World War II batch (79 entries, 2026-10-31) */
Object.assign(window.DATA_NO, {
  ww2_unit_731: { n: 'Enhet 731', p: 'Pingfang, Mandsjuria', d: 'I et hemmelig anlegg ved Harbin gjør Shiro Ishiis «vannrensningsenhet» pest, miltbrann og kolera om til våpen og tester dem på tusenvis av fanger — og bytter til slutt all data mot straffrihet hos amerikanerne.' },
  ww2_marco_polo: { n: 'Den andre kinesisk-japanske krigen', p: 'Wanping, Kina', d: 'Et nattlig sammenstøt ved Marco Polo-broen 7. juli 1937 trapper opp til Japans fullstendige invasjon av Kina: Shanghai og Nanjing brenner, nasjonalistene trekker seg tilbake oppover Yangtze til Chongqing — en utmattende åtte år lang krig som smelter sammen med den andre verdenskrig.' },
  ww2_nanjing: { n: 'Nanjing-massakren', p: 'Nanjing, Kina', d: 'Japanske styrker stormer den kinesiske hovedstaden og myrder i seks uker: opptil 300 000 soldater og sivile dør, titusenvis av kvinner blir voldtatt — «voldtekten av Nanking» sjokkerer verden.' },
  ww2_anschluss: { n: 'Anschluss', p: 'Wien, Østerrike', d: 'Tyske soldater rykker inn i Østerrike uten motstand og blir møtt med blomster; jødene i Wien tvinges til å skure gatene. Europas kart tegnes om uten at et skudd løsnes.' },
  ww2_munich: { n: 'Münchenavtalen', p: 'München, Tyskland', d: 'Storbritannia og Frankrike overlater Sudetenland til Hitler for å kjøpe «fred i vår tid». Seks måneder senere svelger han resten av Tsjekkoslovakia — appeasement-politikkens emblem og veien til Polen.' },
  ww2_kristallnacht: { n: 'Krystallnatten', p: 'Berlin, Tyskland', d: 'Over hele Riket brenner synagoger, og rundt 7500 jødiske forretninger knuses i én koordinert natt; 30 000 jødiske menn sendes til leire — Holocausts innledende crescendo.' },
  ww2_khalkhin_gol: { n: 'Slagene ved Khalkhin Gol', p: 'Khalkhin Gol, Mongolia', d: 'Zjukovs stridsvogner og artilleri utsletter Japans Kwantung-hær på den mongolske steppen; Tokyo vender sørover mot Stillehavet i stedet for nordover — et valg som former 1941.' },
  ww2_molotov_ribbentrop: { n: 'Molotov–Ribbentrop-pakten', p: 'Moskva, Sovjetunionen', d: 'De to store fiendene signerer en ikke-angrepspakt med en hemmelig protokoll som deler Øst-Europa i interessesfærer — Polen, Baltikum, Bessarabia og Finland tildelt over natten.' },
  ww2_poland_invasion: { n: 'Invasjonen av Polen', p: 'Westerplatte, Danzig, Polen', d: 'Ved daggry åpner det gamle slagskipet Schleswig-Holstein ild mot Westerplatte — de første skuddene i den andre verdenskrig. Blitzkrig, Stuka-bombefly og 1,5 millioner mann knuser Polen på fem uker.' },
  ww2_anglo_french_decl: { n: 'Storbritannia og Frankrike erklærer krig', p: 'London, Storbritannia', d: 'To dager etter at Polen invaderes, forteller Chamberlain radiolytterne at Storbritannia er i krig med Tyskland; Frankrike følger timer senere. Historiens dødeligste konflikt har begynt.' },
  ww2_soviet_poland: { n: 'Den sovjetiske invasjonen av Polen', p: 'Brest, Polen', d: 'Stalin tar sin andel av den hemmelige protokollen: 17. september rykker den røde hær inn i øst-Polen, og en felles tysk-sovjetisk parade markerer den nye grensen i Brest.' },
  ww2_enigma: { n: 'Bletchley Park — knekkingen av Enigma', p: 'Bletchley Park, Storbritannia', d: 'Et hemmelig gods fullt av matematikere, kryssordmestere og verdens første elektroniske datamaskiner knekker Tysklands chiffermaskiner; konvoiene styrer utenom ubåtenes ulveflokker, og krigen forkortes med år.' },
  ww2_atlantic: { n: 'Slaget om Atlanterhavet', p: 'Nord-Atlanteren', d: 'Krigens lengste felttog: ubåtenes ulveflokker mot konvoier, hjelpehangarskip og kodeknekkere om livslinjen som holder Storbritannia mett og den røde hær forsynt — 3500 handelsskip og 783 ubåter går tapt.' },
  ww2_katyn: { n: 'Katyn-massakren', p: 'Katyn, Sovjetunionen', d: 'På Stalins ordre skyter NKVD 22 000 polske offiserer, politimenn og intellektuelle — fra Katyn-skogen til leirene i Starobilsk og Ostashkov — og skylder på tyskerne i femti år.' },
  ww2_dunkirk: { n: 'Evakueringen av Dunkirk', p: 'Dunkirk, Frankrike', d: 'Stengt inne ved Kanalen reddes 338 000 britiske og franske soldater hjem av destroyere, fiskebåter og ekskursjonsdampere — «frigjøringsmirakelet» som holder Storbritannia i krigen.' },
  ww2_france_falls: { n: 'Frankrikes fall', p: 'Compiègne, Frankrike', d: 'Hæren som holdt stand i 1918, kollapser på seks uker; Hitler lar franskmennene signere i samme jernbanevogn der Tyskland kapitulerte i 1918. Halve landet kommer under Vichy-styre.' },
  ww2_vichy: { n: 'Vichy-Frankrike', p: 'Vichy, Frankrike', d: 'Marskalk Pétains kollaborasjonsregime erstatter republikken og sender jøder og dissidenter østover, mens de Gaulle fra London forsikrer at Frankrike har «mistet et slag, ikke krigen».' },
  ww2_battle_of_britain: { n: 'Slaget om Storbritannia', p: 'Sør-England, Storbritannia', d: '«Aldri har så mange skyldt så få så mye»: Spitfire- og Hurricane-jagere og radarkjeden slår Luftwaffe i luftkamper over engelsk himmel — Nazi-Tysklands første strategiske nederlag.' },
  ww2_blitz: { n: 'Blitzen', p: 'London, Storbritannia', d: 'I 57 netter på rad brenner London under tyske bomber, og 43 000 sivile dør i Storbritannia; londonerne sover i undergrunnsstasjonene — og byen fortsetter å fungere.' },
  ww2_greco_italian: { n: 'Den gresk-italienske krigen', p: 'Pindos, Hellas', d: 'Mussolini invaderer Hellas fra Albania 28. oktober «for å matche Hitlers bragder» — og den greske hæren driver italienerne tilbake i fjellene, noe som tvinger Tyskland til å redde sin allierte.' },
  ww2_lend_lease: { n: 'Lend-Lease', p: 'Washington, USA', d: 'Roosevelt gjør USA til «demokratiets arsenal»: rundt 50 milliarder dollar i stridsvogner, lastebiler, mat og flydrivstoff — 400 000 lastebiler og jeeps til den røde hær alene.' },
  ww2_balkans: { n: 'Invasjonen av Jugoslavia og Hellas', p: 'Beograd, Jugoslavia', d: 'Etter at et statskupp i Beograd velter aksepakten, jevner Hitlers Luftwaffe byen med jorden; Wehrmacht feier gjennom Balkan på tre uker — og Europas største partisankrig begynner.' },
  ww2_tobruk: { n: 'Beleiringen av Tobruk', p: 'Tobruk, Libya', d: 'De australske «rottene fra Tobruk» holder festningshavnen i 241 dager mot Rommels Afrikakorps — det første hinderet for Ørkenrevens marsj mot Egypt.' },
  ww2_crete: { n: 'Slaget om Kreta', p: 'Kreta, Hellas', d: 'Det største luftlandslaget hittil: tyske fallskjermjegere erobrer Kreta til en pris som får Hitler til å forby massede fallskjermhopp for alltid — men øya faller, og Egeerhavet blir Aksemaktenes indre hav.' },
  ww2_barbarossa: { n: 'Operasjon Barbarossa', p: 'Brest, Sovjetunionen', d: 'Tre millioner aksetropper invaderer Sovjetunionen på en 2900 km lang front — historiens største invasjon. Fire år og 27 millioner sovjetiske døde senere står den røde hær i Berlin.' },
  ww2_continuation_war: { n: 'Fortsettelseskrigen', p: 'Karelen, Finland', d: 'Finland går til angrep på nytt ved Tysklands side for å vinne tilbake tapte Karelen, rykker frem, og holder deretter tre års skyttergravskrig — og stopper Sovjets store offensiv i 1944 og bevarer sin uavhengighet.' },
  ww2_leningrad: { n: 'Beleiringen av Leningrad', p: 'Leningrad, Sovjetunionen', d: 'I 872 dager blir byen beskutt og sultet ut: brødet rasjonert til 125 gram om dagen, over en million sivile døde, Livets vei over den frosne Ladogasjøen som eneste tråd — og byen overgir seg aldri.' },
  ww2_kyiv_1941: { n: 'Slaget om Kyiv (1941)', p: 'Kyiv, Ukraina', d: 'Historiens største innringing: fire sovjetiske armeer ringes inn øst for Dnipro, og over 600 000 fanger marsjerer inn i tyske leirer. Okkuperte Kyiv gjennomlider massakre — og Guderians sving sørover forsinker fremstøtet mot Moskva.' },
  ww2_moscow: { n: 'Slaget om Moskva', p: 'Moskva, Sovjetunionen', d: 'Tyske spissformasjoner når utkanten av hovedstaden, panikk flakker gjennom Moskva — deretter kommer ferske sibiriske divisjoner med toget, og Zjukov går til motangrep. Blitzkrigen dør i snøen.' },
  ww2_sevastopol: { n: 'Beleiringen av Sevastopol', p: 'Sevastopol, Krim', d: 'Marinefestningen holder stand i 250 dager mot Mansteins 11. armé — med 80 cm-kanonen Dora — før den faller, og Svartehavsflåtens helteby betaler i blod.' },
  ww2_pearl_harbor: { n: 'Angrepet på Pearl Harbor', p: 'Pearl Harbor, Hawaii, USA', d: '«En dato som vil leve i vanære»: 353 japanske hangarskipfly angriper den amerikanske Stillehavsflåten til ankers — 2400 døde, åtte slagskip truffet — og USA går inn i krigen.' },
  ww2_wannsee: { n: 'Wannseekonferansen', p: 'Wannsee, Berlin, Tyskland', d: 'Femten tjenestemenn møtes i en villa ved sjøen i nitti minutter for å koordinere «den endelige løsning»: Europas elleve millioner jøder settes opp til deportasjon og mord.' },
  ww2_singapore: { n: 'Singapores fall', p: 'Singapore', d: '«Den verste katastrofen og den største kapitulasjonen i britisk historie»: 80 000 samveldetropper overgir seg til en mindre japansk styrke som har sykklet ned gjennom Malaya — imperiets prestisje kommer seg aldri.' },
  ww2_bataan: { n: 'Dødsmarsjen på Bataan', p: 'Bataan, Filippinene', d: 'Etter kapitulasjonen på Bataan tvinges 75 000 amerikanske og filippinske fanger til å marsjere 106 km i tropisk hete — tusenvis dør på veien, og frigjøringen er tre år unna.' },
  ww2_coral_sea: { n: 'Slaget i Korallhavet', p: 'Korallhavet', d: 'Det første sjøslaget der flåtene aldri ser hverandre — hangarskipfly angriper over horisonten. Det japanske fremstøtet mot Port Moresby slås tilbake for første gang.' },
  ww2_kharkiv_1942: { n: 'Det andre slaget om Kharkiv', p: 'Kharkiv, Ukraina', d: 'Timosjenkos våroffensiv for å gjenerobre byen går rett i en motfelle: en kvart million sovjetiske soldater går tapt i Barvenkovo-lommen — katastrofen som åpner veien til Don og Stalingrad.' },
  ww2_heydrich: { n: 'Attentatet mot Heydrich — Lidice', p: 'Praha, Tsjekkoslovakia', d: 'Tsjekkiske fallskjermjegere fra operasjon Anthropoid kaster granater inn i «Bøddelens» åpne bil; SS jevner landsbyene Lidice og Ležáky med jorden som gjengjeldelse og deporterer barna deres.' },
  ww2_midway: { n: 'Slaget ved Midway', p: 'Midwayatollen, Stillehavet', d: 'Varslet av kodeknekkere legger amerikanske hangarskip den japanske flåten i bakhold: i fem minutter med stupbombing brenner fire hangarskip — og balansen i Stillehavskrigen snur 4. juni 1942.' },
  ww2_guadalcanal: { n: 'Guadalcanal-felttoget', p: 'Guadalcanal, Salomonøyene', d: 'Seks måneder med jungel, malaria og natlige sjødueller rundt en flueinfestert øy — Amerikas første landoffensiv, der det japanske fremrykket i Stillehavet endelig bryter sammen.' },
  ww2_stalingrad: { n: 'Slaget om Stalingrad', p: 'Stalingrad, Sovjetunionen', d: 'Hvert hus en festning, hver gate et slag: fem måneder med slakting i byruene ender med at 91 000 overlevende fra 6. armé marsjerer inn i fangenskap — vendepunktet i krigen i Europa.' },
  ww2_el_alamein: { n: 'Slaget ved El Alamein', p: 'El Alamein, Egypt', d: 'Montgomerys 8. armé bryter Rommels linje hundre kilometer fra Alexandria — «før Alamein vant vi aldri; etter Alamein tapte vi aldri».' },
  ww2_torch: { n: 'Operasjon Torch', p: 'Algier, Algerie', d: 'Anglo-amerikanske landsettinger tar Rommels hær i ryggen; innen mai 1943 overgir en kvart million akse-soldater seg i Tunisia, og Middelhavet blir de alliertes indre hav.' },
  ww2_manhattan: { n: 'Manhattanprosjektet', p: 'Los Alamos, USA', d: 'I hemmelige laboratorier i New Mexico bygger Oppenheimers team den første atombomben — en innsats på to milliarder dollar med 130 000 mennesker, som skal ende krigen og innlede atomalderen.' },
  ww2_bengal_famine: { n: 'Hungersnøden i Bengal', p: 'Bengal, Britisk India', d: 'Krigens politikk med å beslaglegge båter, hamstring og Churchills kabinetts avvisning av nødforsendelser overlater Bengal til hungersnøden mens krigen raser i Burma — tre millioner mennesker dør.' },
  ww2_koriukivka: { n: 'Koriukivka-tragedien', p: 'Koriukivka, Ukraina', d: 'Som gjengjeldelse for partisanbakhold myrder tyske SS- og ungarske enheter rundt 6700 innbyggere og brenner byen Koriukivka — den største enkeltmassakren av sivile i krigstidens Ukraina.' },
  ww2_khatyn: { n: 'Khatyn-massakren', p: 'Khatyn, Belarus', d: 'En straffepolitibataljon under SS-kommando driver innbyggerne i en belarusisk landsby inn i en låve og brenner dem i live — 149 mennesker, 75 av dem barn; en skjebne som rammet rundt 9200 belarusiske landsbyer.' },
  ww2_warsaw_ghetto: { n: 'Oppstanden i Warszawa-gettoen', p: 'Warszawa, Polen', d: 'Krigens største jødiske opprør: lett bevæpnede kjempere holder SS-panserkjøretøyer unna i nesten en måned før gettoen brenner — kjempet, som overlevende sa, for å dø på egne premisser.' },
  ww2_kursk: { n: 'Slaget om Kursk', p: 'Kursk, Sovjetunionen', d: 'Historiens største panserslag: 6000 stridsvogner støter sammen på steppen idet Hitlers siste østlige offensiv knuses mot forsvarsverk åtte belter dypt — herfra rykker den røde hær frem for godt.' },
  ww2_dnipro: { n: 'Slaget om Dnipro', p: 'Dnipro-elva, Ukraina', d: 'Fem sovjetiske fronter stormer den store elva på en 1400 km lang front — pontongbro etter pontongbro, speidere som erobrer brohoder om natten. Wehrmachts «Østmur» bryter sammen, og veien til Kyiv og vest ligger åpen.' },
  ww2_italy_armistice: { n: 'Italia kapitulerer', p: 'Roma, Italia', d: 'Mussolini settes fra makten og fengsles; Badoglio signerer våpenhvile med de allierte — og Tyskland avvæpner en million italienske soldater i løpet av dager og besetter halve landet.' },
  ww2_kyiv_1943: { n: 'Frigjøringen av Kyiv', p: 'Kyiv, Ukraina', d: '6. november 1943 tar den røde hær Kyiv fra brohodet ved Ljutezj — den første okkuperte republikkshovedstaden som gjenerobres; byen kommer ut av 778 dager med okkupasjon og massakre.' },
  ww2_tehran: { n: 'Teherankonferansen', p: 'Teheran, Iran', d: 'Stalin, Roosevelt og Churchill møtes for første gang: den andre fronten settes til mai 1944, Polens grenser skisseres over middagsbordet — den store alliansen på sitt høydepunkt.' },
  ww2_monte_cassino: { n: 'Slaget om Monte Cassino', p: 'Monte Cassino, Italia', d: 'Fire angrep på fire måneder, et abbedi fra 500-tallet bombet til grus, og til slutt heiser polske soldater sitt flagg over ruinene — Gustav-linjen bryter sammen, og veien til Roma ligger åpen.' },
  ww2_deportations: { n: 'Sovjetiske tvangsdeportasjoner', p: 'Krim og Nord-Kaukasus', d: 'Stalin avskaffer hele folkeslag som erklæres «illojale»: den tsjetsjensk-ingusjiske befolkningen fraktes ut i godsvogner i februar 1944, krimtatarene 18. mai — nesten halvparten dør underveis; hjemme igjen først tiår senere.' },
  ww2_bagration: { n: 'Operasjon Bagration', p: 'Minsk, Belarus', d: 'Tre år på dagen etter Barbarossa tilintetgjør den røde hær Armégruppe Sentrum — 28 divisjoner utslettet på fem uker, Wehrmachts verste nederlag — og fronten flyttes 600 km vestover.' },
  ww2_bretton_woods: { n: 'Bretton Woods-konferansen', p: 'Bretton Woods, USA', d: 'Mens krigen raser, planlegger 44 nasjoner freden: IMF og Verdensbanken blir til, og dollaren blir verdens anker-valuta — etterkrigstidens økonomiske skjelett.' },
  ww2_lviv_1944: { n: 'Lviv–Sandomierz-offensiven', p: 'Lviv, Ukraina', d: 'I juli 1944 knuser sovjetiske armeer Brody-lommen og tar Lviv, og når Wisła i løpet av en måned — Armégruppe Nord-Ukraina knuses, og fronten krysser inn i okkupert Polen.' },
  ww2_wallenberg: { n: 'Raoul Wallenberg i Budapest', p: 'Budapest, Ungarn', d: 'Mens Eichmanns transporter frakter 437 000 ungarske jøder til Auschwitz på åtte uker, utsteder en svensk diplomat beskyttelsespas og gir tusenvis husly i «svenske hus» — titusenvis overlever.' },
  ww2_warsaw_uprising: { n: 'Warszawaoppstanden', p: 'Warszawa, Polen', d: 'Hjemmearméen gjør opprør 1. august for å frigjøre byen før sovjeterne kommer; etter 63 dagers gatekamp er Warszawa rasert og rundt 200 000 polakker døde — mens den røde hær ser på fra andre siden av Wisła.' },
  ww2_paris: { n: 'Frigjøringen av Paris', p: 'Paris, Frankrike', d: 'Leclercs frie franske divisjon og motstandsbevegelsens barrikader frigjør hovedstaden etter fire års okkupasjon; Choltitz kapitulerer uten å tenne på broene, og de Gaulle går nedover Champs-Élysées.' },
  ww2_slovak_uprising: { n: 'Den slovakiske nasjonaloppstanden', p: 'Banská Bystrica, Slovakia', d: 'Den slovakiske hæren vender våpnene mot Tiso-regimet og dets tyske beskytter; to måneder med fjellkamp ender i nederlag — men Slovakia føres inn i de alliertes bok.' },
  ww2_v2: { n: 'V-2 — rakettalderen', p: 'Peenemünde, Tyskland', d: 'Fra hemmelige laboratorier ved Østersjøen faller verdens første ballistiske missil over London og Antwerpen, raskere enn lyden; Hitlers «hevnvåpen» klarer ikke å redde ham — men legger grunnlaget for romfartens tidsalder.' },
  ww2_market_garden: { n: 'Operasjon Market Garden', p: 'Arnhem, Nederland', d: 'En bro for langt: det største luftlandslaget noensinne forsøker å hoppe over Rhinen — og panserstyrkene er i Arnhem. Krigen vil hamre seg gjennom enda en vinter.' },
  ww2_percentages: { n: 'Prosentavtalen', p: 'Moskva, Sovjetunionen', d: 'På et halvt ark papir deler Churchill og Stalin Balkan: Romania nitti prosent sovjetisk, Hellas nitti prosent britisk, Jugoslavia femtifemti — «kunne dette ikke oppfattes som temmelig kynisk?»' },
  ww2_leyte: { n: 'Slaget i Leytebukten', p: 'Leytebukten, Filippinene', d: 'Det største sjøslaget noensinne: fire adskilte slag, de første kamikazeangrepene og den japanske flåtens siste utfall — den keiserlige flåten slutter å være en stridende styrke.' },
  ww2_bulge: { n: 'Ardenneroffensiven', p: 'Ardennene, Belgia', d: 'Hitlers siste hasardspill i vest: panserstyrker veller gjennom de snødekte Ardennene for å kløyve de allierte; Bastogne holder stand — «Nuts!» — og Wehrmacht brenner sine siste reserver.' },
  ww2_vistula_oder: { n: 'Wisła–Oder-offensiven', p: 'Poznań, Polen', d: 'På tre vinteruker rykker den røde hær 500 km frem, fra Wisła til innen 70 km fra Berlin — Schlesien erobret, Warszawa forbi — og den tyske østfronten kommer seg aldri.' },
  ww2_yalta: { n: 'Jaltakonferansen', p: 'Jalta, Krim', d: 'De tre store tegner etterkrigsverdenen i et palass på Krim: okkupasjonssoner i Tyskland, FN, løfter om frie valg i Polen — som aldri holdes. Den kalde krigens kart tegnes her.' },
  ww2_dresden: { n: 'Bombingen av Dresden', p: 'Dresden, Tyskland', d: 'Fire angrep på 36 timer utløser en ildstorm i den flyktningtette «Firenzen ved Elben»; rundt 25 000 dør — og et fast uttrykk for teppebombingens etiske dilemmaer er myntet.' },
  ww2_iwo_jima: { n: 'Slaget om Iwo Jima', p: 'Iwo Jima, Japan', d: 'Et område på knapt 21 kvadratkilometer vulkansk aske koster 26 000 amerikanske tap mot tunnelbaserte forsvarsverk — flagget på Suribachi blir krigens mest berømte fotografi.' },
  ww2_tokyo_fire: { n: 'Brannbombingen av Tokyo', p: 'Tokyo, Japan', d: 'Natten mellom 9. og 10. mars slipper rundt 300 B-29-fly brannbomber over det trebygde Tokyo — rundt 100 000 døde på noen timer, historiens dødeligste luftangrep, et halvt år før atombombene.' },
  ww2_okinawa: { n: 'Slaget om Okinawa', p: 'Okinawa, Japan', d: 'Den siste øya før Japan: 82 dager, 12 000 amerikanske og rundt 100 000 japanske falne, 150 000 okinawanske sivile omkomne, kamikazeangrep i massevis — selve invasjonen av Japan står for døren.' },
  ww2_battle_of_berlin: { n: 'Slaget om Berlin', p: 'Berlin, Tyskland', d: 'To og en halv million sovjetiske soldater tar rikshovedstaden gate for gate; Hitler tar sitt eget liv i bunkeren, og Riksdagsbygningen inntas 30. april — krigen i Europa er dager fra å være over.' },
  ww2_elbe_day: { n: 'Elbe-dagen', p: 'Torgau, Tyskland', d: 'Amerikanske og sovjetiske patruljer tar hverandre i hendene på en krigsherjet bro over Elben — øst og vest har møttes; sjampanjen deles, og kartet over et delt Europa begynner å stivne.' },
  ww2_ve_day: { n: 'Seiersdagen i Europa', p: 'Reims, Frankrike', d: 'Tyskland kapitulerer betingelsesløst — i Reims 7. mai, og igjen i Berlin–Karlshorst for sovjeterne 8. mai. Seks år med krig i Europa ender med titalls millioner døde.' },
  ww2_nagasaki: { n: 'Atombombingen av Nagasaki', p: 'Nagasaki, Japan', d: 'Skydekke over Kokura flytter målet: «Fat Man» detonerer over Urakamidalen i Nagasaki — 40 000 dør umiddelbart, 70 000 innen utgangen av året, og Japans krigsråd brytes endelig sammen.' },
  ww2_japan_surrender: { n: 'Japan kapitulerer', p: 'Tokyobukta, Japan', d: 'På dekket av USS Missouri signerer Japan kapitulasjonserklæringen — historiens dødeligste krig er over: 70–85 millioner døde, og to supermakter står ansikt til ansikt over en herjet verden.' },
  ww2_nuremberg: { n: 'Nürnbergprosessen', p: 'Nürnberg, Tyskland', d: 'Tjuefire naziledere må svare for et internasjonalt tribunal i den utbombede partibyen: forbrytelser mot menneskeheten skrives inn i loven, «ordre ovenfra» slutter å gjelde som forsvar, og tolv henges.' },
  ww2_expulsions: { n: 'Utdrivelsen av tyskerne fra øst', p: 'Øst-Europa', d: 'Historiens største tvangsflytting: 12–14 millioner tyskere drives ut av Polen, Tsjekkoslovakia og Baltikum — en halv million dør på veiene i den «ordnede og humane» overføringen.' },
});
